    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.bomb\nversion: 0.2.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Bomb / Rush\ndescription: Attackers arm the bomb and defend it; defenders must defuse it before it explodes. With team codes, each team arms and defuses with its own keypad code.\nroles:\n  bomb: { requires: [team_input], optional: [keypad, audio, led, display] }\nparams:\n  attackers:          { type: team, default: red }\n  defenders:          { type: team, default: blue }\n  fuse_s:             { type: int, min: 10, max: 3600, default: 300, label: "Fuse (s)" }\n  arm_hold_ms:        { type: int, default: 5000, label: "Hold time to arm (ms)" }\n  defuse_hold_ms:     { type: int, default: 10000, label: "Hold time to defuse (ms)" }\n  reset_after_defuse: { type: bool, default: false, label: "Return to standby after defuse" }\n  auto_arm_after_s:   { type: int, optional: true, label: "Arm automatically after (s)" }\n  team_codes:         { type: string, optional: true, max: 60, gm_only: true, label: "Team codes, e.g. red=1234,blue=5678: the keypad arms (a team\'s code) and defuses (another team\'s code) instead of the buttons" }\ni18n:\n  pt:\n    name: Bomba / Rush\n    description: Os atacantes armam a bomba e defendem-na; os defensores têm de a desarmar antes de explodir. Com códigos de equipa, cada equipa arma e desarma com o seu próprio código no teclado.\n    params:\n      attackers: Atacantes\n      defenders: Defensores\n      fuse_s: Rastilho (s)\n      arm_hold_ms: Tempo a premir para armar (ms)\n      defuse_hold_ms: Tempo a premir para desarmar (ms)\n      reset_after_defuse: Voltar à espera depois de desarmada\n      auto_arm_after_s: Armar automaticamente ao fim de (s)\n      team_codes: "Códigos de equipa, ex.: red=1234,blue=5678: o teclado arma (o código de uma equipa) e desarma (o código de outra equipa) em vez dos botões"\n  de:\n    name: Bombe / Rush\n    description: >-\n      Die Angreifenden machen die Bombe scharf und verteidigen sie; die Verteidigenden müssen sie entschärfen,\n      bevor sie explodiert. Mit Team-Codes macht jedes Team mit seinem eigenen Code am Tastenfeld scharf und\n      entschärft.\n    params:\n      attackers: Angreifende\n      defenders: Verteidigende\n      fuse_s: Zünder (s)\n      arm_hold_ms: Haltezeit zum Schärfen (ms)\n      defuse_hold_ms: Haltezeit zum Entschärfen (ms)\n      reset_after_defuse: Nach dem Entschärfen wieder bereit\n      auto_arm_after_s: Automatisch scharf nach (s)\n      team_codes: "Team-Codes, z. B. red=1234,blue=5678: das Tastenfeld macht scharf (der Code eines Teams) und entschärft (der Code eines anderen Teams) statt der Knöpfe"\n  zh-tw:\n    name: 炸彈 / Rush\n    description: 進攻方啟動炸彈並守住它；防守方必須在爆炸前拆除。使用隊伍密碼時，各隊用自己的密碼在按鍵上啟動與拆除。\n    params:\n      attackers: 進攻方\n      defenders: 防守方\n      fuse_s: 引信（秒）\n      arm_hold_ms: 啟動需按住的時間（毫秒）\n      defuse_hold_ms: 拆除需按住的時間（毫秒）\n      reset_after_defuse: 拆除後回到待命\n      auto_arm_after_s: 自動啟動的時間（秒）\n      team_codes: 隊伍密碼，例如 red=1234,blue=5678：改用按鍵啟動（某一隊的密碼）與拆除（另一隊的密碼），不用按鈕\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Bomb / Rush: attackers arm, defenders defuse before the fuse runs out.\n-- With team codes (params.team_codes, e.g. "red=1234,blue=5678") the keypad\n-- arms and defuses instead of the team buttons: in standby a team\'s code\n-- arms the bomb for that team; once armed, another team\'s code defuses it.\n\nlocal s = state.node { phase = "standby", explode_at = 0, armed_by = nil, defused_by = nil }\nlocal fuse_timer\n\nlocal team_of = {} -- code -> team\nlocal use_codes = false\nfor team, code in string.gmatch(params.team_codes or "", "([^=,%s]+)=(%d+)") do\n  team_of[code] = team\n  use_codes = true\nend\n-- Scripts on this box that read keypad codes list a check here (see the\n-- Codes modifier), so a code meant for another script is not "wrong" here.\nkeypad_codes = keypad_codes or {}\nlocal function mine(c)\n  return team_of[c] ~= nil\nend\nif use_codes then\n  keypad_codes[#keypad_codes + 1] = mine\nend\nlocal typed = ""\nlocal typing -- while a code prompt is up: the timer that gives the screen back to the phase\nlocal note, note_failed -- the prompt\'s message\n-- How far the team holding its button now is with arming or defusing\n-- (0-1), nil while nobody holds: the phase screen shows it as it fills.\nlocal holding\n\n-- The prop\'s screen follows the phase: standby, countdown, defused, exploded.\nlocal function show_countdown()\n  local left = math.ceil(s.explode_at - game.time())\n  if use_codes then\n    ui.screen("countdown", { left = left, team = s.armed_by })\n  else\n    ui.screen("countdown", { left = left, defuse = holding })\n  end\nend\n\nlocal function show_standby()\n  if use_codes then\n    ui.screen("code_entry", { title = "ARM", digits = 0, message = "Enter your team code" })\n  else\n    ui.screen("standby", { arm = params.attackers, progress = holding })\n  end\nend\n\nlocal function show_phase()\n  if typing then\n    cancel(typing)\n  end\n  typed, typing = "", nil\n  if s.phase == "standby" then\n    show_standby()\n  elseif s.phase == "armed" then\n    show_countdown()\n  elseif s.phase == "defused" then\n    ui.screen("defused", { team = s.defused_by })\n  else\n    ui.screen("exploded", { team = s.armed_by })\n  end\nend\n\nlocal function explode()\n  s.phase = "exploded"\n  audio.play("explosion")\n  show_phase()\n  emit("bomb.exploded", { team = s.armed_by }, { prio = "critical" })\nend\n\nlocal function arm(team, how)\n  holding = nil\n  s.phase = "armed"\n  s.armed_by = team\n  s.explode_at = game.time() + params.fuse_s\n  -- The explosion is its own timer, so it lands exactly on time no matter\n  -- when the bomb was armed relative to the display tick below.\n  fuse_timer = after(params.fuse_s, explode)\n  audio.play("armed")\n  show_phase()\n  emit("bomb.armed", { team = team, fuse_s = params.fuse_s, reason = how }, { prio = "critical" })\nend\n\nlocal function defuse(team, how)\n  holding = nil\n  cancel(fuse_timer)\n  audio.play("defused")\n  s.defused_by = team\n  s.phase = params.reset_after_defuse and "standby" or "defused"\n  show_phase()\n  emit("bomb.defused", { team = team, reason = how }, { prio = "critical" })\nend\n\non("game.start", show_standby)\n\n-- After a power loss a box picked for a game on its own gives the state back\n-- (decision HB-7): an armed bomb goes on with the fuse it had left (or\n-- explodes at once when it ran out meanwhile), and the screen shows the\n-- phase again. In a field game the state starts afresh: standby.\non("node.rebooted", function()\n  holding = nil\n  if s.phase == "armed" then\n    local left = s.explode_at - game.time()\n    if left > 0 then\n      fuse_timer = after(left, explode)\n    else\n      return explode()\n    end\n  end\n  show_phase()\nend)\n\n-- The share of a hold, in hundredths, so the screen gets few distinct values.\nlocal function share(ms, total)\n  return math.floor(ms * 100 / total) / 100\nend\n\non("team_input.hold", function(e)\n  if use_codes then\n    return\n  end\n  if s.phase == "standby" and e.team == params.attackers then\n    if e.ms >= params.arm_hold_ms then\n      arm(e.team)\n    else\n      holding = share(e.ms, params.arm_hold_ms)\n      show_standby()\n    end\n  elseif s.phase == "armed" and e.team == params.defenders then\n    if e.ms >= params.defuse_hold_ms then\n      defuse(e.team)\n    else\n      holding = share(e.ms, params.defuse_hold_ms)\n      show_countdown()\n    end\n  end\nend)\n\n-- Letting go early empties the bar.\non("team_input.release", function(e)\n  if holding == nil then\n    return\n  end\n  local holder = (s.phase == "standby" and e.team == params.attackers)\n    or (s.phase == "armed" and e.team == params.defenders)\n  if holder then\n    holding = nil\n    show_phase()\n  end\nend)\n\n-- Team codes: the prompt shows the digits typed (and the fuse while armed).\nlocal function draw()\n  local title = s.phase == "armed" and "DEFUSE" or "ARM"\n  local data = { title = title, digits = #typed, message = note, error = note_failed }\n  if s.phase == "armed" then\n    data.left = math.ceil(s.explode_at - game.time())\n  end\n  ui.screen("code_entry", data)\nend\n\nlocal function prompt(message, failed, linger_s)\n  note, note_failed = message, failed\n  draw()\n  if typing then\n    cancel(typing)\n  end\n  typing = after(linger_s, show_phase)\nend\n\nlocal function enter(c)\n  local team = team_of[c]\n  typed = ""\n  if team == nil then\n    if c ~= "" and keypad_codes and #keypad_codes > 1 then\n      for _, knows in ipairs(keypad_codes) do\n        if knows ~= mine and knows(c) then\n          return show_phase() -- another script\'s code\n        end\n      end\n    end\n    return prompt("Wrong code", true, 3)\n  end\n  if s.phase == "standby" then\n    arm(team, "code")\n  elseif s.phase == "armed" and team ~= s.armed_by then\n    defuse(team, "code")\n  elseif s.phase == "armed" then\n    prompt("Your team armed it", true, 3)\n  else\n    prompt("The bomb is " .. s.phase, true, 3)\n  end\nend\n\non("keypad.key", function(e)\n  if not use_codes then\n    return\n  end\n  local k = e.key\n  if k == "#" then\n    enter(typed)\n  elseif k == "*" then\n    typed = ""\n    prompt(nil, false, 10)\n  elseif string.match(k or "", "^%d\$") and #typed < 8 then\n    typed = typed .. k\n    prompt(nil, false, 10)\n  end\nend)\n\nif params.auto_arm_after_s then\n  after(params.auto_arm_after_s, function()\n    if s.phase == "standby" then\n      arm(params.attackers)\n    end\n  end)\nend\n\nevery(1, function()\n  if s.phase ~= "armed" then\n    return\n  end\n  if typing == nil then\n    show_countdown()\n  else\n    draw()\n  end\nend)\n',
