  'codes': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.codes\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: modifier\nname: Codes\ndescription: >-\n  Keypad codes grant points, hints or unlocks, alongside any main mode on the same box. Each code works\n  once per game. The game master sees every code used, the team it counted for and the team holding the box.\nroles:\n  # On its own (no main mode) the box is a code terminal; added to a main mode, Codes runs on\n  # every box of that mode.\n  terminal: { requires: [keypad], optional: [display, audio] }\nparams:\n  codes:\n    type: string\n    default: ""\n    max: 120\n    gm_only: true\n    label: "Codes: digits:kind[:points][:team], comma-separated; kind is points, hint or unlock (e.g. 4711:points:50,0815:hint,2222:unlock:red)"\ni18n:\n  pt:\n    name: Códigos\n    description: >-\n      Códigos no teclado dão pontos, pistas ou desbloqueios, ao lado de qualquer modo principal na mesma caixa.\n      Cada código funciona uma vez por jogo. O mestre de jogo vê cada código usado, a equipa a que contou e a\n      equipa que tinha a caixa.\n    params:\n      codes: "Códigos: dígitos:tipo[:pontos][:equipa], separados por vírgulas; o tipo é points, hint ou unlock (ex.: 4711:points:50,0815:hint,2222:unlock:red)"\n  de:\n    name: Codes\n    description: >-\n      Codes am Tastenfeld geben Punkte, Hinweise oder Freischaltungen, neben jedem Hauptmodus auf derselben\n      Box. Jeder Code gilt einmal pro Spiel. Die Spielleitung sieht jeden benutzten Code, das Team, für das er\n      zählte, und das Team, das die Box hielt.\n    params:\n      codes: "Codes: Ziffern:Art[:Punkte][:Team], durch Kommas getrennt; Art ist points, hint oder unlock (z. B. 4711:points:50,0815:hint,2222:unlock:red)"\n  zh-tw:\n    name: 密碼\n    description: 在按鍵輸入密碼可得到分數、提示或解鎖，可與同一個盒子上的任何主要模式並用。每個密碼每場遊戲只能用一次。主辦會看到每個用過的密碼、計分的隊伍，以及當時佔有盒子的隊伍。\n    params:\n      codes: "密碼：數字:種類[:分數][:隊伍]，以逗號分隔；種類為 points、hint 或 unlock（例如 4711:points:50,0815:hint,2222:unlock:red）"\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Codes (a modifier): keypad codes grant points, hints or unlocks, alongside\n-- any main mode on the same box. params.codes lists them as\n-- digits:kind[:points][:team], comma-separated, for example\n-- "4711:points:50,0815:hint,2222:unlock:red". Type the digits, then #;\n-- * clears. Each code works once per game. code.used tells the game master\n-- which code (its place in the list), what it gave, the team it counted for\n-- (the code\'s team, else the team holding the box) and the holding team.\n\nlocal codes = {} -- digits -> { id, kind, amount, team }\nlocal used = {}\nlocal kinds = { p = "points", h = "hint", u = "unlock" }\nlocal index = 0\nfor entry in string.gmatch(params.codes or "", "[^,]+") do\n  index = index + 1\n  local f = {}\n  for part in string.gmatch(entry, "[^:%s]+") do\n    f[#f + 1] = part\n  end\n  local kind = f[2] and kinds[string.sub(f[2], 1, 1)]\n  local amount = kind == "points" and math.tointeger(tonumber(f[3] or "")) or nil\n  if\n    f[1]\n    and string.match(f[1], "^%d+\$")\n    and kind\n    and (kind ~= "points" or (amount and amount > 0))\n  then\n    local team = f[3]\n    if kind == "points" then\n      team = f[4]\n    end\n    codes[f[1]] = { id = tostring(index), kind = kind, amount = amount, team = team }\n  else\n    log("codes: entry " .. index .. " is not digits:kind[:points][:team]; it is ignored")\n  end\nend\n\n-- Other scripts on this box that read keypad codes (Bomb\'s team codes) list\n-- a check here, so that a code meant for one of them is not "wrong" here.\nkeypad_codes = keypad_codes or {}\nlocal function mine(c)\n  return codes[c] ~= nil\nend\nkeypad_codes[#keypad_codes + 1] = mine\nlocal function known_elsewhere(c)\n  for _, knows in ipairs(keypad_codes) do\n    if knows ~= mine and knows(c) then\n      return true\n    end\n  end\n  return false\nend\n\n-- The team holding the box: the main mode\'s last capture.\nlocal holder\non("zone.captured", function(e)\n  holder = e.team\nend)\non("zone.neutralized", function()\n  holder = nil\nend)\n\n-- While a code is being typed, this prompt owns the screen: the main mode\'s\n-- screens wait, and the newest one comes back when the prompt closes.\nlocal show = ui.screen\nlocal last -- the main mode\'s newest screen\nlocal open = false\nlocal typed = ""\nlocal closer\n\nui.screen = function(template, data)\n  last = { template, data }\n  if not open then\n    show(template, data)\n  end\nend\n\nlocal function close()\n  open, typed, closer = false, "", nil\n  if last then\n    show(last[1], last[2])\n  else\n    show("code_entry", { title = "CODE", digits = 0 })\n  end\nend\n\nlocal function prompt(message, failed, linger_s)\n  open = true\n  show("code_entry", { title = "CODE", digits = #typed, message = message, error = failed })\n  if closer then\n    cancel(closer)\n  end\n  closer = after(linger_s, close)\nend\n\nlocal function use(c)\n  local code = codes[c]\n  if used[c] then\n    return prompt("Code already used", true, 3)\n  end\n  local team = code.team or holder\n  if code.kind == "points" and team == nil then\n    return prompt("No team holds this box", true, 3)\n  end\n  used[c] = true\n  emit(\n    "code.used",\n    { team = team, code = code.id, kind = code.kind, amount = code.amount, holder = holder }\n  )\n  if code.kind == "points" then\n    score.add(team, code.amount, "code")\n    prompt("+" .. code.amount .. " points for " .. string.upper(team), false, 3)\n  elseif code.kind == "hint" then\n    prompt("Hint: the game master is told", false, 3)\n  else\n    prompt("Unlocked", false, 3)\n  end\nend\n\non("keypad.key", function(e)\n  local k = e.key\n  if k == "#" then\n    local c = typed\n    typed = ""\n    if codes[c] then\n      use(c)\n    elseif c ~= "" and known_elsewhere(c) then\n      close()\n    elseif c ~= "" then\n      prompt("Wrong code", true, 3)\n    end\n  elseif k == "*" then\n    typed = ""\n    prompt(nil, false, 10)\n  elseif string.match(k or "", "^%d\$") and #typed < 8 then\n    typed = typed .. k\n    prompt(nil, false, 10)\n  end\nend)\n\non("game.start", function()\n  if last == nil then\n    show("code_entry", { title = "CODE", digits = 0 })\n  end\nend)\n\non("game.end", function()\n  if closer then\n    cancel(closer)\n  end\n  if open then\n    close()\n  end\nend)\n',
  },
  'domination': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.domination\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Domination\ndescription: The last team to claim the box scores while it holds it.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:          { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick" }\n  points_per_tick: { type: int, min: 1, max: 1000,  default: 1,    label: "Points per tick" }\n# How a box scores while it holds, so a controller can project the points between two STATEs\n# (modes/README.md, "Projected score"): points_per_tick for the owner every tick_s seconds.\nscoring:\n  hold: { every: tick_s, points: points_per_tick }\ni18n:\n  pt:\n    name: Domínio\n    description: A última equipa a capturar a caixa pontua enquanto a tiver.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por intervalo de pontuação\n      points_per_tick: Pontos por intervalo\n  de:\n    name: Domination\n    description: Das letzte Team, das die Box einnimmt, punktet, solange es sie hält.\n    params:\n      capture_hold_ms: Haltezeit zum Einnehmen (ms)\n      tick_s: Sekunden pro Wertungsintervall\n      points_per_tick: Punkte pro Intervall\n  zh-tw:\n    name: 佔點\n    description: 最後佔領盒子的隊伍，在佔有期間持續得分。\n    params:\n      capture_hold_ms: 佔領需按住的時間（毫秒）\n      tick_s: 每次計分間隔（秒）\n      points_per_tick: 每次計分的分數\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Domination (draft): the last team to claim the box scores while it holds it.\n-- Screens (assets/screens/): neutral until the first capture, then captured\n-- (the holding team, its points on this box and when it took it), and\n-- final_score when the game ends.\n\nlocal s = state.node { owner = nil, since = 0 }\n\nlocal function show()\n  if s.owner then\n    ui.screen("captured", { team = s.owner, points = score.get(s.owner), since = s.since })\n  else\n    ui.screen("neutral", {})\n  end\nend\n\non("game.start", show)\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console (decision E7): a team, or none to\n-- free the box. Same as Hold-All and Last Stand; scoring follows the owner.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\nevery(params.tick_s, function()\n  if s.owner then\n    score.add(s.owner, params.points_per_tick, "hold")\n    show()\n  end\nend)\n\n-- The core freezes scores on game.end; show the final result on the prop.\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner, points = s.owner and score.get(s.owner) or nil })\nend)\n',
    'assets/screens/captured.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the zone. Data: team, points (the team\'s on this box),\n# since (game time of the capture, in seconds); lang (pt, en, de or zh-tw) from the box.\ntemplate: captured\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'ZONA OCUPADA\' || lang == \'de\' && \'ZONE BESETZT\' || lang == \'zh-tw\' && \'據點已佔領\' || \'ZONE HELD\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{points} {lang == \'pt\' && \'pontos nesta caixa\' || lang == \'de\' && \'Punkte auf dieser Box\' || lang == \'zh-tw\' && \'分（這個盒子）\' || \'points on this box\'}"\n    style: { font_size: 20 }\n  - type: label\n    text: "{lang == \'pt\' && \'desde\' || lang == \'de\' && \'seit\' || lang == \'zh-tw\' && \'佔領於\' || \'held since\'} {since|clock}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém o botão premido para a tomar\' || lang == \'de\' && \'Halte den Knopf zum Übernehmen\' || lang == \'zh-tw\' && \'按住你的按鈕即可奪取\' || \'Hold your button to take it over\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/final_score.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The game is over. Data: owner (the team holding the zone at the end),\n# points (its points on this box); lang (pt, en, de or zh-tw) from the box.\ntemplate: final_score\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'FIM DO JOGO\' || lang == \'de\' && \'SPIEL VORBEI\' || lang == \'zh-tw\' && \'遊戲結束\' || \'GAME OVER\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'A zona ficou com\' || lang == \'de\' && \'Zone gehalten von\' || lang == \'zh-tw\' && \'據點最後由此隊佔領\' || \'The zone was held by\'}"\n    style: { font_size: 20, color: muted, visible: "{owner}" }\n  - type: label\n    text: "{owner|upper}"\n    style: { font_size: 48, color: "{owner}", visible: "{owner}" }\n  - type: label\n    text: "{points} {lang == \'pt\' && \'pontos nesta caixa\' || lang == \'de\' && \'Punkte auf dieser Box\' || lang == \'zh-tw\' && \'分（這個盒子）\' || \'points on this box\'}"\n    style: { font_size: 20, visible: "{owner}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Nenhuma equipa ficou com a zona\' || lang == \'de\' && \'Kein Team hielt die Zone\' || lang == \'zh-tw\' && \'沒有隊伍佔領據點\' || \'No team held the zone\'}"\n    style: { font_size: 20, color: muted, visible: "{!owner}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Pontuações finais\' || lang == \'de\' && \'Endstand\' || lang == \'zh-tw\' && \'最終分數\' || \'Scores are final\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/neutral.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the zone yet (a running game: decision BN-11; the box\'s own\n# "waiting" screen is before the start). No data of the mode\'s; the hold time\n# comes from the game\'s parameters, lang (pt, en, de or zh-tw) from the box (box_text.h).\ntemplate: neutral\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'ZONA\' || lang == \'de\' && \'ZONE\' || lang == \'zh-tw\' && \'據點\' || \'ZONE\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'LIVRE\' || lang == \'de\' && \'FREI\' || lang == \'zh-tw\' && \'中立\' || \'NEUTRAL\'}"\n    style: { font_size: 48 }\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém premido\' || lang == \'de\' && \'Gedrückt halten\' || lang == \'zh-tw\' && \'按住按鈕\' || \'Hold to capture\'}"\n    style: { font_size: 20, color: accent }\n  - type: label\n    text: "Hold your button for {params.capture_hold_ms / 1000} s"\n    style: { font_size: 14, color: muted, visible: "{lang != \'pt\' && lang != \'de\' && lang != \'zh-tw\'}" }\n  - type: label\n    text: "{params.capture_hold_ms / 1000} s para capturar a zona"\n    style: { font_size: 14, color: muted, visible: "{lang == \'pt\'}" }\n  - type: label\n    text: "{params.capture_hold_ms / 1000} s zum Einnehmen der Zone"\n    style: { font_size: 14, color: muted, visible: "{lang == \'de\'}" }\n  - type: label\n    text: "按住 {params.capture_hold_ms / 1000} 秒即可佔領據點"\n    style: { font_size: 14, color: muted, visible: "{lang == \'zh-tw\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Nenhuma equipa tem esta zona\' || lang == \'de\' && \'Kein Team hält diese Zone\' || lang == \'zh-tw\' && \'目前沒有隊伍佔領此據點\' || \'Nobody holds this zone\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'hacking_terminal': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.hacking_terminal\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Hacking Terminal\ndescription: >-\n  A terminal with a puzzle on its keypad: crack a code from right-place and wrong-place counts, cut the\n  wires in the right order, or repeat a sequence. A wrong answer locks it for a while. Solving it can\n  reveal a code, score points and capture the terminal for the team that solved it; the puzzle comes\n  from the game\'s seed, so a replay sees the same one.\nroles:\n  terminal: { requires: [keypad], optional: [team_input, team_display, display, audio] }\nparams:\n  puzzle:      { type: string, default: code, max: 8, label: "Puzzle: code, wires or sequence" }\n  digits:      { type: int, min: 3, max: 6, default: 4, label: "Length: digits of the code, wires, keys of the sequence" }\n  lockout_s:   { type: int, min: 0, max: 600, default: 10, label: "Seconds the terminal locks after a wrong answer (0: no lock)" }\n  points:      { type: int, min: 0, max: 1000, default: 10, label: "Points for the team that solves it" }\n  reveal_code: { type: string, optional: true, max: 16, gm_only: true, label: "Code shown and sent when it is solved (empty: none)" }\n  capture:     { type: bool, default: false, label: "Solving captures the terminal; another team can hack it back" }\n  team:        { type: team, optional: true, label: "Team credited when nobody pressed a team button first (empty: none)" }\n  lang:        { type: string, default: "", max: 5, label: "Language of the terminal\'s screen: pt, en, de or zh-tw (empty: the game\'s language)" }\ncommands:\n  reset: { roles: [terminal], label: "New puzzle" }\ni18n:\n  pt:\n    name: Hackeia o terminal\n    description: >-\n      Um terminal com um enigma no teclado: descobrir um código pelos algarismos no sítio certo e fora do\n      sítio, cortar os fios pela ordem certa, ou repetir uma sequência. Uma resposta errada bloqueia-o\n      durante algum tempo. Resolvê-lo pode revelar um código, dar pontos e capturar o terminal para a\n      equipa que o resolveu; o enigma vem da semente do jogo, por isso uma repetição vê o mesmo.\n    params:\n      puzzle: "Enigma: code (código), wires (fios) ou sequence (sequência)"\n      digits: "Tamanho: algarismos do código, fios, teclas da sequência"\n      lockout_s: "Segundos de bloqueio depois de uma resposta errada (0: sem bloqueio)"\n      points: Pontos para a equipa que o resolve\n      reveal_code: "Código mostrado e enviado quando é resolvido (vazio: nenhum)"\n      capture: Resolver captura o terminal; outra equipa pode voltar a hackeá-lo\n      team: "Equipa creditada quando ninguém premiu primeiro um botão de equipa (vazio: nenhuma)"\n      lang: "Língua do ecrã do terminal: pt, en, de ou zh-tw (vazio: a língua do jogo)"\n    commands:\n      reset: Novo enigma\n  de:\n    name: Hacking-Terminal\n    description: >-\n      Ein Terminal mit einem Rätsel am Tastenfeld: einen Code anhand der Ziffern an der richtigen und an der\n      falschen Stelle knacken, die Drähte in der richtigen Reihenfolge kappen oder eine Folge wiederholen.\n      Eine falsche Antwort sperrt es eine Weile. Wer es löst, kann einen Code aufdecken, Punkte holen und das\n      Terminal für das eigene Team einnehmen; das Rätsel kommt aus dem Seed des Spiels, eine Wiederholung\n      sieht also dasselbe.\n    params:\n      puzzle: "Rätsel: code (Code), wires (Drähte) oder sequence (Folge)"\n      digits: "Länge: Ziffern des Codes, Drähte, Tasten der Folge"\n      lockout_s: "Sekunden, die das Terminal nach einer falschen Antwort sperrt (0: keine Sperre)"\n      points: Punkte für das Team, das es löst\n      reveal_code: "Code, der beim Lösen gezeigt und gesendet wird (leer: keiner)"\n      capture: Lösen nimmt das Terminal ein; ein anderes Team kann es zurückhacken\n      team: "Team, das zählt, wenn niemand zuerst einen Teamknopf gedrückt hat (leer: keins)"\n      lang: "Sprache des Terminal-Bildschirms: pt, en, de oder zh-tw (leer: die Sprache des Spiels)"\n    commands:\n      reset: Neues Rätsel\n  zh-tw:\n    name: 駭客終端\n    description: 按鍵上有謎題的終端：依「位置對」與「數字對但位置錯」的提示破解密碼（像 1A2B）、依正確順序剪斷電線，或照順序按回一組按鍵。答錯會鎖定一段時間。解開後可揭露一個密碼、得分，並為解開的隊伍佔領終端；謎題來自遊戲的種子，所以重播時會是同一題。\n    params:\n      puzzle: 謎題：code（密碼）、wires（電線）或 sequence（順序）\n      digits: 長度：密碼的位數、電線數、順序的按鍵數\n      lockout_s: 答錯後終端鎖定的秒數（0：不鎖定）\n      points: 解開的隊伍得到的分數\n      reveal_code: 解開時顯示並送出的密碼（空白：無）\n      capture: 解開即佔領終端；別隊可以再駭回去\n      team: 沒有人先按隊伍按鈕時計分的隊伍（空白：無）\n      lang: 終端畫面的語言：pt、en、de 或 zh-tw（留空：使用遊戲的語言）\n    commands:\n      reset: 新謎題\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hacking Terminal: a puzzle on the keypad (decision P4R5; modes/README.md).\n-- code: guess params.digits different digits, then #; the terminal counts\n-- the digits in place and elsewhere (* clears). wires: press the wires\'\n-- numbers in the right order. sequence: a key shows params.digits keys\n-- (1-9), one a second, then type them back (* shows them again). A wrong answer locks it for\n-- params.lockout_s (the wires join again, the sequence is shown again; the\n-- puzzle stays). Puzzles come from rand() (the game\'s seed and the node\'s id),\n-- so a replay gets the same ones. The solving team: the last to press its\n-- button since the last solve, else params.team. Solving\n-- emits hacking.solved, scores params.points and shows params.reveal_code;\n-- with params.capture the terminal becomes that team\'s (zone.captured) and,\n-- after the solved screen, sets a new puzzle for the other teams. The\n-- screens\' texts are in their templates, in params.lang (note: which line).\n\nlocal SOLVED_SHOW_S = 10\n\nlocal puzzle = ({ wires = "wires", sequence = "sequence" })[params.puzzle] or "code" -- or unknown\nlocal n = params.digits\n\nlocal owner, solved -- the team holding a captured terminal; solved, until a new puzzle\nlocal secret -- code: a string of digits; wires and sequence: a list of numbers\nlocal typed, history, tries = "", {}, 0 -- code: the guess, the last three { guess, right, close }\nlocal cut = {} -- wires: cut so far, in order\nlocal phase, step = "idle", 0 -- sequence: idle, show or input; the key shown or typed\nlocal locked_until, hacker, note\nlocal lock_t, tick_t, show_t, again_t = 0, 0, 0, 0 -- timers (cancel(0) does nothing)\n\nlocal function new_puzzle()\n  local list = {}\n  for i = 1, (puzzle == "code" and 10 or n) do\n    list[i] = puzzle == "code" and i - 1 or (puzzle == "wires" and i or rand(1, 9))\n  end\n  if puzzle ~= "sequence" then\n    for i = #list, 2, -1 do\n      local j = rand(1, i)\n      list[i], list[j] = list[j], list[i]\n    end\n  end\n  secret = puzzle == "code" and table.concat(list, "", 1, n) or list\n  typed, history, tries, cut, phase, step, note = "", {}, 0, {}, "idle", 0, nil\nend\n\nlocal function draw()\n  if solved then\n    return\n  end\n  local d = {\n    team = hacker or params.team,\n    owner = owner,\n    locked = locked_until and math.max(1, math.ceil(locked_until - game.time())) or 0,\n    note = note,\n  }\n  if puzzle == "code" then\n    d.typed = (typed .. string.rep("_", n - #typed)):gsub(".", "%0 "):sub(1, 2 * n - 1)\n    d.digits, d.tries, d.note = n, tries, note or "enter"\n    for i, h in ipairs(history) do\n      d["g" .. i], d["r" .. i], d["c" .. i] = h[1], h[2], h[3]\n    end\n    return ui.screen("hack_code", d)\n  end\n  d.of = n\n  if puzzle == "wires" then\n    local w = { 1, 2, 3, 4, 5, 6 }\n    for _, c in ipairs(cut) do\n      w[c] = "-"\n    end\n    d.wires, d.cut = table.concat(w, " ", 1, n), #cut\n    return ui.screen("hack_wires", d)\n  end\n  d.phase, d.step, d.key = phase, step, phase == "show" and secret[step] or nil\n  ui.screen("hack_sequence", d)\nend\n\nlocal function wrong()\n  audio.play("armed") -- the warning tone\n  cut, phase, step = {}, "idle", 0\n  cancel(show_t)\n  if params.lockout_s > 0 then\n    locked_until = game.time() + params.lockout_s\n    lock_t = after(params.lockout_s, function()\n      cancel(tick_t)\n      locked_until = nil\n      draw()\n    end)\n    tick_t = every(1, draw)\n  end\n  draw()\nend\n\nlocal function solve()\n  local team = hacker or params.team\n  cancel(show_t)\n  hacker = nil\n  audio.play("defused") -- the success tone\n  emit("hacking.solved", { team = team, puzzle = puzzle, code = params.reveal_code })\n  if team and params.points > 0 then\n    score.add(team, params.points, "hacking")\n  end\n  local capture = params.capture and team ~= nil\n  ui.screen("hack_solved", { team = team, code = params.reveal_code, capture = capture })\n  solved = true\n  if capture then\n    emit("zone.captured", { team = team, previous_team = owner })\n    owner = team\n    cap("team_display"):show(team)\n    new_puzzle()\n    again_t = after(SOLVED_SHOW_S, function()\n      solved = false\n      draw()\n    end)\n  end\nend\n\n-- The holder of a captured terminal cannot solve it again.\nlocal function mine()\n  if params.capture and owner and (hacker or params.team) == owner then\n    note = "yours"\n    return true\n  end\nend\n\nlocal keys = {}\n\nfunction keys.code(k)\n  if k == "*" then\n    typed = ""\n  elseif k:match("^%d\$") and #typed < n then\n    typed = typed .. k\n  elseif k == "#" and #typed < n then\n    note = "short"\n  elseif k == "#" then\n    local guess = typed\n    typed = ""\n    if mine() then\n      return draw()\n    end\n    tries = tries + 1\n    if guess == secret then\n      return solve()\n    end\n    local right, close, a, b = 0, 0, {}, {}\n    for i = 1, n do\n      local x, y = secret:sub(i, i), guess:sub(i, i)\n      if x == y then\n        right = right + 1\n      else\n        a[x], b[y] = (a[x] or 0) + 1, (b[y] or 0) + 1\n      end\n    end\n    for digit, count in pairs(b) do\n      close = close + math.min(count, a[digit] or 0)\n    end\n    table.insert(history, 1, { guess, right, close })\n    history[4] = nil\n    return wrong()\n  end\n  draw()\nend\n\nfunction keys.wires(k)\n  local w = k:match("^%d\$") and tonumber(k)\n  if not w or w < 1 or w > n then\n    return\n  end\n  for _, c in ipairs(cut) do\n    if c == w then\n      return\n    end\n  end\n  if mine() then\n    return draw()\n  elseif secret[#cut + 1] ~= w then\n    return wrong()\n  end\n  cut[#cut + 1] = w\n  if #cut == n then\n    return solve()\n  end\n  draw()\nend\n\nlocal function show_next()\n  step = step + 1\n  if step > n then\n    cancel(show_t)\n    phase, step = "input", 0\n  end\n  draw()\nend\n\nfunction keys.sequence(k)\n  if phase == "idle" or (phase == "input" and k == "*") then\n    if mine() then\n      return draw()\n    end\n    phase, step = "show", 0\n    show_t = every(1, show_next)\n    return show_next()\n  elseif phase ~= "input" or not k:match("^[1-9]\$") then\n    return\n  elseif secret[step + 1] ~= tonumber(k) then\n    return wrong()\n  end\n  step = step + 1\n  if step == n then\n    return solve()\n  end\n  draw()\nend\n\nlocal function stop_all()\n  cancel(lock_t)\n  cancel(tick_t)\n  cancel(show_t)\n  cancel(again_t)\nend\n\non("game.start", function()\n  new_puzzle()\n  draw()\nend)\n\non("team_input.press", function(e)\n  hacker = e.team\n  draw()\nend)\n\non("keypad.key", function(e)\n  if type(e.key) ~= "string" or solved or locked_until or not secret then\n    return\n  end\n  note = nil\n  keys[puzzle](e.key)\nend)\n\n-- The GM\'s "reset": a new puzzle, unlocked and unsolved; the holder stays.\non("cmd.mode", function(e)\n  if e.name == "reset" then\n    stop_all()\n    locked_until, hacker, solved = nil, nil, false\n    new_puzzle()\n    log("hacking_terminal: new puzzle")\n    draw()\n  end\nend)\n\n-- The GM\'s owner override, when solving captures the terminal.\non("cmd.set_owner", function(e)\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if not params.capture or e.team == owner or (free and owner == nil) then\n    return\n  elseif free then\n    emit("zone.neutralized", { previous_team = owner })\n  else\n    emit("zone.captured", { team = e.team, previous_team = owner })\n  end\n  owner = not free and e.team or nil\n  cap("team_display"):show(owner or "none")\n  draw()\nend)\n\non("game.end", function()\n  stop_all()\n  ui.screen("final_score", { owner = owner })\nend)\n',
    'assets/screens/hack_code.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The code puzzle. Data: team (the team at the keypad, if known), owner (the\n# team holding a captured terminal), typed (the digits typed, "_" for the\n# rest), digits, tries, g1-g3 / r1-r3 / c1-c3 (the last guesses, newest\n# first: the guess, digits in the right place, digits in the code but\n# elsewhere; zh-tw: 1A2B), locked (seconds left of a lock, 0 when open, shown\n# at the bottom instead of the note), note (enter, short for a guess too\n# short, yours when its holder types). Texts in params.lang (pt, en, de, zh-tw).\ntemplate: hack_code\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || owner || \'panel\'}" }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'CRACK THE CODE\' || params.lang == \'de\' && \'KNACK DEN CODE\' || params.lang == \'zh-tw\' && \'破解密碼\' || \'DECIFRA O CÓDIGO\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: label\n    text: "{params.lang == \'zh-tw\' && \'終端：\' || \'Terminal: \'}{owner|upper}"\n    style:\n      font_size: 14\n      color: "{owner}"\n      visible: "{owner}"\n      padding: { top: 4 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{typed}"\n    style: { font_size: 48, color: "{locked && \'muted\' || \'accent\'}" }\n  - type: label\n    text: "{g1}: {r1}{params.lang == \'en\' && \' right, \' || params.lang == \'de\' && \' richtig, \' || params.lang == \'zh-tw\' && \'A\' || \' no sítio, \'}{c1}{params.lang == \'en\' && \' wrong place\' || params.lang == \'de\' && \' falsch\' || params.lang == \'zh-tw\' && \'B\' || \' fora\'}"\n    style: { font_size: 20, visible: "{g1}" }\n  - type: label\n    text: "{g2}: {r2}{params.lang == \'en\' && \' right, \' || params.lang == \'de\' && \' richtig, \' || params.lang == \'zh-tw\' && \'A\' || \' no sítio, \'}{c2}{params.lang == \'en\' && \' wrong place\' || params.lang == \'de\' && \' falsch\' || params.lang == \'zh-tw\' && \'B\' || \' fora\'}"\n    style: { font_size: 14, color: muted, visible: "{g2}" }\n  - type: label\n    text: "{g3}: {r3}{params.lang == \'en\' && \' right, \' || params.lang == \'de\' && \' richtig, \' || params.lang == \'zh-tw\' && \'A\' || \' no sítio, \'}{c3}{params.lang == \'en\' && \' wrong place\' || params.lang == \'de\' && \' falsch\' || params.lang == \'zh-tw\' && \'B\' || \' fora\'}"\n    style: { font_size: 14, color: muted, visible: "{g3}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Type\' || params.lang == \'de\' && \'Tippe\' || params.lang == \'zh-tw\' && \'輸入\' || \'Marca\'} {digits} {params.lang == \'en\' && \'digits, then #\' || params.lang == \'de\' && \'Ziffern, dann #\' || params.lang == \'zh-tw\' && \'位數字再按 #\' || \'algarismos e #\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'enter\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{params.lang == \'en\' && \'The code has\' || params.lang == \'de\' && \'Der Code hat\' || params.lang == \'zh-tw\' && \'密碼有\' || \'O código tem\'} {digits} {params.lang == \'en\' && \'digits\' || params.lang == \'de\' && \'Ziffern\' || params.lang == \'zh-tw\' && \'位數\' || \'algarismos\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'short\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{params.lang == \'en\' && \'Your team holds this terminal\' || params.lang == \'de\' && \'Dein Team hält dieses Terminal\' || params.lang == \'zh-tw\' && \'你的隊伍已佔領這個終端\' || \'O terminal já é da tua equipa\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!locked && note == \'yours\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{params.lang == \'en\' && \'LOCKED\' || params.lang == \'de\' && \'GESPERRT\' || params.lang == \'zh-tw\' && \'鎖定\' || \'BLOQUEADO\'} {locked} {params.lang == \'zh-tw\' && \'秒\' || \'s\'}"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{locked}"\n      padding: { bottom: 8 }\n',
    'assets/screens/hack_sequence.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The sequence puzzle. Data: team (the team at the keypad, if known), owner\n# (the team holding a captured terminal), phase (idle: waiting for a key;\n# show: the sequence is shown; input: the player types it back), key (the key\n# shown), step (the key shown, or the keys typed back so far), of (the\n# sequence\'s length), locked (seconds left of a lock, 0 when open), note\n# (yours when the holder\'s team types). Texts in params.lang (pt, the default,\n# en, de or zh-tw).\ntemplate: hack_sequence\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || owner || \'panel\'}" }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'REPEAT THE SEQUENCE\' || params.lang == \'de\' && \'WIEDERHOLE DIE FOLGE\' || params.lang == \'zh-tw\' && \'照順序按回去\' || \'REPETE A SEQUÊNCIA\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: label\n    text: "{params.lang == \'zh-tw\' && \'終端：\' || \'Terminal: \'}{owner|upper}"\n    style:\n      font_size: 14\n      color: "{owner}"\n      visible: "{owner}"\n      padding: { top: 4 }\n  - type: spacer\n    height: fill\n  # Showing the sequence: the key, and its place in it.\n  - type: label\n    text: "{key}"\n    style: { font_size: 48, color: accent, visible: "{phase == \'show\'}" }\n  - type: label\n    text: "{step} / {of}"\n    style: { font_size: 20, color: muted, visible: "{phase == \'show\'}" }\n  # Typing it back.\n  - type: label\n    text: "{params.lang == \'en\' && \'YOUR TURN\' || params.lang == \'de\' && \'DU BIST DRAN\' || params.lang == \'zh-tw\' && \'換你了\' || \'A TUA VEZ\'}"\n    style: { font_size: 28, color: accent, visible: "{phase == \'input\'}" }\n  - type: progress_bar\n    value: "{step / of}"\n    style: { width: 260, height: 12, color: "{team || \'accent\'}", visible: "{phase == \'input\'}" }\n  - type: label\n    text: "{step} {params.lang == \'en\' && \'of\' || params.lang == \'de\' && \'von\' || params.lang == \'zh-tw\' && \'/\' || \'de\'} {of}"\n    style:\n      font_size: 20\n      visible: "{phase == \'input\'}"\n      padding: { top: 6 }\n  # Waiting, or locked.\n  - type: label\n    text: "{of} {params.lang == \'en\' && \'KEYS\' || params.lang == \'de\' && \'TASTEN\' || params.lang == \'zh-tw\' && \'個按鍵\' || \'TECLAS\'}"\n    style: { font_size: 28, visible: "{phase == \'idle\' && !locked}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'WRONG KEY: LOCKED\' || params.lang == \'de\' && \'FALSCH: GESPERRT\' || params.lang == \'zh-tw\' && \'按錯了：鎖定\' || \'TECLA ERRADA: BLOQUEADO\'} {locked} {params.lang == \'zh-tw\' && \'秒\' || \'s\'}"\n    style: { font_size: 20, color: danger, visible: "{locked}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Your team holds this terminal\' || params.lang == \'de\' && \'Dein Team hält dieses Terminal\' || params.lang == \'zh-tw\' && \'你的隊伍已佔領這個終端\' || \'O terminal já é da tua equipa\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{note == \'yours\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{params.lang == \'en\' && \'Press a key to see the sequence\' || params.lang == \'de\' && \'Drück eine Taste für die Folge\' || params.lang == \'zh-tw\' && \'按任一鍵看順序\' || \'Carrega numa tecla para ver a sequência\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && phase == \'idle\' && !locked}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{params.lang == \'en\' && \'Remember the keys\' || params.lang == \'de\' && \'Merk dir die Tasten\' || params.lang == \'zh-tw\' && \'記住這些按鍵\' || \'Memoriza as teclas\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'show\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/hack_solved.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The puzzle is solved. Data: team (the team that solved it, if known), code\n# (the code it reveals, if the game set one), capture (true when the terminal\n# is now that team\'s and another team can hack it back). Texts in\n# params.lang (pt, the default, en, de or zh-tw).\ntemplate: hack_solved\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{params.lang == \'en\' && \'ACCESS GRANTED\' || params.lang == \'de\' && \'ZUGRIFF ERTEILT\' || params.lang == \'zh-tw\' && \'存取成功\' || \'ACESSO CONCEDIDO\'}"\n    style: { font_size: 28, color: contrast }\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 20, color: contrast, visible: "{team}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'Code\' || params.lang == \'de\' && \'Code\' || params.lang == \'zh-tw\' && \'密碼\' || \'Código\'}"\n    style:\n      font_size: 14\n      color: contrast\n      visible: "{code}"\n      padding: { top: 8 }\n  - type: label\n    text: "{code}"\n    style: { font_size: 48, color: contrast, visible: "{code}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'Another team can hack it back\' || params.lang == \'de\' && \'Ein anderes Team kann es zurückhacken\' || params.lang == \'zh-tw\' && \'別隊可以再駭回去\' || \'Outra equipa pode voltar a hackeá-lo\'}"\n    style: { font_size: 14, color: contrast, visible: "{capture}", padding: 6 }\n',
    'assets/screens/hack_wires.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The wires puzzle. Data: team (the team at the keypad, if known), owner (the\n# team holding a captured terminal), wires (the wires\' numbers, "-" for the\n# ones cut), cut and of (wires cut, of all of them), locked (seconds left of a\n# lock, 0 when open), note (yours when the holder\'s team types). Texts in\n# params.lang (pt, the default, en, de or zh-tw).\ntemplate: hack_wires\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || owner || \'panel\'}" }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'CUT THE WIRES\' || params.lang == \'de\' && \'KAPPE DIE DRÄHTE\' || params.lang == \'zh-tw\' && \'剪斷電線\' || \'CORTA OS FIOS\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: label\n    text: "{params.lang == \'zh-tw\' && \'終端：\' || \'Terminal: \'}{owner|upper}"\n    style:\n      font_size: 14\n      color: "{owner}"\n      visible: "{owner}"\n      padding: { top: 4 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{wires}"\n    style: { font_size: 48, color: "{locked && \'muted\' || \'accent\'}" }\n  - type: progress_bar\n    value: "{cut / of}"\n    style: { width: 260, height: 12, color: "{team || \'accent\'}" }\n  - type: label\n    text: "{cut} {params.lang == \'en\' && \'of\' || params.lang == \'de\' && \'von\' || params.lang == \'zh-tw\' && \'/\' || \'de\'} {of} {params.lang == \'en\' && \'cut\' || params.lang == \'de\' && \'gekappt\' || params.lang == \'zh-tw\' && \'條已剪\' || \'cortados\'}"\n    style:\n      font_size: 20\n      visible: "{!locked}"\n      padding: { top: 6 }\n  - type: label\n    text: "{params.lang == \'en\' && \'WRONG WIRE: LOCKED\' || params.lang == \'de\' && \'FALSCH: GESPERRT\' || params.lang == \'zh-tw\' && \'剪錯了：鎖定\' || \'FIO ERRADO: BLOQUEADO\'} {locked} {params.lang == \'zh-tw\' && \'秒\' || \'s\'}"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{locked}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Your team holds this terminal\' || params.lang == \'de\' && \'Dein Team hält dieses Terminal\' || params.lang == \'zh-tw\' && \'你的隊伍已佔領這個終端\' || \'O terminal já é da tua equipa\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{note == \'yours\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{params.lang == \'en\' && \'Press the number of the wire to cut\' || params.lang == \'de\' && \'Drück die Nummer des Drahts\' || params.lang == \'zh-tw\' && \'按下要剪的電線號碼\' || \'Carrega no número do fio a cortar\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note}"\n      padding: { bottom: 10 }\n',
  },
  'holdall': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.holdall\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Hold-All Domination\ndescription: Teams capture boxes as in Domination, but a team scores only while it holds every box at once.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:          { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while one team holds every box" }\n  points_per_tick: { type: int, min: 1, max: 1000,  default: 1,    label: "Points per tick" }\n  min_zones:       { type: int, min: 1, max: 64,    default: 2,    label: "Boxes in play before anyone can score" }\ni18n:\n  pt:\n    name: Domínio Total\n    description: As equipas capturam caixas como no Domínio, mas uma equipa só pontua enquanto tiver todas as caixas ao mesmo tempo.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por ponto enquanto uma equipa tem todas as caixas\n      points_per_tick: Pontos por intervalo\n      min_zones: Caixas em jogo antes de alguém poder pontuar\n  de:\n    name: Hold-All Domination\n    description: >-\n      Teams nehmen Boxen ein wie bei Domination, aber ein Team punktet nur, solange es alle Boxen gleichzeitig\n      hält.\n    params:\n      capture_hold_ms: Haltezeit zum Einnehmen (ms)\n      tick_s: Sekunden pro Wertungsintervall, solange ein Team alle Boxen hält\n      points_per_tick: Punkte pro Intervall\n      min_zones: Boxen im Spiel, bevor jemand punkten kann\n  zh-tw:\n    name: 全佔點\n    description: 各隊像佔點模式一樣佔領盒子，但只有同時佔有所有盒子的隊伍才會得分。\n    params:\n      capture_hold_ms: 佔領需按住的時間（毫秒）\n      tick_s: 一隊佔有所有盒子時的計分間隔（秒）\n      points_per_tick: 每次計分的分數\n      min_zones: 開始計分前需要在場的盒子數\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on each box: a team captures the box by holding its\n-- input, as in Domination. The box does not score by itself: the field\n-- controller\'s field.lua scores a team only while it holds every box.\n\nlocal s = state.node { owner = nil, since = 0 }\n\n-- The box\'s screen (decision BN-11): the Field Box\'s built-in neutral and captured\n-- screens (screen_renderer.c), as Domination\'s.\nlocal function show()\n  if s.owner then\n    ui.screen("captured", { team = s.owner, since = s.since })\n  else\n    ui.screen("neutral", { hold_s = params.capture_hold_ms // 1000 })\n  end\nend\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\non("game.start", show)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on the field controller: while one team holds every\n-- zone box (and at least params.min_zones of them are in play), it scores\n-- params.points_per_tick every params.tick_s seconds. Box owners come from\n-- the boxes\' STATE reports, which can arrive a little after the capture\n-- event, so the check also runs every second.\n\nlocal fs = state.field { holder = nil }\nlocal tick\n\nlocal function zone_ids()\n  local ids = {}\n  for _, n in ipairs(field.nodes("zone")) do\n    ids[#ids + 1] = n.id\n  end\n  return ids\nend\n\nlocal function check()\n  local ids = zone_ids()\n  local team = nil\n  if #ids >= params.min_zones then\n    team = field.common_owner(ids)\n  end\n  if team == fs.holder then\n    return\n  end\n  if fs.holder ~= nil then\n    cancel(tick)\n    tick = nil\n    emit("holdall.scoring_stop", { team = fs.holder })\n  end\n  fs.holder = team\n  if team ~= nil then\n    emit("holdall.scoring_start", { team = team })\n    -- The first points come one full tick after the last box fell.\n    tick = every(params.tick_s, function()\n      score.add(team, params.points_per_tick, "holdall")\n    end)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'kill_confirmed': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.kill_confirmed\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Kill Confirmed\ndescription: >-\n  Players carry signed NFC tags. A team presses its button at the station and scans the tags it\n  collected: an enemy\'s tag confirms the kill (points for the team, a penalty for the tag\'s team), a\n  teammate\'s tag denies it. Forged tags and tags from another game are refused.\nroles:\n  station: { requires: [nfc, team_input], optional: [display] }\nparams:\n  confirm_points: { type: int, min: 0, max: 100, default: 1, label: "Points for a confirmed kill" }\n  penalty_points: { type: int, min: 0, max: 100, default: 1, label: "Points the killed player\'s team loses" }\n  turn_in_s:      { type: int, min: 3, max: 120, default: 20, label: "Seconds to scan tags after pressing the team button" }\n  retag_after_s:  { type: int, min: 1, max: 3600, default: 60, label: "Seconds before the same player\'s tag counts again" }\ni18n:\n  pt:\n    name: Baixa Confirmada\n    description: >-\n      Cada participante leva uma etiqueta NFC assinada. Uma equipa carrega no seu botão na estação e lê as\n      etiquetas que recolheu: a etiqueta de alguém da equipa adversária confirma a baixa (pontos para a\n      equipa e penalização para a equipa da etiqueta); a de alguém da própria equipa nega-a. Etiquetas\n      falsificadas ou de outro jogo são recusadas.\n    params:\n      confirm_points: Pontos por baixa confirmada\n      penalty_points: Pontos que perde a equipa de quem foi abatido\n      turn_in_s: Segundos para ler etiquetas depois de carregar no botão da equipa\n      retag_after_s: Segundos até a etiqueta da mesma pessoa voltar a contar\n  de:\n    name: Kill Confirmed\n    description: >-\n      Die Spielenden tragen signierte NFC-Tags. Ein Team drückt seinen Knopf an der Station und scannt die\n      gesammelten Tags: der Tag eines Gegners bestätigt den Kill (Punkte für das Team, ein Abzug für das Team\n      des Tags), der Tag eines Teammitglieds verweigert ihn. Gefälschte Tags und Tags aus einem anderen Spiel\n      werden abgelehnt.\n    params:\n      confirm_points: Punkte für einen bestätigten Kill\n      penalty_points: Punkte, die das Team der getroffenen Person verliert\n      turn_in_s: Sekunden zum Scannen der Tags nach dem Teamknopf\n      retag_after_s: Sekunden, bis der Tag derselben Person wieder zählt\n  zh-tw:\n    name: 擊殺確認\n    description: 玩家身上帶著已簽署的 NFC 標籤。隊伍在站點按下自己的按鈕，再感應收集到的標籤：敵人的標籤確認擊殺（該隊得分，標籤所屬的隊伍扣分），隊友的標籤則否決擊殺。偽造的標籤與其他遊戲的標籤會被拒絕。\n    params:\n      confirm_points: 確認擊殺的分數\n      penalty_points: 被擊殺玩家的隊伍扣除的分數\n      turn_in_s: 按下隊伍按鈕後感應標籤的秒數\n      retag_after_s: 同一位玩家的標籤再次計算前的秒數\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Kill Confirmed: players carry signed NFC tags (protocol/nfc-tag.md). A team\n-- presses its button at the station, then scans the tags it collected within\n-- turn_in_s seconds (each scan keeps the station open). An enemy\'s tag\n-- confirms the kill: confirm_points for the team, penalty_points off the\n-- tag\'s team. A teammate\'s tag denies the kill: no points. The same player\'s\n-- tag counts again only after retag_after_s. Forged tags, tags from another\n-- game and tags without a team are refused; the shell checks the signature\n-- with the game key and says why in nfc.tag\'s reason.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal open_team -- the team turning in tags\nlocal closes_at = 0\nlocal closer\nlocal counted = {} -- player -> game time when their tag last counted\nlocal message, failed, fade\n\nlocal function show()\n  local data = { message = message, error = failed }\n  if open_team then\n    data.team = open_team\n    data.left = math.max(0, math.ceil(closes_at - game.time()))\n  end\n  ui.screen("tags", data)\nend\n\n-- A message under the station\'s state, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n    fade = nil\n  end\n  if text then\n    fade = after(4, function()\n      fade = nil\n      message, failed = nil, false\n      show()\n    end)\n  end\nend\n\nlocal function close()\n  open_team, closer = nil, nil\n  say(nil, false)\nend\n\nlocal function open(team)\n  open_team = team\n  closes_at = game.time() + params.turn_in_s\n  if closer then\n    cancel(closer)\n  end\n  closer = after(params.turn_in_s, close)\nend\n\non("game.start", show)\n\non("team_input.press", function(e)\n  open(e.team)\n  say("Scan your tags", false)\nend)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("kill confirmed: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if open_team == nil then\n    return say("Press your team\'s button first", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local last = counted[e.player]\n  if last and game.time() - last < params.retag_after_s then\n    return say("Tag already counted", true)\n  end\n  counted[e.player] = game.time()\n  open(open_team)\n  if e.team == open_team then\n    emit("kill.denied", { team = open_team, player = e.player, owner = e.team })\n    say("Kill denied: " .. e.player, false)\n  else\n    emit("kill.confirmed", { team = open_team, player = e.player, owner = e.team })\n    score.add(open_team, params.confirm_points, "kill")\n    score.add(e.team, -params.penalty_points, "killed")\n    say("Kill confirmed: " .. e.player, false)\n  end\nend)\n\n-- The time left to scan, once a second while the station is open.\nevery(1, function()\n  if open_team then\n    show()\n  end\nend)\n',
    'assets/screens/tags.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The Kill Confirmed station. Data: team (the team turning in tags, while the\n# station is open), left (seconds left to scan), message, error; lang (pt, de, zh-tw,\n# else English) from the box.\ntemplate: tags\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'BAIXA CONFIRMADA\' || lang == \'de\' && \'KILL CONFIRMED\' || lang == \'zh-tw\' && \'擊殺確認\' || \'KILL CONFIRMED\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{!team}" }\n      - type: label\n        text: "{team|upper}{lang == \'pt\' && \': LÊ AS ETIQUETAS\' || lang == \'de\' && \': TAGS SCANNEN\' || lang == \'zh-tw\' && \'：感應標籤\' || \': SCAN TAGS\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Carrega no botão\' || lang == \'de\' && \'Knopf drücken\' || lang == \'zh-tw\' && \'按你的按鈕\' || \'Press your button\'}"\n    style: { font_size: 28, visible: "{!team}" }\n  - type: label\n    text: "{lang == \'pt\' && \'e lê as etiquetas\' || lang == \'de\' && \'dann die Tags scannen\' || lang == \'zh-tw\' && \'然後感應標籤\' || \'then scan the tags\'}"\n    style: { font_size: 20, color: muted, visible: "{!team}" }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: team, visible: "{team}" }\n  - type: progress_bar\n    value: "{left / params.turn_in_s}"\n    style: { width: 240, height: 8, color: team, visible: "{team}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Inimiga confirma, da equipa recusa.\' || lang == \'de\' && \'Gegner-Tag zählt, Team-Tag nicht.\' || lang == \'zh-tw\' && \'敵隊標籤確認，自隊標籤拒絕。\' || \'Enemy tag: confirmed. Team tag: denied.\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'laststand': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.laststand\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Last Stand\ndescription: The defenders start with every zone. Once they are down to their last zone, a countdown to defeat runs until they retake another one.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  attackers:       { type: team, default: red, label: "Attackers (win when the defenders fall)" }\n  defenders:       { type: team, default: blue, label: "Defenders (start with every zone)" }\n  countdown_s:     { type: int, min: 10, max: 3600, default: 120, label: "Countdown to defeat (s)" }\n  last_zones:      { type: int, min: 0, max: 63, default: 1, label: "The countdown runs while the defenders hold this many zones or fewer" }\n  min_zones:       { type: int, min: 1, max: 64, default: 2, label: "Zones in play before the countdown can run" }\n  reset:           { type: bool, default: true, label: "The countdown starts over after a retake (otherwise it carries on where it stopped)" }\n  end_game:        { type: bool, default: true, label: "End the game when the defenders fall" }\ni18n:\n  pt:\n    name: Último Elemento\n    description: Os defensores começam com todas as zonas. Quando ficam reduzidos à última zona, corre uma contagem para a derrota até reconquistarem outra.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      attackers: Atacantes (ganham quando os defensores caem)\n      defenders: Defensores (começam com todas as zonas)\n      countdown_s: Contagem para a derrota (s)\n      last_zones: A contagem corre enquanto os defensores tiverem este número de zonas ou menos\n      min_zones: Zonas em jogo antes de a contagem poder correr\n      reset: A contagem recomeça do início após uma reconquista (senão continua de onde parou)\n      end_game: Terminar o jogo quando os defensores caem\n  de:\n    name: Last Stand\n    description: >-\n      Die Verteidigenden beginnen mit allen Zonen. Sobald sie nur noch ihre letzte Zone haben, läuft ein\n      Countdown zur Niederlage, bis sie eine andere zurückerobern.\n    params:\n      capture_hold_ms: Haltezeit zum Einnehmen (ms)\n      attackers: Angreifende (gewinnen, wenn die Verteidigenden fallen)\n      defenders: Verteidigende (beginnen mit allen Zonen)\n      countdown_s: Countdown zur Niederlage (s)\n      last_zones: Der Countdown läuft, solange die Verteidigenden so viele Zonen oder weniger halten\n      min_zones: Zonen im Spiel, bevor der Countdown laufen kann\n      reset: Der Countdown beginnt nach einer Rückeroberung von vorn (sonst läuft er weiter, wo er stand)\n      end_game: Das Spiel endet, wenn die Verteidigenden fallen\n  zh-tw:\n    name: 最後一人\n    description: 防守方一開始佔有所有據點。防守方只剩最後一個據點時，失敗倒數開始，直到防守方奪回另一個據點為止。\n    params:\n      capture_hold_ms: 佔領需按住的時間（毫秒）\n      attackers: 進攻方（防守方失守時獲勝）\n      defenders: 防守方（一開始佔有所有據點）\n      countdown_s: 失敗倒數（秒）\n      last_zones: 防守方佔有的據點不超過這個數目時開始倒數\n      min_zones: 倒數開始前需要在場的據點數\n      reset: 奪回據點後倒數重新開始（否則從停下的地方繼續）\n      end_game: 防守方失守時結束遊戲\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on each zone box: the defenders hold the box when the game\n-- starts; any team captures it by holding its input. The field controller\'s\n-- field.lua counts the defenders\' zones and runs the countdown to defeat.\n\nlocal s = state.node { owner = nil, since = 0 }\n\n-- The box\'s screen (decision BN-11): the Field Box\'s built-in neutral and captured\n-- screens (screen_renderer.c), as Domination\'s.\nlocal function show()\n  if s.owner then\n    ui.screen("captured", { team = s.owner, since = s.since })\n  else\n    ui.screen("neutral", { hold_s = params.capture_hold_ms // 1000 })\n  end\nend\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\non("game.start", function()\n  if s.owner == nil then\n    capture(params.defenders)\n  end\nend)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on the field controller. Once the defence is set up (the\n-- defenders have held more than params.last_zones zones, or 30 s have\n-- passed: box owners come from STATE reports, which can lag), a countdown of\n-- params.countdown_s seconds runs whenever they hold params.last_zones\n-- zones or fewer. Retaking a zone stops it; it starts over (params.reset)\n-- or carries on where it stopped. When it runs out the defenders are\n-- defeated, and with params.end_game the attackers win the game.\n\nlocal fs = state.field { held = 0, countdown = false, defeated = false }\nlocal ready = false -- the defence is set up\nlocal timer -- the defeat timer, while the countdown runs\nlocal left = params.countdown_s -- seconds the next countdown starts from\nlocal deadline = 0\n\nlocal function defeat()\n  timer = nil\n  fs.countdown = false\n  fs.defeated = true\n  emit("laststand.defeated", { team = params.defenders })\n  if params.end_game then\n    game.win(params.attackers)\n  end\nend\n\nlocal function check()\n  if fs.defeated then\n    return\n  end\n  local zones = field.nodes("zone")\n  local held = 0\n  for _, n in ipairs(zones) do\n    if field.owner(n.id) == params.defenders then\n      held = held + 1\n    end\n  end\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if held > params.last_zones or game.time() >= 30 then\n    ready = true\n  end\n  local danger = ready and #zones >= params.min_zones and held <= params.last_zones\n  if danger and timer == nil then\n    deadline = game.time() + left\n    timer = after(left, defeat)\n    fs.countdown = true\n    emit("laststand.countdown_start", { team = params.defenders, duration_s = math.ceil(left) })\n  elseif not danger and timer ~= nil then\n    cancel(timer)\n    timer = nil\n    fs.countdown = false\n    local remaining = deadline - game.time()\n    emit(\n      "laststand.countdown_cancel",\n      { team = params.defenders, duration_s = math.ceil(remaining) }\n    )\n    left = params.reset and params.countdown_s or math.max(remaining, 0.1)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'master_satellites': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.master_satellites\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Master and Satellites\ndescription: >-\n  Teams capture a master box and its satellites as in Domination. Only the master scores, and the\n  satellites its holder also holds raise its points; when the master changes hands, every satellite goes\n  back to neutral.\nroles:\n  master:    { requires: [team_input], optional: [team_display, audio, display] }\n  satellite: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms:     { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:              { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while a team holds the master" }\n  points_per_tick:     { type: int, min: 1, max: 1000,  default: 2,    label: "Points per tick for the master alone" }\n  satellite_bonus_pct: { type: int, min: 0, max: 1000,  default: 50,   label: "Bonus per satellite held, in % of the master\'s points (rounded down)" }\n  min_satellites:      { type: int, min: 0, max: 63,    default: 0,    label: "Satellites the master\'s holder needs before the master scores" }\ni18n:\n  pt:\n    name: Mestre e Satélites\n    description: >-\n      As equipas capturam uma caixa mestre e os seus satélites como no Domínio. Só a mestre pontua, e os\n      satélites que a mesma equipa tiver aumentam os seus pontos; quando a mestre muda de mãos, todos os\n      satélites voltam a ficar neutros.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por intervalo enquanto uma equipa tem a mestre\n      points_per_tick: Pontos por intervalo só pela mestre\n      satellite_bonus_pct: Bónus por satélite, em % dos pontos da mestre (arredondado para baixo)\n      min_satellites: Satélites de que a equipa da mestre precisa antes de a mestre pontuar\n  de:\n    name: Master und Satelliten\n    description: >-\n      Teams nehmen eine Master-Box und ihre Satelliten ein wie bei Domination. Nur der Master punktet, und die\n      Satelliten, die sein Team auch hält, erhöhen seine Punkte; wechselt der Master den Besitz, werden alle\n      Satelliten wieder frei.\n    params:\n      capture_hold_ms: Haltezeit zum Einnehmen (ms)\n      tick_s: Sekunden pro Wertungsintervall, solange ein Team den Master hält\n      points_per_tick: Punkte pro Intervall für den Master allein\n      satellite_bonus_pct: Bonus pro gehaltenem Satelliten, in % der Master-Punkte (abgerundet)\n      min_satellites: Satelliten, die das Team des Masters braucht, bevor der Master punktet\n  zh-tw:\n    name: 主站與衛星\n    description: 各隊像佔點模式一樣佔領主站盒子與它的衛星。只有主站會得分，佔有主站的隊伍同時佔有的衛星會提高主站的分數；主站易手時，所有衛星都回到中立。\n    params:\n      capture_hold_ms: 佔領需按住的時間（毫秒）\n      tick_s: 一隊佔有主站時的計分間隔（秒）\n      points_per_tick: 主站本身每次計分的分數\n      satellite_bonus_pct: 每個佔有的衛星的加成，主站分數的 %（無條件捨去）\n      min_satellites: 主站開始計分前，佔有主站的隊伍需要的衛星數\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Master and Satellites, on each box (the master and the satellites run the\n-- same script): a team captures the box by holding its input, as in\n-- Domination. Boxes do not score: the field controller\'s field.lua scores the\n-- master\'s holder, with a bonus for the satellites it holds too, and frees\n-- every satellite when the master changes hands. It also tells the master box\n-- how many satellites its holder has (the mode command "status"), so the\n-- master shows them; a box that was never told is a satellite, or a box\n-- picked from its own preset list, and shows only who holds it.\n-- Screens (assets/screens/): neutral, captured, master_status; final_score at\n-- the end (the Field Box\'s built-in screen).\n\nlocal s = state.node { owner = nil, since = 0 }\nlocal master = nil -- the last status from the controller: { held, of, points }\n\nlocal function show()\n  if s.owner == nil then\n    ui.screen("neutral", {})\n  elseif master then\n    ui.screen("master_status", {\n      team = s.owner,\n      since = s.since,\n      held = master.held,\n      of = master.of,\n      points = master.points,\n    })\n  else\n    ui.screen("captured", { team = s.owner, since = s.since })\n  end\nend\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  if master then\n    -- A new holder of the master starts with no satellites (they are freed);\n    -- the controller\'s next status confirms it.\n    master.held, master.points = 0, params.points_per_tick\n  end\n  show()\nend\n\non("game.start", show)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console, and the controller freeing the\n-- satellites: a team, or none to free the box (a free box stays as it is).\non("cmd.set_owner", function(e)\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\n-- From field.lua, to the master box only: its holder\'s satellites and points per tick.\non("cmd.mode", function(e)\n  if e.name ~= "status" or e.team ~= s.owner then\n    return\n  end\n  master = {\n    held = math.tointeger(e.held) or 0,\n    of = math.tointeger(e.of) or 0,\n    points = math.tointeger(e.points) or 0,\n  }\n  show()\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Master and Satellites, on the field controller: while a team holds the\n-- master box, it scores every params.tick_s seconds (the first points one\n-- full tick after the capture): params.points_per_tick, plus\n-- params.satellite_bonus_pct % of that for each satellite it holds too,\n-- rounded down (score.add takes whole points), and nothing while it holds\n-- fewer than params.min_satellites. When the master leaves a team\'s hands\n-- (to another team, or freed by the GM), every satellite is freed. Box owners\n-- come from the boxes\' STATE reports, which can arrive a little after the\n-- capture event, so the check also runs every second. A satellite that\n-- rebooted is freed at the next change of the master, as on the field.\n-- With more than one master box, the first one (the lowest node id) counts.\n\nlocal fs = state.field { master = nil, held = 0 }\nlocal tick\nlocal told -- the last status sent to the master box\n\nlocal function master_id()\n  local m = field.nodes("master")[1]\n  return m and m.id\nend\n\nlocal function satellites_of(team)\n  local held, of = 0, 0\n  for _, n in ipairs(field.nodes("satellite")) do\n    of = of + 1\n    if team ~= nil and field.owner(n.id) == team then\n      held = held + 1\n    end\n  end\n  return held, of\nend\n\nlocal function points(held)\n  if held < params.min_satellites then\n    return 0\n  end\n  return params.points_per_tick + params.points_per_tick * held * params.satellite_bonus_pct // 100\nend\n\nlocal function free_satellites()\n  for _, n in ipairs(field.nodes("satellite")) do\n    field.send(n.id, "set_owner", { team = "none" })\n  end\nend\n\nlocal function check()\n  local id = master_id()\n  local owner = id and field.owner(id)\n  if owner ~= fs.master then\n    if tick then\n      cancel(tick)\n      tick = nil\n    end\n    if fs.master ~= nil then\n      free_satellites()\n    end\n    fs.master = owner\n    told = nil\n    if owner ~= nil then\n      tick = every(params.tick_s, function()\n        local amount = points(satellites_of(owner))\n        if amount > 0 then\n          score.add(owner, amount, "master")\n        end\n      end)\n    end\n  end\n  local held, of = satellites_of(owner)\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if owner ~= nil then\n    local status = owner .. " " .. held .. " " .. of .. " " .. points(held)\n    if status ~= told then\n      told = status\n      field.send(\n        id,\n        "mode",\n        { name = "status", team = owner, held = held, of = of, points = points(held) }\n      )\n    end\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
    'assets/screens/captured.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds a satellite (or a box with no controller). Data: team, since\n# (game time of the capture, in seconds). Boxes do not score: the master does;\n# lang (pt, en, de or zh-tw) from the box.\ntemplate: captured\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'ZONA OCUPADA\' || lang == \'de\' && \'ZONE BESETZT\' || lang == \'zh-tw\' && \'據點已佔領\' || \'ZONE HELD\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{lang == \'pt\' && \'desde\' || lang == \'de\' && \'seit\' || lang == \'zh-tw\' && \'佔領於\' || \'held since\'} {since|clock}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém o botão premido para a tomar\' || lang == \'de\' && \'Halte den Knopf zum Übernehmen\' || lang == \'zh-tw\' && \'按住你的按鈕即可奪取\' || \'Hold your button to take it over\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/master_status.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the master. Data: team, since (game time of the capture, in\n# seconds), held and of (the satellites the team holds, of all of them) and\n# points (the master\'s points per tick with that bonus), from the controller;\n# lang (pt, en, de or zh-tw) from the box.\ntemplate: master_status\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'MASTER OCUPADO\' || lang == \'de\' && \'MASTER BESETZT\' || lang == \'zh-tw\' && \'主站已佔領\' || \'MASTER HELD\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{held} {lang == \'pt\' && \'de\' || lang == \'de\' && \'von\' || lang == \'zh-tw\' && \'/\' || \'of\'} {of} {lang == \'pt\' && \'satélites\' || lang == \'de\' && \'Satelliten\' || lang == \'zh-tw\' && \'個衛星\' || \'satellites\'}"\n    style: { font_size: 20 }\n  - type: label\n    text: "{points} {lang == \'pt\' && \'pontos a cada\' || lang == \'de\' && \'Punkte alle\' || lang == \'zh-tw\' && \'分，每\' || \'points every\'} {params.tick_s} s"\n    style: { font_size: 20, color: "{points > 0 && \'white\' || \'danger\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'desde\' || lang == \'de\' && \'seit\' || lang == \'zh-tw\' && \'佔領於\' || \'held since\'} {since|clock}"\n    style: { font_size: 14, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém o botão premido para a tomar\' || lang == \'de\' && \'Halte den Knopf zum Übernehmen\' || lang == \'zh-tw\' && \'按住你的按鈕即可奪取\' || \'Hold your button to take it over\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/neutral.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the box (a master or a satellite) in a running game (decision\n# BN-11). No data of the mode\'s; the hold time comes from the game\'s\n# parameters, lang (pt, en, de or zh-tw) from the box.\ntemplate: neutral\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'ZONA\' || lang == \'de\' && \'ZONE\' || lang == \'zh-tw\' && \'據點\' || \'ZONE\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'LIVRE\' || lang == \'de\' && \'FREI\' || lang == \'zh-tw\' && \'中立\' || \'NEUTRAL\'}"\n    style: { font_size: 48 }\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém premido\' || lang == \'de\' && \'Gedrückt halten\' || lang == \'zh-tw\' && \'按住按鈕\' || \'Hold to capture\'}"\n    style: { font_size: 20, color: accent }\n  - type: label\n    text: "Hold your button for {params.capture_hold_ms / 1000} s"\n    style: { font_size: 14, color: muted, visible: "{lang != \'pt\' && lang != \'de\' && lang != \'zh-tw\'}" }\n  - type: label\n    text: "{params.capture_hold_ms / 1000} s para capturar a zona"\n    style: { font_size: 14, color: muted, visible: "{lang == \'pt\'}" }\n  - type: label\n    text: "{params.capture_hold_ms / 1000} s zum Einnehmen der Zone"\n    style: { font_size: 14, color: muted, visible: "{lang == \'de\'}" }\n  - type: label\n    text: "按住 {params.capture_hold_ms / 1000} 秒即可佔領據點"\n    style: { font_size: 14, color: muted, visible: "{lang == \'zh-tw\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Nenhuma equipa tem esta zona\' || lang == \'de\' && \'Kein Team hält diese Zone\' || lang == \'zh-tw\' && \'目前沒有隊伍佔領此據點\' || \'Nobody holds this zone\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'medic': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.medic\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\n# A role package: added to any game (org.atalaia.domination+org.atalaia.medic), its role\n# brings medic kits to the field, and a node given that role runs this script alone.\nkind: role\nname: Medic Kit\ndescription: >-\n  A medic kit next to any game. A hit player scans their signed NFC tag and holds a button for a time\n  the organisers set, to be healed; letting go early cancels. The kit has a number of heals and shows\n  how many are left; each player can be healed a limited number of times per game, at every kit, and the\n  GM and the players see every heal. Forged tags, tags from another game and players of a team the kit\n  does not serve are refused, and the screen says why.\nroles:\n  medic: { requires: [nfc, team_input], optional: [display, audio] }\nparams:\n  heal_hold_s:          { type: int, min: 1, max: 120, default: 10, label: "Seconds a player holds the button to be healed" }\n  charges:              { type: int, min: 1, max: 999, default: 5, label: "Heals in the kit" }\n  max_heals_per_player: { type: int, min: 0, max: 100, default: 2, label: "Heals per player in the game, at every kit (0: no limit)" }\n  cooldown_s:           { type: int, min: 0, max: 3600, default: 0, label: "Seconds a player waits between two heals (0: no wait)" }\n  team:                 { type: team, optional: true, label: "Team the kit serves (empty: every team)" }\n  lang:                 { type: string, default: "", max: 5, label: "Language of the kit\'s screen: pt, en, de or zh-tw (empty: the game\'s language)" }\ncommands:\n  refill: { roles: [medic], label: "Refill the kit" }\ni18n:\n  pt:\n    name: Ligaduras\n    description: >-\n      Um kit de primeiros socorros ao lado de qualquer jogo. A pessoa atingida lê a sua etiqueta NFC\n      assinada e mantém premido um botão durante o tempo que a organização definir, para receber o\n      tratamento; largar antes do tempo cancela. O kit tem um número de ligaduras e mostra quantas restam;\n      cada pessoa pode receber um número limitado de tratamentos por jogo, em todos os kits, e a\n      organização e quem joga veem cada tratamento. Etiquetas falsificadas ou de outro jogo, e pessoas de\n      uma equipa que o kit não serve, são recusadas, e o ecrã diz porquê.\n    params:\n      heal_hold_s: Segundos a premir o botão para receber o tratamento\n      charges: Ligaduras no kit\n      max_heals_per_player: "Tratamentos por pessoa no jogo, em todos os kits (0: sem limite)"\n      cooldown_s: "Segundos de espera entre dois tratamentos da mesma pessoa (0: sem espera)"\n      team: "Equipa que o kit serve (vazio: todas)"\n      lang: "Língua do ecrã do kit: pt, en, de ou zh-tw (vazio: a língua do jogo)"\n    commands:\n      refill: Repor as ligaduras\n  de:\n    name: Medic-Kit\n    description: >-\n      Ein Medic-Kit neben jedem Spiel. Wer getroffen wurde, scannt den eigenen signierten NFC-Tag und hält\n      einen Knopf so lange, wie die Orga es festlegt, um behandelt zu werden; zu frühes Loslassen bricht ab.\n      Das Kit hat eine Zahl von Behandlungen und zeigt, wie viele übrig sind; jede Person kann pro Spiel an\n      allen Kits nur begrenzt oft behandelt werden, und die Spielleitung und die Spielenden sehen jede\n      Behandlung. Gefälschte Tags, Tags aus einem anderen Spiel und Spielende eines Teams, dem das Kit nicht\n      dient, werden abgelehnt, und der Bildschirm sagt, warum.\n    params:\n      heal_hold_s: Sekunden, die man zum Behandeln den Knopf hält\n      charges: Behandlungen im Kit\n      max_heals_per_player: "Behandlungen pro Person im Spiel, an allen Kits (0: kein Limit)"\n      cooldown_s: "Sekunden Wartezeit zwischen zwei Behandlungen (0: keine)"\n      team: "Team, dem das Kit dient (leer: alle Teams)"\n      lang: "Sprache des Kit-Bildschirms: pt, en, de oder zh-tw (leer: die Sprache des Spiels)"\n    commands:\n      refill: Kit auffüllen\n  zh-tw:\n    name: 醫護包\n    description: 可搭配任何遊戲的醫護包。中彈的玩家感應自己已簽署的 NFC 標籤，再按住按鈕到主辦設定的時間，即可接受治療；太早放開就會取消。醫護包有固定的治療次數並顯示剩餘次數；每位玩家每場遊戲在所有醫護包合計的治療次數有限，主辦與玩家都看得到每一次治療。偽造的標籤、其他遊戲的標籤，以及醫護包不服務的隊伍的玩家都會被拒絕，畫面會說明原因。\n    params:\n      heal_hold_s: 接受治療需按住按鈕的秒數\n      charges: 醫護包的治療次數\n      max_heals_per_player: 每位玩家每場遊戲的治療次數，所有醫護包合計（0：不限）\n      cooldown_s: 兩次治療之間需等待的秒數（0：不用等）\n      team: 醫護包服務的隊伍（空白：所有隊伍）\n      lang: 醫護包畫面的語言：pt、en、de 或 zh-tw（留空：使用遊戲的語言）\n    commands:\n      refill: 補充醫護包\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Medic Kit (Ligaduras): a hit player scans their signed NFC tag\n-- (protocol/nfc-tag.md), then holds a button for params.heal_hold_s seconds\n-- to be healed; letting go early cancels the heal. The kit holds\n-- params.charges heals and shows how many are left. A player gets at most\n-- params.max_heals_per_player heals in the game (0: no limit), and waits\n-- params.cooldown_s between two of them. With params.team the kit serves\n-- that team only. Every refusal says why on the screen.\n--\n-- A role package (modes/README.md): in a field game the kit\'s node runs this\n-- script alone, next to any main mode. The controller\'s field.lua counts the\n-- heals of every kit and tells the kits ("heals" mode command), so a limit\n-- holds across kits; a kit out of its reach goes on with its own count and\n-- what it was told. The GM refills a kit from the console ("refill").\n\nlocal HOLD_STEP_MS = 250 -- shells send team_input.hold this often (modes/README.md)\nlocal SCAN_WINDOW_S = 15 -- after a scan, the hold must start within this time\nlocal SHOW_S = 4 -- a result stays on the screen this long\n\nlocal tag_refusals = {\n  mac = "mac", -- forged: signed with another key\n  game = "game", -- a tag from another game\n  no_game = "no_game", -- this kit is not in a controller\'s game\n  team = "team", -- a team this game does not have\n}\n\n-- Why a tag or a hold was refused, in the kit\'s language (params.lang).\nlocal reasons = {\n  pt = {\n    mac = "Etiqueta falsificada",\n    game = "Etiqueta de outro jogo",\n    no_game = "Este kit não está num jogo",\n    team = "Equipa desconhecida",\n    not_tag = "Não é uma etiqueta do jogo",\n    wrong_team = "Este kit é de outra equipa",\n    limit = "Chegaste ao limite de tratamentos",\n    cooldown = "Espera %d s",\n    cancelled = "Largaste antes do tempo: lê a etiqueta outra vez",\n    scan_first = "Lê primeiro a tua etiqueta",\n  },\n  en = {\n    mac = "Forged tag",\n    game = "Tag from another game",\n    no_game = "This kit is not in a game",\n    team = "Unknown team",\n    not_tag = "Not a game tag",\n    wrong_team = "This kit is for another team",\n    limit = "You have had all your heals",\n    cooldown = "Wait %d s",\n    cancelled = "Let go too early: scan again",\n    scan_first = "Scan your tag first",\n  },\n  -- German and Traditional Chinese (Taiwan): drafted by an AI model, not yet reviewed\n  -- (docs/translations/status.yaml).\n  de = {\n    mac = "Gefälschter Tag",\n    game = "Tag aus einem anderen Spiel",\n    no_game = "Dieses Kit ist in keinem Spiel",\n    team = "Unbekanntes Team",\n    not_tag = "Kein Tag dieses Spiels",\n    wrong_team = "Dieses Kit gehört einem anderen Team",\n    limit = "Du hast alle Behandlungen gehabt",\n    cooldown = "Warte %d s",\n    cancelled = "Zu früh losgelassen: nochmal scannen",\n    scan_first = "Scanne zuerst deinen Tag",\n  },\n  ["zh-tw"] = {\n    mac = "偽造的標籤",\n    game = "其他遊戲的標籤",\n    no_game = "這個醫護包不在遊戲中",\n    team = "未知隊伍",\n    not_tag = "不是這場遊戲的標籤",\n    wrong_team = "這是別隊的醫護包",\n    limit = "你的治療次數已用完",\n    cooldown = "請等 %d 秒",\n    cancelled = "太早放開了：請再感應一次",\n    scan_first = "請先感應你的標籤",\n  },\n}\nlocal texts = reasons[params.lang] or reasons.pt\n\nlocal s = state.node { charges = params.charges }\nlocal used = {} -- player -> heals in this game: this kit\'s, and those it was told about\nlocal last = {} -- player -> game time (s) of their last heal\nlocal pending -- after a valid scan: { player, team, base } until the heal or a refusal\nlocal window -- the timer that ends the scan\'s wait for a hold\nlocal back -- the timer that brings the idle screen back\n\nlocal function idle()\n  if back then\n    cancel(back)\n    back = nil\n  end\n  if s.charges <= 0 then\n    ui.screen("medic_empty", { team = params.team })\n  else\n    ui.screen("medic_idle", { remaining = s.charges, team = params.team })\n  end\nend\n\n-- A result screen, then the idle screen again after SHOW_S.\nlocal function show(name, data)\n  if back then\n    cancel(back)\n  end\n  ui.screen(name, data)\n  back = after(SHOW_S, function()\n    back = nil\n    idle()\n  end)\nend\n\nlocal function forget()\n  pending = nil\n  if window then\n    cancel(window)\n    window = nil\n  end\nend\n\nlocal function refuse(reason, data)\n  forget()\n  data = data or {}\n  data.reason = reason\n  data.message = string.format(texts[reason], data.wait_s or 0)\n  data.remaining = s.charges\n  log("medic: refused (" .. reason .. ")" .. (data.player and (" for " .. data.player) or ""))\n  show("medic_refused", data)\nend\n\nlocal function heals_of(player)\n  return used[player] or 0\nend\n\nlocal function heal()\n  local p = pending\n  forget()\n  s.charges = s.charges - 1\n  used[p.player] = heals_of(p.player) + 1\n  last[p.player] = game.time()\n  audio.play("healed")\n  emit("medic.heal", {\n    team = p.team,\n    player = p.player,\n    remaining = s.charges,\n    player_heals_used = used[p.player],\n  })\n  show("medic_healed", {\n    player = p.player,\n    team = p.team,\n    remaining = s.charges,\n    used = used[p.player],\n    max = params.max_heals_per_player,\n  })\n  if s.charges <= 0 then\n    emit("medic.empty", { team = params.team })\n  end\nend\n\nlocal function hold_screen(progress)\n  if back then\n    cancel(back)\n    back = nil\n  end\n  ui.screen("medic_hold", {\n    player = pending.player,\n    team = pending.team,\n    progress = progress,\n    left = math.max(0, math.ceil(params.heal_hold_s * (1 - progress))),\n    remaining = s.charges,\n  })\nend\n\non("game.start", idle)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("medic: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    -- unsigned, format and version: not a player tag of this system\n    return refuse(tag_refusals[e.reason] or "not_tag")\n  end\n  local who = { player = e.player, team = e.team }\n  if params.team and e.team ~= params.team then\n    return refuse("wrong_team", who)\n  end\n  if s.charges <= 0 then\n    forget()\n    return idle()\n  end\n  local max = params.max_heals_per_player\n  if max > 0 and heals_of(e.player) >= max then\n    who.used, who.max = heals_of(e.player), max\n    return refuse("limit", who)\n  end\n  local t = last[e.player]\n  if params.cooldown_s > 0 and t and game.time() - t < params.cooldown_s then\n    who.wait_s = math.ceil(params.cooldown_s - (game.time() - t))\n    return refuse("cooldown", who)\n  end\n  forget()\n  pending = { player = e.player, team = e.team }\n  window = after(SCAN_WINDOW_S, function()\n    window = nil\n    pending = nil\n    idle()\n  end)\n  hold_screen(0)\nend)\n\n-- A press after the scan starts the hold from zero; a button already held\n-- when the tag was read counts from its first hold step after the scan.\non("team_input.press", function()\n  if pending then\n    pending.base = 0\n  end\nend)\n\non("team_input.hold", function(e)\n  if not pending then\n    if s.charges > 0 and back == nil then\n      refuse("scan_first")\n    end\n    return\n  end\n  if window then\n    cancel(window)\n    window = nil\n  end\n  if pending.base == nil then\n    pending.base = math.max(0, e.ms - HOLD_STEP_MS)\n  end\n  local progress = (e.ms - pending.base) / (params.heal_hold_s * 1000)\n  if progress >= 1 then\n    heal()\n  else\n    hold_screen(progress)\n  end\nend)\n\non("team_input.release", function()\n  if pending and pending.base ~= nil then\n    refuse("cancelled", { player = pending.player, team = pending.team })\n  end\nend)\n\n-- Mode commands (CMD opcode 8): the controller\'s count of a player\'s heals\n-- at every kit, and the GM\'s refill.\non("cmd.mode", function(e)\n  if e.name == "heals" and type(e.player) == "string" then\n    local n = math.tointeger(e.used) or 0\n    if n > heals_of(e.player) then\n      used[e.player] = n\n    end\n    if type(e.at) == "number" and (last[e.player] == nil or e.at > last[e.player]) then\n      last[e.player] = e.at\n    end\n  elseif e.name == "refill" then\n    s.charges = params.charges\n    log("medic: refilled to " .. s.charges)\n    forget()\n    idle()\n  end\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Medic Kit, on the field controller: counts every kit\'s heals per player for\n-- the whole game and tells the kits ("heals" mode command), so a player with a\n-- limit of 2 is not healed twice at every kit. A kit out of reach heals with\n-- its own count; its medic.heal arrives later (the box resends it) and carries\n-- the count the kit knew, so the total here is the larger of the two. A kit\n-- that rebooted is told every count again.\n\nlocal used = {} -- player -> heals in the game, at every kit\nlocal last = {} -- player -> game time (s) the controller heard of their last heal\n\nlocal function tell(node_id, player)\n  field.send(\n    node_id,\n    "mode",\n    { name = "heals", player = player, used = used[player], at = last[player] }\n  )\nend\n\non("medic.heal", function(e)\n  if type(e.player) ~= "string" then\n    return\n  end\n  local n = (used[e.player] or 0) + 1\n  local kit_knew = math.tointeger(e.player_heals_used) or 0\n  if kit_knew > n then\n    n = kit_knew\n  end\n  -- Whole seconds keep the command short (a box takes 127 bytes of parameters).\n  used[e.player], last[e.player] = n, math.floor(game.time())\n  for _, kit in ipairs(field.nodes("medic")) do\n    -- The kit that healed knows its own count unless it was behind.\n    if kit.id ~= e.node or kit_knew < n then\n      tell(kit.id, e.player)\n    end\n  end\nend)\n\non("node.rebooted", function(e)\n  for _, kit in ipairs(field.nodes("medic")) do\n    if kit.id == e.node then\n      for player in pairs(used) do\n        tell(kit.id, player)\n      end\n    end\n  end\nend)\n',
    'assets/screens/medic_empty.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The kit has no heals left until the organisers refill it. Data: team (the\n# team the kit serves, if one). Texts in params.lang (pt, the default, en, de or\n# zh-tw).\ntemplate: medic_empty\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'MEDIC KIT\' || params.lang == \'de\' && \'MEDIC-KIT\' || params.lang == \'zh-tw\' && \'醫護包\' || \'LIGADURAS\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "0"\n    style: { font_size: 48, color: danger }\n  - type: label\n    text: "{params.lang == \'en\' && \'The kit is empty\' || params.lang == \'de\' && \'Das Kit ist leer\' || params.lang == \'zh-tw\' && \'醫護包已用完\' || \'Sem ligaduras\'}"\n    style: { font_size: 28, color: danger }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'The organisers can refill it\' || params.lang == \'de\' && \'Die Orga kann es auffüllen\' || params.lang == \'zh-tw\' && \'主辦可以補充醫護包\' || \'A organização pode repor o kit\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_healed.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A heal is done. Data: player, team (the player\'s), remaining (heals left\n# in the kit), used (the player\'s heals in this game), max (heals a player\n# may have; 0: no limit). Texts in params.lang (pt, the default, en, de or\n# zh-tw).\ntemplate: medic_healed\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: plus\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{params.lang == \'en\' && \'BACK IN THE GAME\' || params.lang == \'de\' && \'ZURÜCK IM SPIEL\' || params.lang == \'zh-tw\' && \'回到遊戲\' || \'DE VOLTA AO JOGO\'}"\n    style: { font_size: 28, color: contrast }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20, color: contrast }\n  - type: label\n    text: "{params.lang == \'en\' && \'Heal\' || params.lang == \'de\' && \'Behandlung\' || params.lang == \'zh-tw\' && \'第\' || \'Tratamento\'} {used} {params.lang == \'en\' && \'of\' || params.lang == \'de\' && \'von\' || params.lang == \'zh-tw\' && \'次，共\' || \'de\'} {max}{params.lang == \'zh-tw\' && \' 次\' || \'\'}"\n    style: { font_size: 20, color: contrast, visible: "{max > 0}" }\n  - type: label\n    text: "Restam {remaining} ligaduras"\n    style: { font_size: 14, color: contrast, visible: "{params.lang != \'en\' && params.lang != \'de\' && params.lang != \'zh-tw\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: Resta 1 ligadura\n    style: { font_size: 14, color: contrast, visible: "{params.lang != \'en\' && params.lang != \'de\' && params.lang != \'zh-tw\' && remaining == 1}", padding: 6 }\n  - type: label\n    text: "{remaining} heals left in the kit"\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'en\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: 1 heal left in the kit\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'en\' && remaining == 1}", padding: 6 }\n  - type: label\n    text: "Noch {remaining} Verbände im Kit"\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'de\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: Noch 1 Verband im Kit\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'de\' && remaining == 1}", padding: 6 }\n  - type: label\n    text: "醫護包還剩 {remaining} 次"\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'zh-tw\'}", padding: 6 }\n',
    'assets/screens/medic_hold.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A player\'s tag was read: the heal fills up while the button is held.\n# Data: player, team (the player\'s), progress (0-1), left (seconds still to\n# hold), remaining (heals left in the kit). Texts in params.lang (pt, the\n# default, en, de or zh-tw).\ntemplate: medic_hold\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{player}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Keep holding to heal\' || params.lang == \'de\' && \'Halten zum Behandeln\' || params.lang == \'zh-tw\' && \'按住以治療\' || \'Mantém premido para tratar\'}"\n    style: { font_size: 20, width: 300, align: center }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: accent }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 260, height: 14, color: "{team || \'accent\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Letting go early cancels\' || params.lang == \'de\' && \'Zu früh loslassen bricht ab\' || params.lang == \'zh-tw\' && \'太早放開就會取消\' || \'Largar antes do tempo cancela\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_idle.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The kit waits for a player\'s tag. Data: remaining (heals left), team (the\n# team the kit serves, if one). The texts follow the game\'s params.lang\n# (pt, the default, en, de or zh-tw).\ntemplate: medic_idle\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'MEDIC KIT\' || params.lang == \'de\' && \'MEDIC-KIT\' || params.lang == \'zh-tw\' && \'醫護包\' || \'LIGADURAS\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{remaining}"\n    style: { font_size: 48, color: "{remaining <= 1 && \'orange\' || \'white\'}" }\n  - type: label\n    text: "Restam {remaining} ligaduras"\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\' && params.lang != \'de\' && params.lang != \'zh-tw\' && remaining != 1}" }\n  - type: label\n    text: Resta 1 ligadura\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\' && params.lang != \'de\' && params.lang != \'zh-tw\' && remaining == 1}" }\n  - type: label\n    text: "{remaining} heals left"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\' && remaining != 1}" }\n  - type: label\n    text: 1 heal left\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\' && remaining == 1}" }\n  - type: label\n    text: "Noch {remaining} Verbände"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'de\' && remaining != 1}" }\n  - type: label\n    text: Noch 1 Verband\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'de\' && remaining == 1}" }\n  - type: label\n    text: "還剩 {remaining} 次"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'zh-tw\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Scan your tag\' || params.lang == \'de\' && \'Scanne deinen Tag\' || params.lang == \'zh-tw\' && \'感應你的標籤\' || \'Lê a tua etiqueta\'}"\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: "{params.lang == \'en\' && \'then hold the button\' || params.lang == \'de\' && \'und halte den Knopf\' || params.lang == \'zh-tw\' && \'再按住按鈕\' || \'e mantém premido o botão\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_refused.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A tag or a hold was refused. Data: reason (mac, game, no_game, team,\n# not_tag, wrong_team, limit, cooldown, cancelled, scan_first), message (the\n# reason in params.lang, from the script), player and team (when the tag was\n# a player\'s), remaining (heals left in the kit).\ntemplate: medic_refused\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "danger" }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'REFUSED\' || params.lang == \'de\' && \'ABGELEHNT\' || params.lang == \'zh-tw\' && \'已拒絕\' || \'RECUSADO\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: icon\n    icon: close\n    style: { font_size: 48, color: danger }\n  - type: label\n    text: "{message}"\n    style: { font_size: 20, width: 300, align: center }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20, color: "{team || \'muted\'}", visible: "{player}" }\n  - type: spacer\n    height: fill\n',
  },
  'money_factory': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.money_factory\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Money Factory\ndescription: >-\n  Teams capture factory boxes, which make money while they hold them. Players collect it by scanning\n  their signed NFC tag at their team\'s factory, carry it across the field and bank it by scanning their\n  tag at a bank box: money banked is points. The controller keeps what each player carries, so the\n  money can be collected at one box and banked at another. A player healed at a medic kit loses what\n  they carry, and a team that banks the target wins.\nroles:\n  factory: { requires: [nfc, team_input], optional: [team_display, display, audio] }\n  bank:    { requires: [nfc], optional: [display, audio] }\nparams:\n  production:      { type: int, min: 1, max: 1000, default: 1, label: "Money a factory makes each tick" }\n  tick_s:          { type: int, min: 1, max: 600, default: 10, label: "Seconds per tick of a factory" }\n  capacity:        { type: int, min: 1, max: 10000, default: 50, label: "Most money a factory holds" }\n  carry_max:       { type: int, min: 0, max: 10000, default: 20, label: "Most money a player carries (0: no limit)" }\n  capture:         { type: bool, default: true, label: "Teams capture the factories: a factory makes money only while held, and only its team collects (off: always, and anyone)" }\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture a factory (ms)" }\n  target:          { type: int, min: 0, max: 100000, default: 0, label: "Money a team banks to win the game (0: no end)" }\n  drop_on_heal:    { type: bool, default: true, label: "A player healed at a medic kit loses the money they carry" }\ni18n:\n  pt:\n    name: Fábrica de Dinheiro\n    description: >-\n      As equipas capturam caixas-fábrica, que fazem dinheiro enquanto as tiverem. Quem joga recolhe-o\n      lendo a sua etiqueta NFC assinada na fábrica da sua equipa, leva-o pelo campo e deposita-o lendo a\n      etiqueta numa caixa-banco: o dinheiro depositado são pontos. O controlador guarda o que cada pessoa\n      leva, por isso o dinheiro pode ser recolhido numa caixa e depositado noutra. Quem recebe tratamento\n      num kit de ligaduras perde o que leva, e a equipa que depositar o objetivo ganha.\n    params:\n      production: Dinheiro que uma fábrica faz por intervalo\n      tick_s: Segundos por intervalo de uma fábrica\n      capacity: Máximo de dinheiro numa fábrica\n      carry_max: "Máximo de dinheiro que cada pessoa leva (0: sem limite)"\n      capture: "As equipas capturam as fábricas: uma fábrica só faz dinheiro enquanto tiver equipa, e só essa equipa recolhe (desligado: sempre, e qualquer pessoa)"\n      capture_hold_ms: Tempo a premir para capturar uma fábrica (ms)\n      target: "Dinheiro que uma equipa deposita para ganhar o jogo (0: sem fim)"\n      drop_on_heal: Quem recebe tratamento num kit de ligaduras perde o dinheiro que leva\n  de:\n    name: Money Factory\n    description: >-\n      Teams nehmen Fabrik-Boxen ein, die Geld machen, solange sie gehalten werden. Die Spielenden holen es ab,\n      indem sie ihren signierten NFC-Tag an der Fabrik ihres Teams scannen, tragen es über das Feld und zahlen\n      es ein, indem sie ihren Tag an einer Bank-Box scannen: eingezahltes Geld sind Punkte. Der Controller\n      merkt sich, was jede Person trägt, so kann das Geld an einer Box abgeholt und an einer anderen\n      eingezahlt werden. Wer an einem Medic-Kit behandelt wird, verliert das getragene Geld, und ein Team, das\n      das Ziel einzahlt, gewinnt.\n    params:\n      production: Geld, das eine Fabrik pro Intervall macht\n      tick_s: Sekunden pro Intervall einer Fabrik\n      capacity: Meistes Geld, das eine Fabrik fasst\n      carry_max: "Meistes Geld, das eine Person trägt (0: kein Limit)"\n      capture: "Teams nehmen die Fabriken ein: eine Fabrik macht nur Geld, solange sie gehalten wird, und nur ihr Team holt ab (aus: immer, und alle)"\n      capture_hold_ms: Haltezeit zum Einnehmen einer Fabrik (ms)\n      target: "Geld, das ein Team zum Sieg einzahlt (0: kein Ende)"\n      drop_on_heal: Wer an einem Medic-Kit behandelt wird, verliert das getragene Geld\n  zh-tw:\n    name: 印鈔廠\n    description: 各隊佔領印鈔廠盒子，佔有期間印鈔廠會產生金錢。玩家在自己隊伍的印鈔廠感應已簽署的 NFC 標籤領錢，帶著穿越場地，再到銀行盒子感應標籤存入：存入的錢就是分數。場地控制器會記住每位玩家身上的錢，所以可以在一個盒子領錢、到另一個盒子存入。在醫護包接受治療的玩家會失去身上的錢，存到目標金額的隊伍獲勝。\n    params:\n      production: 印鈔廠每次間隔產生的金錢\n      tick_s: 印鈔廠的間隔秒數\n      capacity: 印鈔廠最多可存的金錢\n      carry_max: 每位玩家最多可帶的金錢（0：不限）\n      capture: 各隊要佔領印鈔廠：只有被佔有時才會產生金錢，也只有該隊能領錢（關閉：一直產生，誰都能領）\n      capture_hold_ms: 佔領印鈔廠需按住的時間（毫秒）\n      target: 隊伍存到這個金額即獲勝（0：不結束）\n      drop_on_heal: 在醫護包接受治療的玩家會失去身上的錢\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Money Factory, on each node: a factory or a bank. Players identify\n-- themselves with their signed NFC tag (protocol/nfc-tag.md).\n--\n-- * A factory makes params.production money every params.tick_s seconds, up\n--   to params.capacity. With params.capture (the default) a team captures it\n--   by holding its input for params.capture_hold_ms, as in Domination: it\n--   makes money only while a team holds it, and only that team\'s players\n--   collect. Without capture it always makes money and anyone collects.\n--   A scan takes all the factory holds, up to what the player may still carry\n--   (params.carry_max; 0: no limit): money.collected.\n-- * A bank takes all a player carries: money.deposited, and as many points\n--   for the player\'s team, on this box.\n--\n-- One script plays both roles, and a script does not know its role (decision\n-- M5-5): a node is a factory until the controller\'s field.lua tells it it is a\n-- bank (the mode command "bank"). What a player carries lives in field.lua,\n-- which tells every bank (and every factory, when carrying has a limit) each\n-- player\'s money with the mode command "wallet" (amount, and n, which grows\n-- with each change, so an older or repeated word is ignored). A node out of the\n-- controller\'s reach goes on with what it knows and what it did itself.\n-- Refusals say why on the screen (`reason`); the texts are in the templates.\n-- Screens (assets/screens/): neutral, captured, factory, collected, bank,\n-- deposited, refused; final_score at the end (the Field Box\'s built-in one).\n\nlocal SHOW_S = 4 -- a result stays on the screen this long\n\nlocal tag_refusals = {\n  mac = "forged", -- signed with another key\n  game = "game", -- a tag from another game\n  no_game = "no_game", -- this box is not in a controller\'s game\n  team = "no_team", -- a team this game does not have\n}\n\nlocal s = state.node { owner = nil, since = 0, stock = 0 }\nlocal bank = false -- told by field.lua\nlocal wallets = {} -- player -> { amount, n }: what each player carries\nlocal banked = {} -- team -> money deposited at this bank\nlocal order = {} -- teams in the order they first banked here\nlocal taker, progress -- a team holding its input to take the factory, and how far (0-1)\nlocal back -- the timer that brings the main screen back after a result\n\nlocal function carried(player)\n  local w = wallets[player]\n  return w and w.amount or 0\nend\n\n-- This node\'s own change: the controller\'s next word (a larger n) overrides it.\nlocal function set_carried(player, amount)\n  local w = wallets[player]\n  wallets[player] = { amount = amount, n = w and w.n or 0 }\nend\n\nlocal function counts()\n  local parts = {}\n  for _, team in ipairs(order) do\n    parts[#parts + 1] = string.upper(team) .. " " .. banked[team]\n  end\n  return table.concat(parts, "  ")\nend\n\nlocal function draw()\n  if bank then\n    local total = 0\n    for _, team in ipairs(order) do\n      total = total + banked[team]\n    end\n    ui.screen("bank", { total = total, counts = counts() })\n  elseif not params.capture then\n    ui.screen("factory", { stock = s.stock })\n  elseif s.owner then\n    ui.screen(\n      "captured",\n      { team = s.owner, since = s.since, stock = s.stock, taker = taker, progress = progress }\n    )\n  else\n    ui.screen("neutral", { stock = s.stock, taker = taker, progress = progress })\n  end\nend\n\n-- The main screen again, unless a result is still showing.\nlocal function refresh()\n  if back == nil then\n    draw()\n  end\nend\n\n-- A result screen, then the main screen again after SHOW_S.\nlocal function show(name, data)\n  if back then\n    cancel(back)\n  end\n  ui.screen(name, data)\n  back = after(SHOW_S, function()\n    back = nil\n    draw()\n  end)\nend\n\nlocal function refuse(reason, data)\n  data = data or {}\n  data.reason = reason\n  log("money: refused (" .. reason .. ")" .. (data.player and (" for " .. data.player) or ""))\n  show("refused", data)\nend\n\nlocal function collect(e)\n  local who = { player = e.player, team = e.team, carrying = carried(e.player) }\n  if params.capture then\n    if s.owner == nil then\n      return refuse("neutral", who)\n    end\n    if e.team ~= s.owner then\n      return refuse("not_yours", who)\n    end\n  end\n  local room = s.stock\n  if params.carry_max > 0 then\n    room = params.carry_max - who.carrying\n    if room <= 0 then\n      return refuse("full", who)\n    end\n  end\n  if s.stock <= 0 then\n    return refuse("empty", who)\n  end\n  local take = math.min(s.stock, room)\n  s.stock = s.stock - take\n  set_carried(e.player, who.carrying + take)\n  emit("money.collected", { team = e.team, player = e.player, amount = take })\n  audio.play("collected")\n  show("collected", {\n    player = e.player,\n    team = e.team,\n    amount = take,\n    carrying = who.carrying + take,\n    stock = s.stock,\n  })\nend\n\nlocal function deposit(e)\n  local amount = carried(e.player)\n  if amount <= 0 then\n    return refuse("nothing", { player = e.player, team = e.team, carrying = 0 })\n  end\n  set_carried(e.player, 0)\n  if banked[e.team] == nil then\n    banked[e.team] = 0\n    order[#order + 1] = e.team\n  end\n  banked[e.team] = banked[e.team] + amount\n  emit("money.deposited", { team = e.team, player = e.player, amount = amount })\n  score.add(e.team, amount, "deposit")\n  audio.play("deposited")\n  show("deposited", { player = e.player, team = e.team, amount = amount, total = banked[e.team] })\nend\n\non("game.start", draw)\n\n-- After a power loss the script starts again: the factory\'s holder (kept in\n-- state.node in a game picked on the box) gets its colour back. In a field\n-- game field.lua tells a bank again what it is and what players carry.\non("node.rebooted", function()\n  if s.owner and not bank then\n    cap("team_display"):show(s.owner)\n  end\n  draw()\nend)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("money: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    -- unsigned, format and version: not a player tag of this system\n    return refuse(tag_refusals[e.reason] or "not_tag")\n  end\n  if e.team == nil then\n    return refuse("no_team", { player = e.player })\n  end\n  if bank then\n    deposit(e)\n  else\n    collect(e)\n  end\nend)\n\nevery(params.tick_s, function()\n  if bank or (params.capture and s.owner == nil) or s.stock >= params.capacity then\n    return\n  end\n  s.stock = math.min(params.capacity, s.stock + params.production)\n  refresh()\nend)\n\nlocal function capture(team, squad)\n  local previous = s.owner\n  s.owner = team\n  s.since = math.floor(game.time())\n  taker, progress = nil, nil\n  cap("team_display"):show(team)\n  audio.play("captured")\n  emit("zone.captured", { team = team, squad = squad, previous_team = previous })\n  refresh()\nend\n\non("team_input.hold", function(e)\n  if bank or not params.capture or e.team == s.owner then\n    return\n  end\n  if e.ms < params.capture_hold_ms then\n    taker = e.team\n    -- In hundredths, so the screen gets few distinct values to redraw.\n    progress = math.floor(e.ms * 100 / math.max(1, params.capture_hold_ms)) / 100\n    return refresh()\n  end\n  capture(e.team, e.squad)\nend)\n\n-- Letting go too soon empties the bar.\non("team_input.release", function(e)\n  if e.team == taker then\n    taker, progress = nil, nil\n    refresh()\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the factory.\non("cmd.set_owner", function(e)\n  if bank or not params.capture then\n    return\n  end\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    refresh()\n  else\n    capture(e.team)\n  end\nend)\n\n-- From field.lua: this node is a bank, and what a player carries.\non("cmd.mode", function(e)\n  if e.name == "bank" then\n    if not bank then\n      bank = true\n      taker, progress = nil, nil\n      cap("team_display"):show("none")\n      refresh()\n    end\n  elseif e.name == "wallet" and type(e.player) == "string" then\n    local n = math.tointeger(e.n) or 0\n    local w = wallets[e.player]\n    if w == nil or n > w.n then\n      wallets[e.player] = { amount = math.max(0, math.tointeger(e.amount) or 0), n = n }\n    end\n  end\nend)\n\non("game.end", function()\n  if back then\n    cancel(back)\n    back = nil\n  end\n  ui.screen("final_score", { owner = not bank and s.owner or nil })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Money Factory, on the field controller: the state shared between boxes\n-- (decision A1\'s blocker). It\n--\n-- * tells every node of the role bank that it is one (the mode command\n--   "bank"): at the start, within a second for a bank that joins late, again\n--   every REMIND_S seconds in case a word was lost, and after it rebooted;\n-- * keeps what each player carries (wallets): money.collected adds to it,\n--   money.deposited takes from it, and with params.drop_on_heal a heal at a\n--   medic kit (medic.heal, from the Medic Kit\'s role package in the same game)\n--   empties it. After each change it tells every bank, and every factory when\n--   carrying has a limit, the player\'s money (the mode command "wallet",\n--   with n, which grows with each change of that player\'s wallet);\n-- * counts the money each team banked (state.field.banked) and, with a\n--   params.target, ends the game won by the first team to bank it.\n--\n-- A node out of reach misses words; its events arrive later (a box resends\n-- them), and the wallet follows them: a deposit takes at most what the player\n-- carries here, never below 0.\n\nlocal REMIND_S = 30\n\nlocal fs = state.field {}\nlocal banked = {} -- team -> money banked at every bank\nlocal wallets = {} -- player -> { amount, n }\nlocal told = {} -- bank node id -> true once told it is a bank\nlocal won = false\n\nlocal function tell(node_id, player)\n  local w = wallets[player]\n  field.send(node_id, "mode", { name = "wallet", player = player, amount = w.amount, n = w.n })\nend\n\n-- The nodes that need to know what a player carries.\nlocal function money_nodes()\n  local nodes = field.nodes("bank")\n  if params.carry_max > 0 then\n    for _, n in ipairs(field.nodes("factory")) do\n      nodes[#nodes + 1] = n\n    end\n  end\n  return nodes\nend\n\nlocal function set_wallet(player, amount)\n  local w = wallets[player] or { amount = 0, n = 0 }\n  w.amount, w.n = math.max(0, amount), w.n + 1\n  wallets[player] = w\n  for _, n in ipairs(money_nodes()) do\n    tell(n.id, player)\n  end\nend\n\nlocal function tell_banks(all)\n  for _, n in ipairs(field.nodes("bank")) do\n    if all or not told[n.id] then\n      if field.send(n.id, "mode", { name = "bank" }) then\n        told[n.id] = true\n      end\n    end\n  end\nend\n\non("game.start", function()\n  tell_banks(true)\nend)\n\nlocal since_reminder = 0\nevery(1, function()\n  since_reminder = since_reminder + 1\n  if since_reminder >= REMIND_S then\n    since_reminder = 0\n    tell_banks(true)\n  else\n    tell_banks(false)\n  end\nend)\n\non("money.collected", function(e)\n  local amount = math.tointeger(e.amount)\n  if type(e.player) ~= "string" or amount == nil or amount <= 0 then\n    return\n  end\n  local w = wallets[e.player]\n  set_wallet(e.player, (w and w.amount or 0) + amount)\nend)\n\non("money.deposited", function(e)\n  local amount = math.tointeger(e.amount)\n  if type(e.player) ~= "string" or amount == nil or amount <= 0 then\n    return\n  end\n  local w = wallets[e.player]\n  set_wallet(e.player, (w and w.amount or 0) - amount)\n  if type(e.team) == "string" then\n    banked[e.team] = (banked[e.team] or 0) + amount\n    -- state.field reaches the console when a key is set: a new table each time.\n    local copy = {}\n    for team, money in pairs(banked) do\n      copy[team] = money\n    end\n    fs.banked = copy\n    if params.target > 0 and banked[e.team] >= params.target and not won then\n      won = true\n      log("money: " .. e.team .. " banked " .. banked[e.team] .. " of " .. params.target)\n      game.win(e.team)\n    end\n  end\nend)\n\non("medic.heal", function(e)\n  if not params.drop_on_heal or type(e.player) ~= "string" then\n    return\n  end\n  local w = wallets[e.player]\n  if w and w.amount > 0 then\n    log("money: " .. e.player .. " was healed and lost " .. w.amount)\n    set_wallet(e.player, 0)\n  end\nend)\n\n-- A node that rebooted knows nothing: a bank is told again what it is, and\n-- every node that needs them every player\'s money.\non("node.rebooted", function(e)\n  for _, n in ipairs(field.nodes("bank")) do\n    if n.id == e.node then\n      told[n.id] = nil\n      tell_banks(false)\n    end\n  end\n  for _, n in ipairs(money_nodes()) do\n    if n.id == e.node then\n      for player, w in pairs(wallets) do\n        if w.amount > 0 then\n          tell(n.id, player)\n        end\n      end\n    end\n  end\nend)\n',
    'assets/screens/bank.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A bank. Data: total (money banked here), counts (per team, as text); lang\n# (pt or en) from the box.\ntemplate: bank\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'BANCO\' || lang == \'de\' && \'BANK\' || lang == \'zh-tw\' && \'銀行\' || \'BANK\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{total}"\n    style: { font_size: 48 }\n  - type: label\n    text: "{lang == \'pt\' && \'depositado neste banco\' || lang == \'de\' && \'hier eingezahlt\' || lang == \'zh-tw\' && \'存在這間銀行\' || \'banked here\'}"\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{counts}"\n    style: { font_size: 20, visible: "{counts}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Lê a tua etiqueta para depositar\' || lang == \'de\' && \'Scanne deinen Tag zum Einzahlen\' || lang == \'zh-tw\' && \'感應你的標籤來存錢\' || \'Scan your tag to bank your money\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/captured.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the factory (decision BN-11\'s name, so a box\'s OLED shows the\n# team and how long it has held it). Data: team, since (game time of the\n# capture, in seconds), stock (the money in it), taker and progress (0-1)\n# while another team holds its input; lang (pt, en, de or zh-tw) from the box.\ntemplate: captured\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'FÁBRICA OCUPADA\' || lang == \'de\' && \'FABRIK BESETZT\' || lang == \'zh-tw\' && \'印鈔廠已佔領\' || \'FACTORY HELD\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{stock} / {params.capacity}"\n    style: { font_size: 28 }\n  - type: progress_bar\n    value: "{stock / params.capacity}"\n    style: { width: 220, height: 10, color: team, visible: "{!taker}" }\n  - type: label\n    text: "{lang == \'pt\' && \'A tomar:\' || lang == \'de\' && \'Übernahme:\' || lang == \'zh-tw\' && \'奪取中\' || \'Taking:\'} {taker|upper}"\n    style: { font_size: 20, color: "{taker}", visible: "{taker}" }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 220, height: 12, color: "{taker}", visible: "{taker}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Lê a tua etiqueta para recolher\' || lang == \'de\' && \'Scanne deinen Tag zum Abholen\' || lang == \'zh-tw\' && \'感應你的標籤來領錢\' || \'Scan your tag to collect\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/collected.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A player collected money at a factory. Data: player, team, amount (taken\n# now), carrying (all they carry now), stock (left in the factory); lang (pt\n# or en) from the box.\ntemplate: collected\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'RECOLHIDO\' || lang == \'de\' && \'ABGEHOLT\' || lang == \'zh-tw\' && \'已領取\' || \'COLLECTED\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "+{amount}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20 }\n  - type: label\n    text: "{lang == \'pt\' && \'Levas\' || lang == \'de\' && \'Du trägst\' || lang == \'zh-tw\' && \'你帶著\' || \'You carry\'} {carrying}"\n    style: { font_size: 20, color: accent }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Leva-o a um banco\' || lang == \'de\' && \'Bring es zu einer Bank\' || lang == \'zh-tw\' && \'把錢帶到銀行\' || \'Take it to a bank\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/deposited.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A player banked their money. Data: player, team, amount (points for the\n# team), total (the team\'s money banked here); lang (pt, en, de or zh-tw) from the box.\ntemplate: deposited\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'DEPOSITADO\' || lang == \'de\' && \'EINGEZAHLT\' || lang == \'zh-tw\' && \'已存入\' || \'BANKED\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "+{amount}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20 }\n  - type: label\n    text: "{team|upper}: {total} {lang == \'pt\' && \'neste banco\' || lang == \'de\' && \'hier eingezahlt\' || lang == \'zh-tw\' && \'存在這間銀行\' || \'banked here\'}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n',
    'assets/screens/factory.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A factory without capture (params.capture off): it always makes money and\n# anyone collects. Data: stock (the money in it); lang (pt, en, de or zh-tw) from the box.\ntemplate: factory\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'FÁBRICA\' || lang == \'de\' && \'FABRIK\' || lang == \'zh-tw\' && \'印鈔廠\' || \'FACTORY\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{stock}"\n    style: { font_size: 48, color: accent }\n  - type: label\n    text: "{lang == \'pt\' && \'de\' || lang == \'de\' && \'von\' || lang == \'zh-tw\' && \'/\' || \'of\'} {params.capacity}"\n    style: { font_size: 20, color: muted }\n  - type: progress_bar\n    value: "{stock / params.capacity}"\n    style: { width: 220, height: 10, color: accent }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Lê a tua etiqueta para recolher\' || lang == \'de\' && \'Scanne deinen Tag zum Abholen\' || lang == \'zh-tw\' && \'感應你的標籤來領錢\' || \'Scan your tag to collect\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/neutral.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A factory nobody holds (decision BN-11\'s name, so a box\'s OLED shows it as a\n# free zone). Data: stock (the money in it), taker and progress (0-1) while a\n# team holds its input; lang (pt, en, de or zh-tw) from the box.\ntemplate: neutral\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'FÁBRICA\' || lang == \'de\' && \'FABRIK\' || lang == \'zh-tw\' && \'印鈔廠\' || \'FACTORY\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'LIVRE\' || lang == \'de\' && \'FREI\' || lang == \'zh-tw\' && \'中立\' || \'NEUTRAL\'}"\n    style: { font_size: 48 }\n  - type: label\n    text: "{lang == \'pt\' && \'A tomar:\' || lang == \'de\' && \'Übernahme:\' || lang == \'zh-tw\' && \'奪取中\' || \'Taking:\'} {taker|upper}"\n    style: { font_size: 20, color: "{taker}", visible: "{taker}" }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 220, height: 12, color: "{taker}", visible: "{taker}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém premido durante\' || lang == \'de\' && \'Halte deinen Knopf für\' || lang == \'zh-tw\' && \'按住按鈕\' || \'Hold your button for\'} {params.capture_hold_ms / 1000} {lang == \'zh-tw\' && \'秒\' || \'s\'}"\n    style: { font_size: 20, color: accent, visible: "{!taker}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Dinheiro na fábrica:\' || lang == \'de\' && \'Geld in der Fabrik:\' || lang == \'zh-tw\' && \'印鈔廠存量：\' || \'Money in the factory:\'} {stock}"\n    style: { font_size: 14, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Captura-a para fazer dinheiro\' || lang == \'de\' && \'Nimm sie ein, um Geld zu machen\' || lang == \'zh-tw\' && \'佔領它就能印鈔\' || \'Capture it to make money\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/refused.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A scan refused, and why. Data: reason, and for a player tag player, team and\n# carrying; lang (pt, en, de or zh-tw) from the box.\ntemplate: refused\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: danger }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'RECUSADO\' || lang == \'de\' && \'ABGELEHNT\' || lang == \'zh-tw\' && \'已拒絕\' || \'REFUSED\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Etiqueta falsificada\' || lang == \'de\' && \'Gefälschter Tag\' || lang == \'zh-tw\' && \'偽造的標籤\' || \'Forged tag\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'forged\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Etiqueta de outro jogo\' || lang == \'de\' && \'Tag aus einem anderen Spiel\' || lang == \'zh-tw\' && \'其他遊戲的標籤\' || \'Tag from another game\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'game\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Não é uma etiqueta do jogo\' || lang == \'de\' && \'Kein Tag dieses Spiels\' || lang == \'zh-tw\' && \'不是這場遊戲的標籤\' || \'Not a game tag\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'not_tag\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Esta caixa não está num jogo\' || lang == \'de\' && \'Diese Box ist in keinem Spiel\' || lang == \'zh-tw\' && \'這個盒子不在遊戲中\' || \'This box is not in a game\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'no_game\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Equipa desconhecida\' || lang == \'de\' && \'Unbekanntes Team\' || lang == \'zh-tw\' && \'未知隊伍\' || \'Unknown team\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'no_team\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Captura primeiro a fábrica\' || lang == \'de\' && \'Nimm zuerst die Fabrik ein\' || lang == \'zh-tw\' && \'先佔領印鈔廠\' || \'Capture the factory first\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'neutral\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'A fábrica é de outra equipa\' || lang == \'de\' && \'Ein anderes Team hält die Fabrik\' || lang == \'zh-tw\' && \'印鈔廠在別隊手上\' || \'Another team holds the factory\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'not_yours\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'A fábrica ainda não tem dinheiro\' || lang == \'de\' && \'Noch kein Geld in der Fabrik\' || lang == \'zh-tw\' && \'印鈔廠還沒有錢\' || \'No money in the factory yet\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'empty\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Já levas o máximo: vai a um banco\' || lang == \'de\' && \'Du trägst das Maximum: ab zur Bank\' || lang == \'zh-tw\' && \'你已帶滿：去銀行\' || \'You carry all you can: go to a bank\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'full\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Não levas dinheiro\' || lang == \'de\' && \'Du trägst kein Geld\' || lang == \'zh-tw\' && \'你身上沒有錢\' || \'You carry no money\'}"\n    style: { font_size: 20, width: 300, visible: "{reason == \'nothing\'}" }\n  - type: label\n    text: "{player}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{player}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n',
  },
  'objectives': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.objectives\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\n# A role package for custom scenarios (decision P4R7): a scenario package (kind: scenario, a\n# field.lua only) leads the game (org.club.foxhound+org.atalaia.objectives) and tells each node\n# what it is for with the mode command "setup". The box side never changes per scenario.\nkind: role\nname: Objectives\ndescription: >-\n  The boxes and props of a custom scenario. Each one waits for the scenario, on the field\n  controller, to tell it what it is for: a point to capture by holding a team button, a code to\n  type on the keypad, player tags to scan, or a bomb site to arm and defuse. It reports what\n  happens and never scores: the scenario decides when an objective is completed or failed, and\n  tells the node again after a reboot.\nroles:\n  objective: { requires: [team_input], optional: [keypad, nfc, display, audio, team_display] }\n  bomb_site: { requires: [team_input], optional: [display, audio] }\ni18n:\n  pt:\n    name: Objetivos\n    description: >-\n      As caixas e os adereços de um cenário personalizado. Cada um espera que o cenário, no\n      controlador de campo, lhe diga para que serve: um ponto a capturar mantendo premido o botão\n      de uma equipa, um código a marcar no teclado, etiquetas de jogador a ler, ou um local de\n      bomba a armar e a desarmar. Informa o que acontece e nunca pontua: o cenário decide quando um\n      objetivo é cumprido ou falhado, e volta a configurar o nó depois de um reinício.\n  de:\n    name: Ziele\n    description: >-\n      Die Boxen und Props eines eigenen Szenarios. Jede wartet darauf, dass das Szenario auf dem\n      Feld-Controller ihr sagt, wofür sie da ist: ein Punkt zum Einnehmen per Teamknopf, ein Code zum Tippen\n      am Tastenfeld, Tags der Spielenden zum Scannen oder ein Bombenplatz zum Schärfen und Entschärfen. Sie\n      meldet, was passiert, und punktet nie: das Szenario entscheidet, wann ein Ziel erfüllt oder gescheitert\n      ist, und richtet den Knoten nach einem Neustart wieder ein.\n  zh-tw:\n    name: 任務目標\n    description: 自訂劇本中的盒子與道具。每一個都等待場地控制器上的劇本告訴它用途：按住隊伍按鈕佔領的點、在按鍵輸入的密碼、要感應的玩家標籤，或是要啟動與拆除的炸彈點。它只回報發生的事，從不計分：由劇本決定任務目標何時完成或失敗，並在重新啟動後再次設定節點。\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Objectives (org.atalaia.objectives), the nodes of a custom scenario\n-- (decision P4R7). A node does nothing of its own: it waits for the mode\n-- command "setup" from the scenario\'s field.lua on the controller, which says\n-- what the node is for, and reports what happens with the standard events. It\n-- never scores: the scenario decides when an objective is completed or failed.\n--\n-- setup (every field optional but kind; at most 127 bytes of JSON):\n--   kind      capture, code, tags, bomb; off (inactive, a hidden objective);\n--             done (completed: team, the team that completed it, if one);\n--             failed\n--   team      capture, code, tags: the only team that may do it (code: the\n--             team credited); bomb: the attackers, who arm (any other team\n--             defuses). Empty: every team.\n--   label     the objective\'s short name, in the scenario\'s language\n--   lang      pt (the default), en, de or zh-tw: the screen\'s texts\n--   hold_ms   capture and arm: how long a team holds its input (3000)\n--   defuse_ms bomb: how long a team holds to defuse (hold_ms)\n--   code      code: the digits to type, then #\n--   count     tags: how many tags a team scans (1): players\' own tags, or with\n--             any, any cards (intel), for team or the last team to press\n--   any       tags: true for any card, not only players\' tags\n--   fuse_s    bomb: the fuse (60)\n--   holder    capture: the team holding the node (after a reboot)\n--   have      tags: the tags of team already counted (after a reboot)\n--   armed     bomb: the team that armed it (after a reboot), with left, the\n--             seconds left on the fuse; the bomb goes on without a new event\n--\n-- Reports: zone.captured / zone.neutralized (capture, and the GM\'s owner\n-- override), code.used (code: no code in the event, only the team), tag.scanned\n-- (tags: tag, the card\'s uid; owner, the player; team), bomb.armed / bomb.defused /\n-- bomb.exploded (bomb), node.setup_applied (kind: every setup it took). A script does not\n-- know its role (decision M5-5): the setup\'s kind is what the node does, so one script serves\n-- both roles.\n\nlocal cfg = {} -- the last setup\nlocal holder -- capture: the team holding the node\nlocal typed, note = "", nil -- code: the digits typed; the bottom line (wrong, ok, ...)\nlocal got, seen = {}, {} -- tags: team -> tags counted; uid -> true\nlocal phase, by, explode_at, fuse -- bomb: standby, armed, defused, exploded\nlocal last_team -- the last team to press its input (code: the team credited)\n\nlocal function int(v, lo, hi, default)\n  v = math.tointeger(v)\n  if v == nil or v < lo or v > hi then\n    return default\n  end\n  return v\nend\n\nlocal function show()\n  local k = cfg.kind\n  local d = { lang = cfg.lang, label = cfg.label }\n  if k == "capture" then\n    d.team, d.only, d.hold_ms = holder, cfg.team, cfg.hold_ms\n    ui.screen("obj_capture", d)\n  elseif k == "code" then\n    d.team, d.digits, d.note = cfg.team or last_team, #typed, note\n    ui.screen("obj_code", d)\n  elseif k == "tags" then\n    local team = cfg.team or cfg.last\n    d.team, d.have, d.count, d.note, d.any = team, team and got[team] or 0, cfg.count, note, cfg.any\n    ui.screen("obj_tags", d)\n  elseif k == "bomb" then\n    d.phase, d.team, d.attackers, d.fuse_s = phase, by, cfg.team, cfg.fuse_s\n    d.left = phase == "armed" and math.max(0, math.ceil(explode_at - game.time())) or 0\n    ui.screen("obj_bomb", d)\n  else\n    d.state, d.team = k or "wait", k == "done" and cfg.team or nil -- wait, off, done, failed\n    ui.screen("obj_status", d)\n  end\nend\n\nlocal function may(team)\n  return cfg.team == nil or team == cfg.team\nend\n\n-- Capture.\n\nlocal function take(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = holder })\n  holder = team\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\n-- Bomb site.\n\nlocal function arm(team, left, quiet)\n  phase, by, explode_at = "armed", team, game.time() + left\n  fuse = after(left, function()\n    fuse, phase = nil, "exploded"\n    audio.play("explosion")\n    emit("bomb.exploded", { team = by })\n    show()\n  end)\n  if not quiet then\n    audio.play("armed")\n    emit("bomb.armed", { team = team, fuse_s = left })\n  end\n  show()\nend\n\nlocal function defuse(team)\n  cancel(fuse)\n  fuse, phase, by = nil, "defused", team\n  audio.play("defused")\n  emit("bomb.defused", { team = team })\n  show()\nend\n\non("game.start", show)\n\non("cmd.mode", function(e)\n  if e.name ~= "setup" then\n    return\n  end\n  if fuse then\n    cancel(fuse)\n  end\n  local hold = int(e.hold_ms, 0, 600000, 3000)\n  cfg = {\n    kind = e.kind,\n    team = e.team ~= "" and e.team or nil,\n    label = e.label,\n    lang = e.lang,\n    hold_ms = hold,\n    defuse_ms = int(e.defuse_ms, 0, 600000, hold),\n    code = type(e.code) == "string" and e.code or nil,\n    count = int(e.count, 1, 100, 1),\n    any = e.any == true,\n    fuse_s = int(e.fuse_s, 10, 3600, 60),\n  }\n  holder, typed, note, got, seen = e.holder ~= "" and e.holder or nil, "", nil, {}, {}\n  phase, by, fuse = "standby", nil, nil\n  if cfg.kind == "tags" and cfg.team then\n    got[cfg.team] = int(e.have, 0, 100, 0)\n  end\n  if holder then\n    cap("team_display"):show(holder)\n  end\n  -- Tell the scenario the setup arrived (decision PKB-3): its field.lua stops sending it again when it\n  -- hears this. The event is acknowledged and repeated by the radio link like any other, so a lost\n  -- setup is sent again by the scenario and a lost confirmation by the box.\n  if type(cfg.kind) == "string" then\n    emit("node.setup_applied", { kind = cfg.kind })\n  end\n  if cfg.kind == "bomb" and type(e.armed) == "string" then\n    return arm(e.armed, int(e.left, 1, 3600, cfg.fuse_s), true)\n  end\n  show()\nend)\n\non("team_input.press", function(e)\n  last_team = e.team\nend)\n\non("team_input.hold", function(e)\n  local k = cfg.kind\n  if k == "capture" then\n    if e.team ~= holder and e.ms >= cfg.hold_ms and may(e.team) then\n      take(e.team, e.squad)\n    end\n  elseif k == "bomb" then\n    if phase == "standby" and e.ms >= cfg.hold_ms and may(e.team) then\n      arm(e.team, cfg.fuse_s)\n    elseif phase == "armed" and e.team ~= by and e.ms >= cfg.defuse_ms then\n      defuse(e.team)\n    end\n  end\nend)\n\n-- The GM\'s owner override (the console\'s Boxes tab), for a capture only.\non("cmd.set_owner", function(e)\n  if cfg.kind ~= "capture" then\n    return\n  end\n  local team = e.team\n  if team == "" or team == "none" then\n    team = nil\n  end\n  if team == holder then\n    return\n  end\n  if team then\n    return take(team)\n  end\n  emit("zone.neutralized", { previous_team = holder })\n  holder = nil\n  cap("team_display"):show("none")\n  show()\nend)\n\n-- Code: digits, then #; * clears. A wrong code is only on the screen.\non("keypad.key", function(e)\n  if cfg.kind ~= "code" or note == "ok" then\n    return\n  end\n  local k = e.key\n  if k == "#" then\n    if cfg.code and typed == cfg.code then\n      note = "ok"\n      emit("code.used", { team = cfg.team or last_team })\n      audio.play("captured")\n    else\n      note = "wrong"\n    end\n    typed = ""\n  elseif k == "*" then\n    typed, note = "", nil\n  elseif string.match(k or "", "^%d\$") and #typed < 8 then\n    typed, note = typed .. k, nil\n  end\n  show()\nend)\n\n-- Tags: each player of a team scans their own tag once; with any, any card\n-- (intel cards) counts once, for the team at the box.\non("nfc.tag", function(e)\n  if cfg.kind ~= "tags" then\n    return\n  end\n  local team = e.team\n  if cfg.any then\n    team = cfg.team or last_team\n  end\n  if not cfg.any and not e.valid then\n    note = "not_tag"\n  elseif team == nil then\n    note = "team_first"\n  elseif not may(team) then\n    note = "wrong_team"\n  else\n    cfg.last = team\n    local n = got[team] or 0\n    if seen[e.uid] or n >= cfg.count then\n      note = "again"\n    else\n      seen[e.uid], got[team], note = true, n + 1, nil\n      emit("tag.scanned", { team = team, tag = e.uid, owner = e.valid and e.player or nil })\n    end\n  end\n  show()\nend)\n\nevery(1, function()\n  if cfg.kind == "bomb" and phase == "armed" then\n    show()\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = holder })\nend)\n',
    'assets/screens/obj_bomb.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A bomb site. Data: phase (standby, armed, defused, exploded), team (armed,\n# exploded: the team that armed it; defused: the team that defused it),\n# attackers (the only team that may arm it, if one), left (armed: seconds\n# left), fuse_s, label (the objective\'s name), lang (pt, the default, en, de or\n# zh-tw).\ntemplate: obj_bomb\nstyle: { background: "{phase == \'exploded\' && \'danger\' || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{phase == \'armed\' && \'danger\' || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || lang == \'en\' && \'BOMB SITE\' || lang == \'de\' && \'BOMBENPLATZ\' || lang == \'zh-tw\' && \'炸彈點\' || \'LOCAL DA BOMBA\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{left|clock}"\n    style: { font_size: 48, color: "{left <= 10 && \'danger\' || \'white\'}", visible: "{phase == \'armed\'}" }\n  - type: progress_bar\n    value: "{left / fuse_s}"\n    style: { width: 240, height: 10, color: "{team || \'danger\'}", visible: "{phase == \'armed\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'Hold to defuse\' || lang == \'de\' && \'Halten zum Entschärfen\' || lang == \'zh-tw\' && \'按住以拆除\' || \'Mantém premido para desarmar\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'armed\'}"\n      padding: { top: 6 }\n  - type: label\n    text: "{lang == \'de\' && \'Halten zum Schärfen\' || lang == \'zh-tw\' && \'按住以啟動\' || \'Mantém premido para armar\'}"\n    style: { font_size: 20, color: accent, visible: "{phase == \'standby\' && lang != \'en\'}" }\n  - type: label\n    text: Hold to arm\n    style: { font_size: 28, color: accent, visible: "{phase == \'standby\' && lang == \'en\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'DEFUSED\' || lang == \'de\' && \'ENTSCHÄRFT\' || lang == \'zh-tw\' && \'已拆除\' || \'DESARMADA\'}"\n    style: { font_size: 28, color: "{team || \'accent\'}", visible: "{phase == \'defused\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'EXPLODED\' || lang == \'de\' && \'EXPLODIERT\' || lang == \'zh-tw\' && \'已爆炸\' || \'EXPLODIU\'}"\n    style: { font_size: 28, color: white, visible: "{phase == \'exploded\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'en\' && \'Armed by\' || lang == \'de\' && \'Scharf gemacht von\' || lang == \'zh-tw\' && \'啟動隊伍\' || \'Armada por\'} {team|upper}"\n    style:\n      font_size: 14\n      color: team\n      visible: "{phase == \'armed\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Só a equipa {attackers} arma"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'standby\' && attackers && lang != \'en\' && lang != \'de\' && lang != \'zh-tw\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Only {attackers} arms it"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'standby\' && attackers && lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Nur Team {attackers} macht scharf"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'standby\' && attackers && lang == \'de\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "只有 {attackers} 隊能啟動"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{phase == \'standby\' && attackers && lang == \'zh-tw\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_capture.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A point to capture. Data: team (the team holding it, if one), only (the only\n# team that may capture it, if one), hold_ms (how long to hold), label (the\n# objective\'s name), lang (pt, the default, en, de or zh-tw).\ntemplate: obj_capture\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || lang == \'en\' && \'CAPTURE\' || lang == \'de\' && \'EINNEHMEN\' || lang == \'zh-tw\' && \'佔領\' || \'CAPTURAR\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team, visible: "{team}" }\n  - type: label\n    text: "{lang == \'en\' && \'holds this point\' || lang == \'de\' && \'hält diesen Punkt\' || lang == \'zh-tw\' && \'佔領了這個點\' || \'tem este ponto\'}"\n    style: { font_size: 20, color: muted, visible: "{team}" }\n  - type: label\n    text: "{lang == \'en\' && \'HOLD TO CAPTURE\' || lang == \'de\' && \'GEDRÜCKT HALTEN\' || lang == \'zh-tw\' && \'按住以佔領\' || \'MANTÉM PREMIDO\'}"\n    style: { font_size: 28, color: accent, visible: "{!team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'en\' && \'Hold your button\' || lang == \'de\' && \'Halte deinen Knopf\' || lang == \'zh-tw\' && \'按住按鈕\' || \'Mantém premido\'} {hold_ms / 1000} {lang == \'en\' && \'s to capture\' || lang == \'de\' && \'s zum Einnehmen\' || lang == \'zh-tw\' && \'秒即可佔領\' || \'s para capturar\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!only}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Só a equipa {only} captura: {hold_ms / 1000} s"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{only && lang != \'en\' && lang != \'de\' && lang != \'zh-tw\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Only {only} captures: {hold_ms / 1000} s"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{only && lang == \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "Nur Team {only} nimmt ein: {hold_ms / 1000} s"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{only && lang == \'de\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "只有 {only} 隊能佔領：{hold_ms / 1000} 秒"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{only && lang == \'zh-tw\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_code.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A code to type on the keypad. Data: team (the team credited, if known),\n# digits (how many digits are typed: the code itself is never shown), note\n# (wrong: the last code was wrong; ok: the right code was typed), label (the\n# objective\'s name), lang (pt, the default, en, de or zh-tw).\ntemplate: obj_code\nstyle: { background: "{note == \'ok\' && team || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || lang == \'en\' && \'CODE\' || lang == \'de\' && \'CODE\' || lang == \'zh-tw\' && \'密碼\' || \'CÓDIGO\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{digits}"\n    style: { font_size: 48, color: accent, visible: "{note != \'ok\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'digits typed\' || lang == \'de\' && \'Ziffern getippt\' || lang == \'zh-tw\' && \'已輸入的位數\' || \'algarismos marcados\'}"\n    style: { font_size: 20, color: muted, visible: "{note != \'ok\'}" }\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: "{team && \'contrast\' || \'accent\'}", visible: "{note == \'ok\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'CODE ACCEPTED\' || lang == \'de\' && \'CODE RICHTIG\' || lang == \'zh-tw\' && \'密碼正確\' || \'CÓDIGO ACEITE\'}"\n    style: { font_size: 28, color: "{team && \'contrast\' || \'white\'}", visible: "{note == \'ok\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'en\' && \'Wrong code\' || lang == \'de\' && \'Falscher Code\' || lang == \'zh-tw\' && \'密碼錯誤\' || \'Código errado\'}"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'wrong\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "{lang == \'en\' && \'Type the code, then #  (* clears)\' || lang == \'de\' && \'Code tippen, dann #  (* löscht)\' || lang == \'zh-tw\' && \'輸入密碼後按 #（* 清除）\' || \'Marca o código e #  (* apaga)\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_status.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A node with nothing to do. Data: state (wait: no setup from the scenario yet;\n# off: a hidden or inactive objective; done: completed; failed), team (done: the team\n# that completed it, if one), label (the objective\'s name, from the setup),\n# lang (pt, the default, en, de or zh-tw).\ntemplate: obj_status\nstyle: { background: "{state == \'done\' && team || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{label || lang == \'en\' && \'OBJECTIVE\' || lang == \'de\' && \'ZIEL\' || lang == \'zh-tw\' && \'任務目標\' || \'OBJETIVO\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'en\' && \'Waiting for the scenario\' || lang == \'de\' && \'Warte aufs Szenario\' || lang == \'zh-tw\' && \'等待劇本\' || \'À espera do cenário\'}"\n    style: { font_size: 28, visible: "{state == \'wait\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'Objective inactive\' || lang == \'de\' && \'Ziel inaktiv\' || lang == \'zh-tw\' && \'目標未啟用\' || \'Objetivo inativo\'}"\n    style: { font_size: 28, color: muted, visible: "{state == \'off\'}" }\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: "{team && \'contrast\' || \'accent\'}", visible: "{state == \'done\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'COMPLETE\' || lang == \'de\' && \'ERFÜLLT\' || lang == \'zh-tw\' && \'已完成\' || \'CUMPRIDO\'}"\n    style: { font_size: 28, color: "{team && \'contrast\' || \'white\'}", visible: "{state == \'done\'}" }\n  - type: label\n    text: "{lang == \'en\' && \'FAILED\' || lang == \'de\' && \'GESCHEITERT\' || lang == \'zh-tw\' && \'失敗\' || \'FALHADO\'}"\n    style: { font_size: 28, color: danger, visible: "{state == \'failed\'}" }\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 20, color: contrast, visible: "{state == \'done\' && team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'en\' && \'Set up by the field controller\' || lang == \'de\' && \'Eingerichtet vom Feld-Controller\' || lang == \'zh-tw\' && \'由場地控制器設定\' || \'Configurado pelo controlador de campo\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{state == \'wait\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/obj_tags.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Player tags to scan. Data: team (the team of the last tag counted, or the\n# only team that may scan), have (that team\'s tags counted), count (how many it\n# needs), note (not_tag: not a player tag of this game; team_first: a card, and\n# no team has pressed its button yet; wrong_team: a team that may not scan\n# here; again: a tag already counted, or the team already has them all), any\n# (any card counts, not only players\' tags), label (the objective\'s name),\n# lang (pt, the default, en, de or zh-tw).\ntemplate: obj_tags\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{label || lang == \'en\' && \'TAGS\' || lang == \'de\' && \'TAGS\' || lang == \'zh-tw\' && \'標籤\' || \'ETIQUETAS\'}"\n        style: { font_size: 20, width: fill, align: center, color: "{team && \'contrast\' || \'white\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{have} / {count}"\n    style: { font_size: 48, color: "{team || \'accent\'}" }\n  - type: progress_bar\n    value: "{have / count}"\n    style: { width: 260, height: 14, color: "{team || \'accent\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'en\' && \'Not a game tag\' || lang == \'de\' && \'Kein Tag dieses Spiels\' || lang == \'zh-tw\' && \'不是這場遊戲的標籤\' || \'Não é uma etiqueta do jogo\'}"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'not_tag\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "{lang == \'en\' && \'Another team’s objective\' || lang == \'de\' && \'Ziel eines anderen Teams\' || lang == \'zh-tw\' && \'這是別隊的目標\' || \'Objetivo de outra equipa\'}"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'wrong_team\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "{lang == \'en\' && \'Press your team’s button\' || lang == \'de\' && \'Drück deinen Teamknopf\' || lang == \'zh-tw\' && \'先按你隊伍的按鈕\' || \'Carrega no botão da equipa\'}"\n    style:\n      font_size: 20\n      color: danger\n      visible: "{note == \'team_first\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "{lang == \'en\' && \'This tag already counts\' || lang == \'de\' && \'Dieser Tag zählt schon\' || lang == \'zh-tw\' && \'這個標籤已計算過\' || \'Esta etiqueta já conta\'}"\n    style:\n      font_size: 20\n      color: muted\n      visible: "{note == \'again\'}"\n      padding: { bottom: 8 }\n  - type: label\n    text: "{lang == \'en\' && \'Each player scans their own tag\' || lang == \'de\' && \'Alle scannen ihren eigenen Tag\' || lang == \'zh-tw\' && \'每位玩家感應自己的標籤\' || \'Cada pessoa lê a sua etiqueta\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && !any}"\n      padding: { bottom: 10 }\n  - type: label\n    text: "{lang == \'en\' && \'Scan the cards you found\' || lang == \'de\' && \'Scanne die Karten, die du gefunden hast\' || lang == \'zh-tw\' && \'感應你找到的卡片\' || \'Lê os cartões que encontraste\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{!note && any}"\n      padding: { bottom: 10 }\n',
  },
  'player_checkin': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.player_checkin\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Player Check-in\ndescription: >-\n  Players check in at a checkpoint by scanning their signed NFC tag. The box counts the players of each\n  team and gives their team points for each check-in. A player counts once, or again after a set time.\n  Forged tags and tags from another game are refused.\nroles:\n  checkpoint: { requires: [nfc], optional: [display] }\nparams:\n  points:         { type: int, min: 0, max: 1000, default: 1, label: "Points for the player\'s team per check-in" }\n  repeat_after_s: { type: int, min: 0, max: 86400, default: 0, label: "Seconds before the same player counts again (0: once per game)" }\ni18n:\n  pt:\n    name: Registo de Presença\n    description: >-\n      Cada participante faz o registo num ponto de controlo lendo a sua etiqueta NFC assinada. A caixa conta\n      as pessoas de cada equipa e dá pontos à equipa por cada registo. Cada pessoa conta uma vez, ou de\n      novo ao fim de um tempo definido. Etiquetas falsificadas ou de outro jogo são recusadas.\n    params:\n      points: Pontos para a equipa por cada registo\n      repeat_after_s: "Segundos até a mesma pessoa voltar a contar (0: uma vez por jogo)"\n  de:\n    name: Check-in\n    description: >-\n      Die Spielenden checken an einem Checkpoint ein, indem sie ihren signierten NFC-Tag scannen. Die Box\n      zählt die Spielenden jedes Teams und gibt ihrem Team für jeden Check-in Punkte. Eine Person zählt einmal\n      oder nach einer festgelegten Zeit erneut. Gefälschte Tags und Tags aus einem anderen Spiel werden\n      abgelehnt.\n    params:\n      points: Punkte für das Team pro Check-in\n      repeat_after_s: "Sekunden, bis dieselbe Person wieder zählt (0: einmal pro Spiel)"\n  zh-tw:\n    name: 玩家報到\n    description: 玩家在報到點感應自己已簽署的 NFC 標籤報到。盒子會計算每隊的玩家人數，每次報到都為該隊加分。每位玩家只算一次，或在設定的時間後再算一次。偽造的標籤與其他遊戲的標籤會被拒絕。\n    params:\n      points: 每次報到為該隊加的分數\n      repeat_after_s: 同一位玩家再次計算前的秒數（0：每場一次）\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Player Check-in: players check in at a checkpoint with their signed NFC\n-- tag (protocol/nfc-tag.md). The box counts check-ins per team and gives the\n-- player\'s team `points` for each. A player counts once per game, or again\n-- after repeat_after_s seconds; a scan before that is a duplicate and is\n-- refused. Forged tags, tags from another game and tags without a team are\n-- refused (the shell checks the signature and says why in nfc.tag\'s reason).\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal seen = {} -- player -> game time of their last check-in that counted\nlocal count = {} -- team -> check-ins\nlocal order = {} -- teams in the order they first checked in\nlocal total = 0\nlocal last_team\nlocal message, failed, fade\n\nlocal function counts()\n  local parts = {}\n  for _, team in ipairs(order) do\n    parts[#parts + 1] = string.upper(team) .. " " .. count[team]\n  end\n  return table.concat(parts, "  ")\nend\n\nlocal function show()\n  ui.screen("checkin", {\n    total = total,\n    counts = counts(),\n    team = last_team,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the counts, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("check-in: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local t = seen[e.player]\n  if t and (params.repeat_after_s == 0 or game.time() - t < params.repeat_after_s) then\n    return say("Already checked in", true)\n  end\n  seen[e.player] = game.time()\n  if count[e.team] == nil then\n    count[e.team] = 0\n    order[#order + 1] = e.team\n  end\n  count[e.team] = count[e.team] + 1\n  total = total + 1\n  last_team = e.team\n  emit("player.checkin", { team = e.team, player = e.player })\n  score.add(e.team, params.points, "checkin")\n  say("Checked in: " .. e.player, false)\nend)\n',
    'assets/screens/checkin.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The checkpoint. Data: total (check-ins), counts (per team, as text),\n# team (of the last check-in), message, error; lang (pt, de, zh-tw, else English) from\n# the box.\ntemplate: checkin\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'REGISTO DE PRESENÇA\' || lang == \'de\' && \'CHECK-IN\' || lang == \'zh-tw\' && \'玩家報到\' || \'CHECK-IN\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{total}"\n    style: { font_size: 48 }\n  - type: label\n    text: "{lang == \'pt\' && \'participantes registados\' || lang == \'de\' && \'Spielende eingecheckt\' || lang == \'zh-tw\' && \'玩家已報到\' || \'players checked in\'}"\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{counts}"\n    style: { font_size: 20, visible: "{counts}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Lê a tua etiqueta para o registo\' || lang == \'de\' && \'Scanne deinen Tag zum Einchecken\' || lang == \'zh-tw\' && \'感應你的標籤來報到\' || \'Scan your tag to check in\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'progressive_domination': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.progressive_domination\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Progressive Domination\ndescription: >-\n  Several boxes, but only one can be captured at a time. Both teams are told which box is active; the\n  team holding it scores for each minute, and once a team has held it long enough the box is completed\n  for that team and locked, and the next box in the order is announced to both teams.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  complete_min:    { type: int, min: 1, max: 240,   default: 10,   label: "Minutes a team holds the active box to complete it" }\n  points_per_min:  { type: int, min: 0, max: 1000,  default: 6,    label: "Points per full minute a team holds the active box" }\n  complete_bonus:  { type: int, min: 0, max: 10000, default: 0,    label: "Points for completing a box" }\n  random_order:    { type: bool, default: false, label: "Random order of the boxes (off: by box id)" }\n  order:           { type: string, max: 100, default: "", label: "Boxes in the order of play, by name, comma-separated (the others follow)" }\n  target_score:    { type: int, min: 0, max: 100000, default: 0, label: "Points that win the game at once (0: play every box)" }\ni18n:\n  pt:\n    name: Domínio Progressivo\n    description: >-\n      Várias caixas, mas só uma pode ser capturada de cada vez. As duas equipas sabem qual é a caixa ativa;\n      a equipa que a tem pontua por cada minuto e, quando a tiver mantido o tempo necessário, a caixa fica\n      completa para essa equipa e bloqueada, e a caixa seguinte da ordem é anunciada às duas equipas.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      complete_min: Minutos que uma equipa mantém a caixa ativa para a completar\n      points_per_min: Pontos por cada minuto completo que uma equipa mantém a caixa ativa\n      complete_bonus: Pontos por completar uma caixa\n      random_order: "Ordem aleatória das caixas (desligado: pelo número da caixa)"\n      order: "Caixas pela ordem de jogo, por nome e separadas por vírgulas (as outras seguem-se)"\n      target_score: "Pontos que ganham o jogo de imediato (0: jogar todas as caixas)"\n  de:\n    name: Progressive Domination\n    description: >-\n      Mehrere Boxen, aber nur eine kann gleichzeitig eingenommen werden. Beide Teams erfahren, welche Box aktiv\n      ist; das Team, das sie hält, punktet für jede Minute, und hat es sie lange genug gehalten, ist die Box\n      für dieses Team abgeschlossen und gesperrt, und die nächste Box der Reihenfolge wird beiden Teams\n      gemeldet.\n    params:\n      capture_hold_ms: Haltezeit zum Einnehmen (ms)\n      complete_min: Minuten, die ein Team die aktive Box halten muss, um sie abzuschließen\n      points_per_min: Punkte für jede volle Minute, die ein Team die aktive Box hält\n      complete_bonus: Punkte für das Abschließen einer Box\n      random_order: "Zufällige Reihenfolge der Boxen (aus: nach Box-Nummer)"\n      order: "Boxen in Spielreihenfolge, nach Namen und durch Kommas getrennt (die übrigen folgen)"\n      target_score: "Punkte, die das Spiel sofort gewinnen (0: alle Boxen spielen)"\n  zh-tw:\n    name: 漸進佔點\n    description: 場上有好幾個盒子，但同一時間只能佔領其中一個。兩隊都會收到目前啟用的是哪個盒子；佔有它的隊伍每分鐘得分，佔有夠久之後，這個盒子就算該隊完成並鎖定，下一個盒子則會通知兩隊。\n    params:\n      capture_hold_ms: 佔領需按住的時間（毫秒）\n      complete_min: 隊伍要佔有啟用中的盒子幾分鐘才算完成\n      points_per_min: 隊伍佔有啟用中的盒子，每滿一分鐘的得分\n      complete_bonus: 完成一個盒子的得分\n      random_order: 盒子的順序隨機（關閉：依盒子編號）\n      order: 盒子的遊玩順序，用名稱、以逗號分隔（其餘接在後面）\n      target_score: 達到這個分數就立刻獲勝（0：玩完所有盒子）\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Progressive Domination, on each box (decisions PD-MODE-1 to PD-MODE-20).\n-- All the boxes run this script; the field controller\'s field.lua decides\n-- which one is capturable and tells each box with the mode command "pd":\n--\n--   phase "wait"   not its turn (or finished before it): ignores its buttons,\n--                  LED off, shows how many boxes are completed;\n--   phase "active" the only box capturable now: a team captures it by holding\n--                  its input for params.capture_hold_ms, as in Domination, and\n--                  another team takes it over the same way; the LED is white\n--                  while nobody holds it, the holder\'s colour after;\n--   phase "done"   completed by a team (the word\'s "team"): locked for good,\n--                  in that team\'s colour, buttons ignored.\n--\n-- A box never scores and never decides: points per minute held, the hold\n-- time that completes a box, the order and the end of the game are field.lua\'s.\n-- The box only reports its captures (zone.captured and zone.neutralized, as\n-- Domination does) and shows what it was told. The word carries n, which grows\n-- with every change, so an older or repeated word is ignored; field.lua says it\n-- again every few seconds and when this box reboots. Before its first word\n-- (a box picked on its own, without a controller) a box waits.\n-- Screens (assets/screens/): inactive, neutral (the active box nobody holds),\n-- captured (the active box and its holder), completed; final_score at the end\n-- (the Field Box\'s built-in screen).\n\nlocal REFRESH_S = 5 -- the held time on the screen follows the game\'s clock this often\n\nlocal s = state.node {\n  phase = "wait",\n  owner = nil,\n  since = 0,\n  n = 0,\n  step = 0,\n  of = 0,\n  done = 0,\n  team = nil,\n}\nlocal taker, progress -- a team holding its input to take the active box, and how far (0-1)\n\nlocal function final()\n  return s.of > 0 and s.step == s.of\nend\n\nlocal function draw()\n  if s.phase == "active" then\n    if s.owner then\n      local held_s = math.max(0, math.floor(game.time()) - s.since)\n      local need_s = params.complete_min * 60\n      ui.screen("captured", {\n        team = s.owner,\n        since = s.since,\n        step = s.step,\n        of = s.of,\n        final = final(),\n        held_min = held_s // 60,\n        need_min = params.complete_min,\n        points = (held_s // 60) * params.points_per_min,\n        share = math.min(100, held_s * 100 // need_s) / 100,\n        taker = taker,\n        progress = progress,\n      })\n    else\n      ui.screen(\n        "neutral",\n        { step = s.step, of = s.of, final = final(), taker = taker, progress = progress }\n      )\n    end\n  elseif s.phase == "done" then\n    ui.screen("completed", { team = s.team, step = s.step, of = s.of, done = s.done })\n  else\n    ui.screen("inactive", { done = s.of > 0 and s.done or nil, of = s.of > 0 and s.of or nil })\n  end\nend\n\nlocal function light()\n  if s.phase == "active" then\n    cap("team_display"):show(s.owner or "white")\n  elseif s.phase == "done" then\n    cap("team_display"):show(s.team or "none")\n  else\n    cap("team_display"):show("none")\n  end\nend\n\nlocal function capture(team, squad)\n  local previous = s.owner\n  s.owner = team\n  s.since = math.floor(game.time())\n  taker, progress = nil, nil\n  audio.play("captured")\n  emit("zone.captured", { team = team, squad = squad, previous_team = previous })\n  light()\n  draw()\nend\n\non("game.start", function()\n  light()\n  draw()\nend)\n\n-- After a power loss the script starts again, with what state.node kept in a\n-- game picked on the box; in a field game field.lua says it all again.\non("node.rebooted", function()\n  light()\n  draw()\nend)\n\non("team_input.hold", function(e)\n  if s.phase ~= "active" or e.team == s.owner then\n    return\n  end\n  if e.ms < params.capture_hold_ms then\n    taker = e.team\n    -- In hundredths, so the screen gets few distinct values to redraw.\n    progress = math.floor(e.ms * 100 / math.max(1, params.capture_hold_ms)) / 100\n    return draw()\n  end\n  capture(e.team, e.squad)\nend)\n\n-- Letting go too soon empties the bar.\non("team_input.release", function(e)\n  if e.team == taker then\n    taker, progress = nil, nil\n    if s.phase == "active" then\n      draw()\n    end\n  end\nend)\n\n-- The GM\'s owner override from the console: only the active box takes it.\non("cmd.set_owner", function(e)\n  if s.phase ~= "active" then\n    return\n  end\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    taker, progress = nil, nil\n    light()\n    draw()\n  else\n    capture(e.team)\n  end\nend)\n\n-- From field.lua: this box\'s phase and the progress of the game.\non("cmd.mode", function(e)\n  if e.name ~= "pd" then\n    return\n  end\n  local n = math.tointeger(e.n) or 0\n  local phase = e.phase\n  if n <= s.n or (phase ~= "wait" and phase ~= "active" and phase ~= "done") then\n    return\n  end\n  local was = s.phase\n  s.n, s.phase = n, phase\n  s.step = math.tointeger(e.step) or 0\n  s.of = math.tointeger(e.of) or 0\n  s.done = math.tointeger(e.done) or 0\n  s.team = type(e.team) == "string" and e.team or nil\n  if phase == "active" and was ~= "active" then\n    -- A new turn: the box starts free, and says so loud.\n    s.owner, s.since = nil, 0\n    taker, progress = nil, nil\n    audio.play("alarm")\n  elseif phase ~= "active" then\n    taker, progress = nil, nil\n    if phase == "done" and was ~= "done" then\n      audio.play("defused")\n    end\n  end\n  light()\n  draw()\nend)\n\nevery(REFRESH_S, function()\n  if s.phase == "active" and s.owner then\n    draw()\n  end\nend)\n\non("game.end", function()\n  taker, progress = nil, nil\n  ui.screen("final_score", { owner = s.owner or s.team })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Progressive Domination, on the field controller (decisions PD-MODE-1 to\n-- PD-MODE-20): one box is capturable at a time, in an order fixed at the start.\n--\n-- * The order: the boxes named in params.order first, as the GM wrote them,\n--   then the others (every box with the role zone) by box id, or shuffled with\n--   the game\'s seeded rand() when params.random_order, so a replay picks the same.\n-- * The active box: the first of the order at the start; field.lua announces it\n--   (progressive.activated, to both teams) and tells every box its phase (the\n--   mode command "pd": phase wait, active or done, and n, which grows with each\n--   change; node.lua ignores an older or repeated word). The word is said again\n--   every REMIND_S seconds in case a radio word was lost, and to a box that rebooted.\n-- * Holding: the active box\'s own events say who holds it (zone.captured and\n--   zone.neutralized from that box; a stale owner on the controller\'s list of\n--   boxes is never read). A team holding it for each full minute scores\n--   params.points_per_min, the first points one minute after the capture. When\n--   it has held it for params.complete_min minutes (and so been paid for each),\n--   the box is completed for that team (progressive.completed, plus\n--   params.complete_bonus), locked, and the next box in the order is announced.\n-- * Another team taking the box before that starts its own count from zero; what\n--   the first team earned stays its own.\n-- * The end: when the last box is completed, the game ends won by the team with\n--   the most points (a tie ends it without a winner), or earlier when a team\n--   reaches params.target_score (0: no score target).\n\nlocal REMIND_S = 10\nlocal MINUTE_S = 60\n\nlocal fs = state.field { active = nil, step = 0, of = 0, done = 0, holder = nil }\nlocal order = {} -- { id, name } in the order of play\nlocal results = {} -- step -> the team that completed it\nlocal pos = 0 -- the active box\'s place in order; #order + 1 when all are completed\nlocal ver = 0 -- grows with each change of what the boxes are told\nlocal owner, since, credited = nil, 0, 0 -- the holder of the active box, since when, minutes paid\nlocal over = false\n\nlocal function trim(text)\n  return (text:gsub("^%s+", ""):gsub("%s+\$", ""))\nend\n\nlocal function build_order()\n  local boxes = field.nodes("zone")\n  table.sort(boxes, function(a, b)\n    return a.id < b.id\n  end)\n  local taken = {}\n  order = {}\n  for name in string.gmatch(params.order, "[^,]+") do\n    name = trim(name)\n    for _, n in ipairs(boxes) do\n      if n.name == name and not taken[n.id] then\n        taken[n.id] = true\n        order[#order + 1] = { id = n.id, name = n.name }\n        break\n      end\n    end\n  end\n  local rest = {}\n  for _, n in ipairs(boxes) do\n    if not taken[n.id] then\n      rest[#rest + 1] = { id = n.id, name = n.name }\n    end\n  end\n  if params.random_order then\n    for i = #rest, 2, -1 do\n      local j = rand(1, i)\n      rest[i], rest[j] = rest[j], rest[i]\n    end\n  end\n  for _, box in ipairs(rest) do\n    order[#order + 1] = box\n  end\nend\n\nlocal function tell(i)\n  local word = { name = "pd", n = ver, of = #order, step = i }\n  if i < pos then\n    word.phase, word.team = "done", results[i]\n  elseif i == pos then\n    word.phase = "active"\n  else\n    word.phase = "wait"\n  end\n  word.done = pos - 1\n  field.send(order[i].id, "mode", word)\nend\n\nlocal function tell_all()\n  for i = 1, #order do\n    tell(i)\n  end\nend\n\nlocal function publish()\n  local box = order[pos]\n  fs.active = box and box.name or nil\n  fs.step = box and pos or 0\n  fs.of = #order\n  fs.done = pos - 1\n  fs.holder = owner\nend\n\nlocal function activate(i)\n  pos, owner, since, credited = i, nil, 0, 0\n  ver = ver + 1\n  publish()\n  tell_all()\n  emit("progressive.activated", { zone = order[i].name, step = i })\nend\n\nlocal function leader()\n  local best, tied\n  for team, points in pairs(field.score()) do\n    if best == nil or points > best.points then\n      best, tied = { team = team, points = points }, false\n    elseif points == best.points then\n      tied = true\n    end\n  end\n  return best and not tied and best.team or nil\nend\n\nlocal function finish(reason, team)\n  over = true\n  owner = nil\n  publish()\n  if team then\n    game.win(team)\n  else\n    game.finish(reason)\n  end\nend\n\nlocal function reached_target(team)\n  if params.target_score > 0 and field.score()[team] >= params.target_score then\n    log("progressive: " .. team .. " reached " .. params.target_score)\n    finish("target", team)\n    return true\n  end\n  return false\nend\n\nlocal function complete()\n  local team, box = owner, order[pos]\n  results[pos] = team\n  if params.complete_bonus > 0 then\n    score.add(team, params.complete_bonus, "progressive_complete")\n  end\n  emit("progressive.completed", { team = team, zone = box.name, step = pos })\n  if reached_target(team) then\n    return\n  end\n  if pos < #order then\n    activate(pos + 1)\n  else\n    pos, owner = #order + 1, nil\n    ver = ver + 1\n    tell_all()\n    finish("all_completed", leader())\n  end\nend\n\n-- Pays each full minute the holder has held the active box, and completes it.\nlocal function check()\n  if over or owner == nil or pos < 1 or pos > #order then\n    return\n  end\n  local minutes = math.floor((game.time() - since + 1e-6) / MINUTE_S)\n  while credited < minutes and credited < params.complete_min do\n    credited = credited + 1\n    if params.points_per_min > 0 then\n      score.add(owner, params.points_per_min, "progressive")\n      if reached_target(owner) then\n        return\n      end\n    end\n  end\n  if credited >= params.complete_min then\n    complete()\n  end\nend\n\non("game.start", function()\n  build_order()\n  if #order == 0 then\n    log("progressive: no box with the role zone joined")\n    return\n  end\n  activate(1)\nend)\n\non("zone.captured", function(e)\n  local box = order[pos]\n  if over or box == nil or e.node ~= box.id or e.team == nil or e.team == owner then\n    return\n  end\n  owner, since, credited = e.team, game.time(), 0\n  publish()\nend)\n\non("zone.neutralized", function(e)\n  local box = order[pos]\n  if over or box == nil or e.node ~= box.id or owner == nil then\n    return\n  end\n  owner, since, credited = nil, 0, 0\n  publish()\nend)\n\non("node.rebooted", function(e)\n  for i = 1, #order do\n    if order[i].id == e.node then\n      tell(i)\n    end\n  end\nend)\n\non("game.end", function()\n  over = true\nend)\n\nevery(1, check)\n\nevery(REMIND_S, function()\n  if not over and #order > 0 then\n    tell_all()\n  end\nend)\n',
    'assets/screens/captured.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the active box. Data: team, since (game time of its capture, in\n# seconds), step and of (its place in the order, and all the boxes), final (the\n# last box), held_min (full minutes held), need_min (minutes that complete it),\n# points (what those minutes paid), share (0-1 of the time that completes it),\n# taker and progress (0-1) while another team holds its input to take it over;\n# lang (pt, en, de or zh-tw) from the box.\ntemplate: captured\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{final && (lang == \'pt\' && \'ÚLTIMA CAIXA\' || lang == \'de\' && \'LETZTE BOX\' || lang == \'zh-tw\' && \'最後一個盒子\' || \'FINAL BOX\') || (lang == \'pt\' && \'CAIXA ATIVA\' || lang == \'de\' && \'AKTIVE BOX\' || lang == \'zh-tw\' && \'啟用中\' || \'ACTIVE BOX\')} {step}/{of}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{held_min} / {need_min} {lang == \'zh-tw\' && \'分鐘\' || \'min\'}  ·  {points} {lang == \'pt\' && \'pontos\' || lang == \'de\' && \'Punkte\' || lang == \'zh-tw\' && \'分\' || \'points\'}"\n    style: { font_size: 20 }\n  - type: progress_bar\n    value: "{share}"\n    style: { width: 220, height: 12, color: team }\n  - type: label\n    text: "{lang == \'pt\' && \'desde\' || lang == \'de\' && \'seit\' || lang == \'zh-tw\' && \'佔領於\' || \'held since\'} {since|clock}"\n    style: { font_size: 14, color: muted, visible: "{!taker}" }\n  - type: label\n    text: "{lang == \'pt\' && \'A tomar:\' || lang == \'de\' && \'Übernahme:\' || lang == \'zh-tw\' && \'奪取中\' || \'Taking:\'} {taker|upper}"\n    style: { font_size: 14, color: "{taker}", visible: "{taker}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Completa ao fim de \' || lang == \'de\' && \'Abgeschlossen nach \' || lang == \'zh-tw\' && \'滿 \' || \'Completes after \'}{need_min} {lang == \'zh-tw\' && \'分鐘即完成\' || \'min\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/completed.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A box a team completed: locked, its buttons do nothing. Data: team (the\n# team that completed it), step (its place in the order), of (all the boxes)\n# and done (boxes completed so far); lang (pt, en, de or zh-tw) from the box.\ntemplate: completed\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'CAIXA COMPLETA\' || lang == \'de\' && \'BOX ABGESCHLOSSEN\' || lang == \'zh-tw\' && \'盒子已完成\' || \'BOX COMPLETED\'} {step}/{of}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{lang == \'zh-tw\' && \'已完成 \' || \'\'}{done} {lang == \'pt\' && \'de\' || lang == \'de\' && \'von\' || lang == \'zh-tw\' && \'/\' || \'of\'} {of} {lang == \'pt\' && \'caixas completas\' || lang == \'de\' && \'Boxen abgeschlossen\' || lang == \'zh-tw\' && \'個盒子\' || \'boxes completed\'}"\n    style: { font_size: 20 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Bloqueada: já não pode ser capturada\' || lang == \'de\' && \'Gesperrt: nicht mehr einnehmbar\' || lang == \'zh-tw\' && \'已鎖定，無法再佔領\' || \'Locked: it cannot be captured again\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/inactive.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A box that is not the active one (not its turn yet, or told it is not\n# needed): its buttons do nothing and its LED is off. Data: done (boxes\n# completed so far) and of (all the boxes), both missing before the controller\'s\n# first word; lang (pt, en, de or zh-tw) from the box.\ntemplate: inactive\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'INATIVA\' || lang == \'de\' && \'INAKTIV\' || lang == \'zh-tw\' && \'未啟用\' || \'INACTIVE\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'AGUARDA\' || lang == \'de\' && \'WARTEN\' || lang == \'zh-tw\' && \'等待中\' || \'WAIT\'}"\n    style: { font_size: 48, color: muted }\n  - type: label\n    text: "{lang == \'pt\' && \'Ainda não é a vez desta caixa\' || lang == \'de\' && \'Diese Box ist noch nicht dran\' || lang == \'zh-tw\' && \'還沒輪到這個盒子\' || \'This box waits for its turn\'}"\n    style: { font_size: 20 }\n  - type: label\n    text: "{lang == \'zh-tw\' && \'已完成 \' || \'\'}{done} {lang == \'pt\' && \'de\' || lang == \'de\' && \'von\' || lang == \'zh-tw\' && \'/\' || \'of\'} {of} {lang == \'pt\' && \'caixas completas\' || lang == \'de\' && \'Boxen abgeschlossen\' || lang == \'zh-tw\' && \'個盒子\' || \'boxes completed\'}"\n    style: { font_size: 20, color: accent, visible: "{of}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Os botões não fazem nada agora\' || lang == \'de\' && \'Die Knöpfe tun gerade nichts\' || lang == \'zh-tw\' && \'現在按按鈕沒有作用\' || \'The buttons do nothing now\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/neutral.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The active box, nobody holds it (the name `neutral` is decision BN-11\'s, so a\n# box\'s OLED shows it as a free zone). Data: step (its place in the order) and\n# of (all the boxes), final (the last box), taker and progress (0-1) while a\n# team holds its input to take it; lang (pt, en, de or zh-tw) from the box.\ntemplate: neutral\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: accent }\n    children:\n      - type: label\n        text: "{final && (lang == \'pt\' && \'ÚLTIMA CAIXA\' || lang == \'de\' && \'LETZTE BOX\' || lang == \'zh-tw\' && \'最後一個盒子\' || \'FINAL BOX\') || (lang == \'pt\' && \'CAIXA ATIVA\' || lang == \'de\' && \'AKTIVE BOX\' || lang == \'zh-tw\' && \'啟用中\' || \'ACTIVE BOX\')} {step}/{of}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'LIVRE\' || lang == \'de\' && \'FREI\' || lang == \'zh-tw\' && \'中立\' || \'NEUTRAL\'}"\n    style: { font_size: 48 }\n  - type: label\n    text: "{lang == \'pt\' && \'A tomar:\' || lang == \'de\' && \'Übernahme:\' || lang == \'zh-tw\' && \'奪取中\' || \'Taking:\'} {taker|upper}"\n    style: { font_size: 20, color: "{taker}", visible: "{taker}" }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 220, height: 12, color: "{taker}", visible: "{taker}" }\n  - type: label\n    text: "{lang == \'pt\' && \'Mantém premido durante\' || lang == \'de\' && \'Halte deinen Knopf für\' || lang == \'zh-tw\' && \'按住按鈕\' || \'Hold your button for\'} {params.capture_hold_ms / 1000} {lang == \'zh-tw\' && \'秒\' || \'s\'}"\n    style: { font_size: 20, color: accent, visible: "{!taker}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Só esta caixa pode ser capturada\' || lang == \'de\' && \'Nur diese Box ist einnehmbar\' || lang == \'zh-tw\' && \'只有這個盒子能佔領\' || \'Only this box can be captured\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'respawn': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.respawn\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Respawn and Lives\ndescription: >-\n  A respawn point counts lives. Players scan their signed NFC tag (or press their team\'s button) to come\n  back into the game; each respawn takes a life from their team, or from the player with per-player\n  lives, and a player must wait a cooldown between respawns. When a team has no lives left, the next\n  respawn is refused and the team is eliminated.\nroles:\n  respawn: { requires: [nfc], optional: [team_input, display] }\nparams:\n  lives:              { type: int, min: 1, max: 1000, default: 20, label: "Lives: respawns per team, or per player with per-player lives" }\n  per_player:         { type: bool, default: false, label: "Count lives per player (needs NFC tags) instead of per team" }\n  respawn_cooldown_s: { type: int, min: 0, max: 600, default: 30, label: "Seconds a player waits between respawns" }\ni18n:\n  pt:\n    name: Reentradas e Vidas\n    description: >-\n      Um ponto de reentrada conta as vidas. Cada participante lê a sua etiqueta NFC assinada (ou carrega no\n      botão da sua equipa) para voltar ao jogo; cada reentrada gasta uma vida da equipa, ou da própria\n      pessoa com vidas individuais, e há um tempo de espera entre reentradas. Quando uma equipa fica sem\n      vidas, a reentrada seguinte é recusada e a equipa é eliminada.\n    params:\n      lives: "Vidas: reentradas por equipa, ou por pessoa com vidas individuais"\n      per_player: Contar as vidas por pessoa (precisa de etiquetas NFC) em vez de por equipa\n      respawn_cooldown_s: Segundos de espera entre reentradas de cada pessoa\n  de:\n    name: Respawn und Leben\n    description: >-\n      Ein Respawn-Punkt zählt Leben. Die Spielenden scannen ihren signierten NFC-Tag (oder drücken den Knopf\n      ihres Teams), um ins Spiel zurückzukehren; jeder Respawn kostet ihr Team ein Leben, bei Leben pro Person\n      die Person selbst, und zwischen zwei Respawns gilt eine Wartezeit. Hat ein Team keine Leben mehr, wird\n      der nächste Respawn abgelehnt und das Team scheidet aus.\n    params:\n      lives: "Leben: Respawns pro Team, oder pro Person bei Leben pro Person"\n      per_player: Leben pro Person zählen (braucht NFC-Tags) statt pro Team\n      respawn_cooldown_s: Sekunden Wartezeit zwischen zwei Respawns einer Person\n  zh-tw:\n    name: 復活與命數\n    description: 復活點會計算命數。玩家感應自己已簽署的 NFC 標籤（或按自己隊伍的按鈕）回到遊戲；每次復活扣該隊一條命，命數按玩家計算時則扣玩家自己的，兩次復活之間需要等待。隊伍沒有命數時，下一次復活會被拒絕，該隊淘汰。\n    params:\n      lives: 命數：每隊的復活次數，或命數按玩家計算時每位玩家的次數\n      per_player: 按玩家計算命數（需要 NFC 標籤），而不是按隊伍\n      respawn_cooldown_s: 每位玩家兩次復活之間的等待秒數\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Respawn and Lives: a respawn point counts lives. A player scans their\n-- signed NFC tag (protocol/nfc-tag.md), or presses their team\'s button, to\n-- come back into the game. Each respawn takes one of the team\'s `lives`, or\n-- one of the player\'s own with per_player. A player waits respawn_cooldown_s\n-- between respawns; button presses carry no player, so they only have a 2 s\n-- guard against double presses. When a team has no lives left, the next\n-- respawn is refused and team.eliminated is sent (once). Lives are counted on\n-- this box: give each team one respawn point, or share one.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\nlocal BUTTON_GUARD_S = 2\n\nlocal lives = {} -- team, or player with per_player -> lives left\nlocal last = {} -- player id, or "team:<team>" for buttons -> game time of the last respawn\nlocal out = {} -- team -> true once team.eliminated was sent\nlocal message, failed, fade\nlocal shown = { lives = params.lives }\n\nlocal function show()\n  ui.screen("respawn", {\n    team = shown.team,\n    player = shown.player,\n    lives = shown.lives,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the lives count, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\nlocal function lives_of(key)\n  if lives[key] == nil then\n    lives[key] = params.lives\n  end\n  return lives[key]\nend\n\nlocal function respawn(team, player)\n  if params.per_player and player == nil then\n    return say("Scan your tag", true)\n  end\n  if team == nil and not params.per_player then\n    return say("This tag has no team", true)\n  end\n  local who = player or ("team:" .. team)\n  local wait_s = player and params.respawn_cooldown_s or BUTTON_GUARD_S\n  local t = last[who]\n  if t and game.time() - t < wait_s then\n    return say("Wait " .. math.ceil(wait_s - (game.time() - t)) .. " s", true)\n  end\n  local key = params.per_player and player or team\n  shown.team, shown.player = team, player\n  shown.lives = lives_of(key)\n  if lives_of(key) <= 0 then\n    if not params.per_player and not out[team] then\n      out[team] = true\n      emit("team.eliminated", { team = team })\n    end\n    return say(params.per_player and "No lives left" or "No lives left: team out", true)\n  end\n  lives[key] = lives[key] - 1\n  last[who] = game.time()\n  shown.lives = lives[key]\n  emit("player.respawn", { team = team, player = player, lives_left = lives[key] })\n  say("Back in the game", false)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("respawn: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  respawn(e.team, e.player)\nend)\n\non("team_input.press", function(e)\n  respawn(e.team, nil)\nend)\n',
    'assets/screens/respawn.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The respawn point. Data: lives (left, for the last team or player),\n# team, player (the last respawn), message, error; lang (pt, de, zh-tw, else English)\n# from the box.\ntemplate: respawn\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'REENTRADA\' || lang == \'de\' && \'RESPAWN\' || lang == \'zh-tw\' && \'復活\' || \'RESPAWN\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lives}"\n    style: { font_size: 48, color: "{lives == 0 && \'danger\' || \'white\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'vidas restantes\' || lang == \'de\' && \'Leben übrig\' || lang == \'zh-tw\' && \'剩餘命數\' || \'lives left\'}"\n    style: { font_size: 20, color: muted, visible: "{!team && !player}" }\n  # The team\'s and the player\'s lives: Portuguese, German and English put the name last, Chinese\n  # first (a label of its own: a string of a chain holds no value to fill in).\n  - type: label\n    text: "{lang == \'pt\' && \'vidas de \' || lang == \'de\' && \'Leben für \' || \'lives left for \'}{team|upper}"\n    style: { font_size: 20, color: team, visible: "{team && !params.per_player && lang != \'zh-tw\'}" }\n  - type: label\n    text: "{team|upper} 隊剩餘命數"\n    style: { font_size: 20, color: team, visible: "{team && !params.per_player && lang == \'zh-tw\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'vidas de \' || lang == \'de\' && \'Leben für \' || \'lives left for \'}{player}"\n    style: { font_size: 20, color: muted, visible: "{player && params.per_player && lang != \'zh-tw\'}" }\n  - type: label\n    text: "{player} 的剩餘命數"\n    style: { font_size: 20, color: muted, visible: "{player && params.per_player && lang == \'zh-tw\'}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Lê a tua etiqueta para voltares ao jogo\' || lang == \'de\' && \'Scanne deinen Tag, um zurückzukehren\' || lang == \'zh-tw\' && \'感應你的標籤回到遊戲\' || \'Scan your tag to come back in\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'sabotage': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.sabotage\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Sabotage\ndescription: Bomb rounds until the game time runs out. Attackers arm the bomb, defenders defuse it; an explosion scores for the attackers, a defuse for the defenders, then the box rests and the next round starts. The team with more points wins.\nroles:\n  bomb: { requires: [team_input], optional: [keypad, audio, led, display] }\nparams:\n  attackers:          { type: team, default: red }\n  defenders:          { type: team, default: blue }\n  fuse_s:             { type: int, min: 10, max: 3600, default: 300, label: "Fuse (s)" }\n  arm_hold_ms:        { type: int, default: 5000, label: "Hold time to arm (ms)" }\n  defuse_hold_ms:     { type: int, default: 10000, label: "Hold time to defuse (ms)" }\n  pause_s:            { type: int, min: 0, max: 600, default: 10, label: "Pause between rounds (s)" }\n  game_time_min:      { type: int, min: 1, max: 600, default: 20, label: "Game time (min)" }\n  team_codes:         { type: string, optional: true, max: 60, gm_only: true, label: "Team codes, e.g. red=1234,blue=5678: the keypad arms (a team\'s code) and defuses (another team\'s code) instead of the buttons" }\ni18n:\n  pt:\n    name: Sabotagem\n    description: Rondas da bomba até acabar o tempo de jogo. Os atacantes armam a bomba, os defensores desarmam-na; uma explosão pontua para os atacantes, um desarme para os defensores; depois a caixa descansa e começa a ronda seguinte. Vence a equipa com mais pontos.\n    params:\n      attackers: Atacantes\n      defenders: Defensores\n      fuse_s: Rastilho (s)\n      arm_hold_ms: Tempo a premir para armar (ms)\n      defuse_hold_ms: Tempo a premir para desarmar (ms)\n      pause_s: Pausa entre rondas (s)\n      game_time_min: Tempo de jogo (min)\n      team_codes: "Códigos de equipa, ex.: red=1234,blue=5678: o teclado arma (o código de uma equipa) e desarma (o código de outra equipa) em vez dos botões"\n  de:\n    name: Sabotage\n    description: >-\n      Bombenrunden, bis die Spielzeit abläuft. Die Angreifenden machen die Bombe scharf, die Verteidigenden\n      entschärfen sie; eine Explosion zählt für die Angreifenden, eine Entschärfung für die Verteidigenden,\n      dann ruht die Box und die nächste Runde beginnt. Das Team mit mehr Punkten gewinnt.\n    params:\n      attackers: Angreifende\n      defenders: Verteidigende\n      fuse_s: Zünder (s)\n      arm_hold_ms: Haltezeit zum Schärfen (ms)\n      defuse_hold_ms: Haltezeit zum Entschärfen (ms)\n      pause_s: Pause zwischen den Runden (s)\n      game_time_min: Spielzeit (min)\n      team_codes: "Team-Codes, z. B. red=1234,blue=5678: das Tastenfeld macht scharf (der Code eines Teams) und entschärft (der Code eines anderen Teams) statt der Knöpfe"\n  zh-tw:\n    name: 破壞\n    description: 一回合接一回合，直到遊戲時間結束。進攻方啟動炸彈，防守方拆除；爆炸為進攻方得分，拆除為防守方得分，之後裝置休息，下一回合開始。得分較多的隊伍獲勝。\n    params:\n      attackers: 進攻方\n      defenders: 防守方\n      fuse_s: 引信（秒）\n      arm_hold_ms: 啟動需按住的時間（毫秒）\n      defuse_hold_ms: 拆除需按住的時間（毫秒）\n      pause_s: 回合間暫停（秒）\n      game_time_min: 遊戲時間（分鐘）\n      team_codes: 隊伍密碼，例如 red=1234,blue=5678：改用按鍵啟動（某一隊的密碼）與拆除（另一隊的密碼），不用按鈕\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Sabotage: Bomb / Rush rounds until the game time runs out. The attackers\n-- arm, the defenders defuse before the fuse runs out; an explosion scores a\n-- point for the attackers, a defuse one for the defenders, then the box shows\n-- the result, rests for params.pause_s and goes back to standby. At\n-- params.game_time_min the game ends and the team with more points wins (equal:\n-- a draw). A bomb still armed at that moment does not count (decision SAB-3).\n-- With team codes (params.team_codes, e.g. "red=1234,blue=5678") the keypad\n-- arms and defuses instead of the team buttons, as in Bomb.\n-- Phases: standby, armed, defused / exploded (the result, RESULT_S), pause.\n\nlocal RESULT_S = 5 -- how long the result of a round stays on the screen\n\nlocal s = state.node {\n  phase = "standby",\n  explode_at = 0,\n  resume_at = 0,\n  armed_by = nil,\n  defused_by = nil,\n  round = 0,\n  over = false,\n  last = "",\n}\nlocal fuse_timer, phase_timer\n\nlocal team_of = {} -- code -> team\nlocal use_codes = false\nfor team, code in string.gmatch(params.team_codes or "", "([^=,%s]+)=(%d+)") do\n  team_of[code] = team\n  use_codes = true\nend\n-- Scripts on this box that read keypad codes list a check here (see the\n-- Codes modifier), so a code meant for another script is not "wrong" here.\nkeypad_codes = keypad_codes or {}\nlocal function mine(c)\n  return team_of[c] ~= nil\nend\nif use_codes then\n  keypad_codes[#keypad_codes + 1] = mine\nend\nlocal typed = ""\nlocal typing -- while a code prompt is up: the timer that gives the screen back to the phase\nlocal note, note_failed -- the prompt\'s message\n-- How far the team holding its button now is with arming or defusing\n-- (0-1), nil while nobody holds: the phase screen shows it as it fills.\nlocal holding\n\nlocal limit_s = params.game_time_min * 60\n\n-- Draws the phase, or the code prompt while one is up (one function for every\n-- screen: each function costs the box\'s small Lua heap about a kilobyte).\nlocal function screen()\n  local a, d = score.get(params.attackers), score.get(params.defenders)\n  local now = game.time()\n  local game_left = math.max(0, math.ceil(limit_s - now))\n  local left = math.ceil(s.explode_at - now)\n  if typing then\n    ui.screen("code_entry", {\n      title = s.phase == "armed" and "DEFUSE" or "ARM",\n      digits = #typed,\n      message = note,\n      error = note_failed,\n      left = s.phase == "armed" and left or nil,\n    })\n  elseif s.phase == "standby" and use_codes then\n    local message = string.upper(params.attackers)\n      .. " "\n      .. a\n      .. " - "\n      .. d\n      .. " "\n      .. string.upper(params.defenders)\n    ui.screen("code_entry", { title = "ARM", digits = 0, message = message })\n  elseif s.phase == "standby" then\n    ui.screen("standby", {\n      arm = params.attackers,\n      defend = params.defenders,\n      progress = holding,\n      a_points = a,\n      d_points = d,\n      round = s.round + 1,\n      game_left = game_left,\n    })\n  elseif s.phase == "armed" then\n    ui.screen(\n      "countdown",\n      { left = left, team = use_codes and s.armed_by or nil, defuse = holding }\n    )\n  elseif s.phase == "defused" then\n    ui.screen("defused", { team = s.defused_by })\n  elseif s.phase == "exploded" then\n    ui.screen("exploded", { team = s.armed_by })\n  else\n    ui.screen("pause", {\n      a_points = a,\n      d_points = d,\n      attackers = params.attackers,\n      defenders = params.defenders,\n      left = math.max(0, math.ceil(s.resume_at - now)),\n      exploded = s.last == "exploded",\n      game_left = game_left,\n    })\n  end\nend\n\nlocal function show_phase()\n  if typing then\n    cancel(typing)\n  end\n  typed, typing = "", nil\n  if not s.over then\n    screen()\n  end\nend\n\n-- The next phase after a result: the pause (when params.pause_s is set), then standby.\nlocal function advance()\n  phase_timer = nil\n  if s.phase ~= "pause" and params.pause_s > 0 then\n    s.phase = "pause"\n    s.resume_at = game.time() + params.pause_s\n    phase_timer = after(params.pause_s, advance)\n  else\n    s.phase = "standby"\n  end\n  show_phase()\nend\n\n-- A round ended: the result on screen for RESULT_S, then the pause.\nlocal function end_round(result)\n  s.round = s.round + 1\n  s.phase = result\n  s.last = result\n  phase_timer = after(math.min(RESULT_S, math.max(params.pause_s, 1)), advance)\n  show_phase()\nend\n\nlocal function explode()\n  if s.over then\n    return\n  end\n  score.add(s.armed_by, 1, "sabotage")\n  audio.play("explosion")\n  emit("bomb.exploded", { team = s.armed_by }, { prio = "critical" })\n  end_round("exploded")\nend\n\nlocal function arm(team, how)\n  holding = nil\n  s.phase = "armed"\n  s.armed_by = team\n  s.explode_at = game.time() + params.fuse_s\n  -- The explosion is its own timer, so it lands exactly on time no matter\n  -- when the bomb was armed relative to the display tick below.\n  fuse_timer = after(params.fuse_s, explode)\n  audio.play("armed")\n  show_phase()\n  emit("bomb.armed", { team = team, fuse_s = params.fuse_s, reason = how }, { prio = "critical" })\nend\n\nlocal function defuse(team, how)\n  holding = nil\n  cancel(fuse_timer)\n  score.add(team, 1, "sabotage")\n  audio.play("defused")\n  s.defused_by = team\n  emit("bomb.defused", { team = team, reason = how }, { prio = "critical" })\n  end_round("defused")\nend\n\n-- The game\'s end: by the time limit (here) or from the console. The leader\n-- wins; a bomb still armed is dropped and scores nothing.\nlocal function finish()\n  if s.over then\n    return\n  end\n  s.over = true\n  if s.phase == "armed" then\n    cancel(fuse_timer)\n  end\n  local a, d = score.get(params.attackers), score.get(params.defenders)\n  ui.screen("game_over", {\n    winner = a > d and params.attackers or d > a and params.defenders or nil, -- nil: a draw\n    attackers = params.attackers,\n    defenders = params.defenders,\n    a_points = a,\n    d_points = d,\n  })\nend\n\non("game.end", finish)\n\non("game.start", screen)\n\n-- After a power loss a box picked for a game on its own gives the state back\n-- (decision HB-7): an armed bomb goes on with the fuse it had left (or\n-- explodes at once when it ran out meanwhile), a result or pause goes on with\n-- what it had left, and the screen shows the phase again. In a field game the\n-- state starts afresh: standby.\non("node.rebooted", function()\n  holding = nil\n  if s.over then\n    return finish()\n  end\n  if s.phase == "armed" then\n    local left = s.explode_at - game.time()\n    if left > 0 then\n      fuse_timer = after(left, explode)\n    else\n      return explode()\n    end\n  elseif s.phase == "defused" or s.phase == "exploded" then\n    phase_timer = after(1, advance)\n  elseif s.phase == "pause" then\n    phase_timer = after(math.max(0.1, s.resume_at - game.time()), advance)\n  end\n  show_phase()\nend)\n\non("team_input.hold", function(e)\n  if use_codes or s.over then\n    return\n  end\n  if s.phase == "standby" and e.team == params.attackers then\n    if e.ms >= params.arm_hold_ms then\n      arm(e.team)\n    else\n      holding = math.floor(e.ms * 100 / params.arm_hold_ms) / 100 -- hundredths: few distinct screens\n      screen()\n    end\n  elseif s.phase == "armed" and e.team == params.defenders then\n    if e.ms >= params.defuse_hold_ms then\n      defuse(e.team)\n    else\n      holding = math.floor(e.ms * 100 / params.defuse_hold_ms) / 100\n      screen()\n    end\n  end\nend)\n\n-- Letting go early empties the bar.\non("team_input.release", function(e)\n  if holding == nil then\n    return\n  end\n  local holder = (s.phase == "standby" and e.team == params.attackers)\n    or (s.phase == "armed" and e.team == params.defenders)\n  if holder then\n    holding = nil\n    show_phase()\n  end\nend)\n\n-- Team codes: the prompt shows the digits typed (and the fuse while armed).\nlocal function prompt(message, failed, linger_s)\n  note, note_failed = message, failed\n  if typing then\n    cancel(typing)\n  end\n  typing = after(linger_s, show_phase)\n  screen()\nend\n\non("keypad.key", function(e)\n  if not use_codes or s.over then\n    return\n  end\n  local k = e.key\n  if k == "#" then\n    local c, team = typed, team_of[typed]\n    typed = ""\n    if team == nil then\n      if c ~= "" and keypad_codes and #keypad_codes > 1 then\n        for _, knows in ipairs(keypad_codes) do\n          if knows ~= mine and knows(c) then\n            return show_phase() -- another script\'s code\n          end\n        end\n      end\n      return prompt("Wrong code", true, 3)\n    end\n    -- Fixed roles with codes too (SAB-1): only the attackers\' code arms, only the defenders\' defuses.\n    if s.phase == "standby" and team == params.attackers then\n      arm(team, "code")\n    elseif s.phase == "armed" and team == params.defenders then\n      defuse(team, "code")\n    elseif s.phase == "standby" or s.phase == "armed" then\n      prompt("Not your team\'s code", true, 3)\n    else\n      prompt("Next round soon", true, 3)\n    end\n  elseif k == "*" then\n    typed = ""\n    prompt(nil, false, 10)\n  elseif string.match(k or "", "^%d\$") and #typed < 8 then\n    typed = typed .. k\n    prompt(nil, false, 10)\n  end\nend)\n\n-- The time limit, by the game\'s clock (a timer made at load would start over\n-- after a power loss).\nevery(1, function()\n  if s.over then\n    return\n  end\n  if game.time() >= limit_s then\n    local a, d = score.get(params.attackers), score.get(params.defenders)\n    local winner = a > d and params.attackers or d > a and params.defenders or nil\n    if winner then\n      return game.win(winner)\n    end\n    return game.finish("draw")\n  end\n  if\n    s.phase == "armed"\n    or s.phase == "pause"\n    or (s.phase == "standby" and typing == nil and holding == nil)\n  then\n    screen()\n  end\nend)\n',
    'assets/screens/countdown.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Seconds left until the bomb explodes, red for the last ten.\n# Data: left (seconds), team (with team codes: the arming team), defuse (0-1\n# while the defenders hold their button: the defuse bar fills);\n# lang (pt, en, de or zh-tw) from the box.\ntemplate: countdown\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: danger }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'ARMADA\' || lang == \'de\' && \'SCHARF\' || lang == \'zh-tw\' && \'已啟動\' || \'ARMED\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    id: time_left\n    text: "{left|clock}"\n    style: { font_size: 48, color: "{left <= 10 && \'danger\' || \'white\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'até à explosão\' || lang == \'de\' && \'bis zur Explosion\' || lang == \'zh-tw\' && \'後引爆\' || \'until detonation\'}"\n    style: { font_size: 20, color: muted }\n  - type: progress_bar\n    id: fuse_bar\n    value: "{left / params.fuse_s}"\n    style: { width: 240, height: 10, color: "{team || \'danger\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'A desarmar... não largues\' || lang == \'de\' && \'Entschärfen... nicht loslassen\' || lang == \'zh-tw\' && \'拆除中，別放手\' || \'Defusing... keep holding\'}"\n    style:\n      font_size: 14\n      color: white\n      padding: { top: 8 }\n      visible: "{defuse}"\n  - type: progress_bar\n    id: defuse_bar\n    value: "{defuse}"\n    style: { width: 240, height: 12, color: "{params.defenders || \'blue\'}", visible: "{defuse}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Armada por\' || lang == \'de\' && \'Scharf gemacht von\' || lang == \'zh-tw\' && \'啟動隊伍\' || \'Armed by\'} {team|upper}"\n    style:\n      font_size: 14\n      color: team\n      visible: "{team}"\n      padding: { bottom: 10 }\n',
    'assets/screens/defused.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The bomb was defused: the whole screen in the scoring team\'s colour.\n# Data: team (the defusing team, which scores the round\'s point); lang (pt, en, de or zh-tw) from the box.\ntemplate: defused\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{lang == \'zh-tw\' && \'已拆除\' || \'DEFUSED\'}"\n    style: { font_size: 48, color: contrast, visible: "{lang != \'de\' && lang != \'pt\'}" }\n  # German\'s and Portuguese\'s words are wider than the screen at 48 px: 28.\n  - type: label\n    text: "{lang == \'pt\' && \'DESARMADA\' || \'ENTSCHÄRFT\'}"\n    style: { font_size: 28, color: contrast, visible: "{lang == \'de\' || lang == \'pt\'}" }\n  - type: label\n    text: "Point for team {team|upper}"\n    style: { font_size: 28, color: contrast, visible: "{team && lang != \'pt\' && lang != \'de\' && lang != \'zh-tw\'}" }\n  - type: label\n    text: "Ponto para {team|upper}"\n    style: { font_size: 28, color: contrast, visible: "{team && lang == \'pt\'}" }\n  - type: label\n    text: "Punkt für Team {team|upper}"\n    style: { font_size: 28, color: contrast, visible: "{team && lang == \'de\'}" }\n  - type: label\n    text: "{team|upper} 隊得分"\n    style: { font_size: 28, color: contrast, visible: "{team && lang == \'zh-tw\'}" }\n',
    'assets/screens/exploded.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The bomb exploded: the whole screen in the scoring team\'s colour.\n# Data: team (the arming team; the point goes to it); lang (pt, en, de or zh-tw) from the box.\ntemplate: exploded\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: warning\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{lang == \'pt\' && \'EXPLODIU\' || lang == \'zh-tw\' && \'已爆炸\' || \'EXPLODED\'}"\n    style: { font_size: 48, color: contrast, visible: "{lang != \'de\'}" }\n  # German\'s word is wider than the screen at 48 px: 28, as the box\'s own screen fits it.\n  - type: label\n    text: EXPLODIERT\n    style: { font_size: 28, color: contrast, visible: "{lang == \'de\'}" }\n  - type: label\n    text: "Point for team {team|upper}"\n    style: { font_size: 28, color: contrast, visible: "{team && lang != \'pt\' && lang != \'de\' && lang != \'zh-tw\'}" }\n  - type: label\n    text: "Ponto para {team|upper}"\n    style: { font_size: 28, color: contrast, visible: "{team && lang == \'pt\'}" }\n  - type: label\n    text: "Punkt für Team {team|upper}"\n    style: { font_size: 28, color: contrast, visible: "{team && lang == \'de\'}" }\n  - type: label\n    text: "{team|upper} 隊得分"\n    style: { font_size: 28, color: contrast, visible: "{team && lang == \'zh-tw\'}" }\n',
    'assets/screens/game_over.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The game\'s end: the winner in its colour, or a draw. Data: winner (the team\n# with more points; absent for a draw), attackers, defenders (the teams),\n# a_points and d_points (their points); lang (pt, en, de or zh-tw) from the box.\ntemplate: game_over\nstyle: { background: "{winner || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{lang == \'pt\' && \'FIM DE JOGO\' || lang == \'de\' && \'SPIELENDE\' || lang == \'zh-tw\' && \'遊戲結束\' || \'GAME OVER\'}"\n    style: { font_size: 28, color: contrast }\n  - type: label\n    text: "Vence a equipa {winner|upper}"\n    style: { font_size: 28, color: contrast, visible: "{winner && lang == \'pt\'}" }\n  - type: label\n    text: "Team {winner|upper} gewinnt"\n    style: { font_size: 28, color: contrast, visible: "{winner && lang == \'de\'}" }\n  - type: label\n    text: "{winner|upper} 隊獲勝"\n    style: { font_size: 28, color: contrast, visible: "{winner && lang == \'zh-tw\'}" }\n  - type: label\n    text: "{winner|upper} team wins"\n    style: { font_size: 28, color: contrast, visible: "{winner && lang != \'pt\' && lang != \'de\' && lang != \'zh-tw\'}" }\n  - type: label\n    text: "{lang == \'pt\' && \'EMPATE\' || lang == \'de\' && \'UNENTSCHIEDEN\' || lang == \'zh-tw\' && \'平手\' || \'DRAW\'}"\n    style: { font_size: 28, color: contrast, visible: "{!winner}" }\n  - type: label\n    text: "{attackers|upper} {a_points|int} : {d_points|int} {defenders|upper}"\n    style: { font_size: 20, color: contrast }\n',
    'assets/screens/pause.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The pause between two rounds. Data: attackers, defenders (the teams),\n# a_points and d_points (their points), left (seconds until the next round),\n# exploded (the round that ended exploded, else it was defused), game_left\n# (seconds of game time left); lang (pt, en, de or zh-tw) from the box.\ntemplate: pause\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'PAUSA\' || lang == \'de\' && \'PAUSE\' || lang == \'zh-tw\' && \'暫停\' || \'PAUSE\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{attackers|upper} {a_points|int} : {d_points|int} {defenders|upper}"\n    style: { font_size: 28, color: white }\n  - type: label\n    text: "{lang == \'pt\' && (exploded && \'A bomba explodiu\' || \'A bomba foi desarmada\') || lang == \'de\' && (exploded && \'Die Bombe ist explodiert\' || \'Die Bombe wurde entschärft\') || lang == \'zh-tw\' && (exploded && \'炸彈已爆炸\' || \'炸彈已拆除\') || (exploded && \'The bomb exploded\' || \'The bomb was defused\')}"\n    style: { font_size: 14, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Próxima ronda em\' || lang == \'de\' && \'Nächste Runde in\' || lang == \'zh-tw\' && \'下一回合\' || \'Next round in\'}"\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{left|clock}"\n    style: { font_size: 48, color: white }\n  - type: label\n    text: "{lang == \'pt\' && \'Tempo de jogo\' || lang == \'de\' && \'Spielzeit\' || lang == \'zh-tw\' && \'遊戲時間\' || \'Game time\'} {game_left|clock}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The bomb waits to be armed, with the score. Data: arm (the attacking team),\n# defend (the defending team), progress (0-1 while the attackers hold their\n# button; the bar fills, letting go empties it), a_points and d_points (the\n# teams\' points), round (the coming round), game_left (seconds of game time\n# left); lang (pt, en, de or zh-tw) from the box.\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'PRONTA\' || lang == \'de\' && \'BEREIT\' || lang == \'zh-tw\' && \'就緒\' || \'READY\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: label\n    text: "{arm|upper} {a_points|int} : {d_points|int} {defend|upper}"\n    style:\n      font_size: 20\n      color: white\n      padding: { top: 6 }\n  - type: label\n    text: "{lang == \'pt\' && \'Tempo de jogo\' || lang == \'de\' && \'Spielzeit\' || lang == \'zh-tw\' && \'遊戲時間\' || \'Game time\'} {game_left|clock}"\n    style: { font_size: 14, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && (progress && \'A armar... não largues\' || \'Mantém premido para armar\') || lang == \'de\' && (progress && \'Schärfen... nicht loslassen\' || \'Halten zum Schärfen\') || lang == \'zh-tw\' && (progress && \'啟動中，別放手\' || \'按住以啟動\') || (progress && \'Arming... keep holding\' || \'Hold to arm\')}"\n    style: { font_size: 20, color: "{progress && \'white\' || \'muted\'}", visible: "{arm}" }\n  - type: label\n    text: "{arm|upper}"\n    style: { font_size: 48, color: "{arm}", visible: "{arm}" }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 220, height: 12, color: "{arm}", visible: "{arm}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Ronda\' || lang == \'de\' && \'Runde\' || lang == \'zh-tw\' && \'回合\' || \'Round\'} {round|int}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'target_windows': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.target_windows\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Target Windows\ndescription: >-\n  A target lights up in a random team\'s colour for a few seconds; a hit while it is lit scores for that\n  team. Needs the target addon (a hit sensor and an LED ring).\nroles:\n  target: { requires: [hit, led], optional: [display, audio] }\nparams:\n  interval_s:   { type: int, min: 1, max: 3600, default: 20, label: "Seconds the target stays dark between windows" }\n  window_s:     { type: int, min: 1, max: 600,  default: 5,  label: "Seconds a window stays open" }\n  hit_points:   { type: int, min: 1, max: 1000, default: 5,  label: "Points for a hit in the window" }\n  min_strength: { type: int, min: 0, max: 255,  default: 40, label: "Weakest hit that counts (0-255)" }\n  multi_hit:    { type: bool, default: false, label: "Every hit in a window scores (otherwise the first hit closes it)" }\ni18n:\n  pt:\n    name: Janelas de Alvo\n    description: >-\n      Um alvo acende-se na cor de uma equipa ao acaso durante alguns segundos; um tiro enquanto está aceso\n      pontua para essa equipa. Precisa do módulo de alvo (um sensor de impacto e um anel de LED).\n    params:\n      interval_s: Segundos em que o alvo fica apagado entre janelas\n      window_s: Segundos que uma janela fica aberta\n      hit_points: Pontos por um tiro na janela\n      min_strength: Impacto mais fraco que conta (0-255)\n      multi_hit: Todos os tiros numa janela pontuam (senão, o primeiro fecha-a)\n  de:\n    name: Zielfenster\n    description: >-\n      Eine Zielscheibe leuchtet für ein paar Sekunden in der Farbe eines zufälligen Teams; ein Treffer,\n      solange sie leuchtet, punktet für dieses Team. Braucht das Ziel-Addon (ein Treffersensor und ein\n      LED-Ring).\n    params:\n      interval_s: Sekunden, die die Scheibe zwischen den Fenstern dunkel bleibt\n      window_s: Sekunden, die ein Fenster offen bleibt\n      hit_points: Punkte für einen Treffer im Fenster\n      min_strength: Schwächster Treffer, der zählt (0-255)\n      multi_hit: Jeder Treffer in einem Fenster punktet (sonst schließt der erste es)\n  zh-tw:\n    name: 標靶時窗\n    description: 標靶會隨機亮起某一隊的顏色幾秒鐘；亮著時命中就為該隊得分。需要標靶擴充模組（命中感測器與 LED 燈環）。\n    params:\n      interval_s: 兩個時窗之間標靶熄滅的秒數\n      window_s: 每個時窗開啟的秒數\n      hit_points: 時窗內命中的分數\n      min_strength: 計算命中的最小力道（0-255）\n      multi_hit: 時窗內每次命中都得分（否則第一次命中就關閉時窗）\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Target Windows, on each target (decision P4R4): the target stays dark for\n-- params.interval_s seconds, then lights up in a random team\'s colour (one of\n-- game.teams(), with the game\'s seeded rand(), so a replay picks the same\n-- teams) for params.window_s seconds. A hit (the hit capability\'s input\n-- hit.hit, with strength 0-255) of at least params.min_strength while the\n-- window is open scores params.hit_points for the window\'s team and logs\n-- target.hit with window_open = true; the first such hit closes the window\n-- unless params.multi_hit. A hit while the target is dark scores nothing and\n-- logs target.hit with window_open = false. Weaker hits are ignored. The\n-- target is armed (it reports hits) from the start of the game to its end.\n-- Owner overrides (cmd.set_owner) mean nothing here and are ignored.\n-- Screens (assets/screens/): standby while dark (with the last scoring hit),\n-- window while open; final_score at the end (the Field Box\'s built-in screen).\n\nlocal s = state.node { team = nil, left = 0, last_team = nil, hits = 0 }\nlocal timer = nil -- the timer that opens or closes the next window\nlocal tick = nil -- the per-second countdown while a window is open\nlocal running = false\n\nlocal function show()\n  if s.team then\n    ui.screen("window", { team = s.team, left = s.left })\n  else\n    ui.screen("standby", { team = s.last_team, hits = s.hits })\n  end\nend\n\nlocal open_window\n\nlocal function close_window()\n  if tick then\n    cancel(tick)\n    tick = nil\n  end\n  if timer then\n    cancel(timer)\n    timer = nil\n  end\n  s.team = nil\n  cap("ring"):off()\n  show()\n  if running then\n    timer = after(params.interval_s, open_window)\n  end\nend\n\nopen_window = function()\n  timer = nil\n  local teams = game.teams()\n  if #teams == 0 then\n    return\n  end\n  s.team = teams[rand(1, #teams)]\n  s.left = params.window_s\n  cap("ring"):fill(s.team)\n  audio.play("window")\n  show()\n  timer = after(params.window_s, close_window)\n  tick = every(1, function()\n    if s.left > 1 then\n      s.left = s.left - 1\n      show()\n    end\n  end)\nend\n\non("game.start", function()\n  if running then\n    return\n  end\n  running = true\n  cap("hit"):arm()\n  show()\n  timer = after(params.interval_s, open_window)\nend)\n\non("hit.hit", function(e)\n  local strength = tonumber(e.strength) or 0\n  if not running or strength < params.min_strength then\n    return\n  end\n  local team = s.team\n  if team == nil then\n    emit("target.hit", { window_open = false })\n    return\n  end\n  emit("target.hit", { team = team, window_open = true })\n  score.add(team, params.hit_points, "target")\n  s.last_team, s.hits = team, s.hits + 1\n  audio.play("hit")\n  if not params.multi_hit then\n    close_window()\n  end\nend)\n\non("game.end", function()\n  running = false\n  if tick then\n    cancel(tick)\n    tick = nil\n  end\n  if timer then\n    cancel(timer)\n    timer = nil\n  end\n  s.team = nil\n  cap("hit"):disarm()\n  cap("ring"):off()\n  ui.screen("final_score", {})\nend)\n',
    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The target is dark between windows. Data: team (the team of the last\n# scoring hit, if any) and hits (scoring hits on this target so far);\n# lang (pt, en, de or zh-tw) from the box.\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{lang == \'pt\' && \'ALVO\' || lang == \'de\' && \'ZIELSCHEIBE\' || lang == \'zh-tw\' && \'標靶\' || \'TARGET\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'À ESPERA\' || lang == \'de\' && \'WARTEN\' || lang == \'zh-tw\' && \'待命\' || \'STAND BY\'}"\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: "{lang == \'pt\' && \'Espera pela tua cor\' || lang == \'de\' && \'Warte auf deine Farbe\' || lang == \'zh-tw\' && \'等你的顏色亮起\' || \'Wait for your colour\'}"\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{lang == \'pt\' && \'Último acerto\' || lang == \'de\' && \'Letzter Treffer\' || lang == \'zh-tw\' && \'上次命中\' || \'Last hit\'}{lang == \'zh-tw\' && \'：\' || \': \'}{team|upper}"\n    style: { font_size: 20, color: team, visible: "{team}" }\n  - type: label\n    text: "{hits} {lang == \'pt\' && \'acertos que contam\' || lang == \'de\' && \'Treffer mit Punkten\' || lang == \'zh-tw\' && \'次有效命中\' || \'scoring hits\'}"\n    style: { font_size: 14, color: muted, visible: "{hits > 0}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'Acerta no alvo enquanto mostra a tua cor\' || lang == \'de\' && \'Triff, solange sie deine Farbe zeigt\' || lang == \'zh-tw\' && \'標靶亮你的顏色時射擊\' || \'Hit the target while it shows your colour\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/window.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A scoring window is open. Data: team (whose window it is) and left (seconds\n# until it closes); lang (pt, en, de or zh-tw) from the box.\ntemplate: window\nstyle: { background: team }\nlayout:\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lang == \'pt\' && \'ACERTA\' || lang == \'de\' && \'TREFFEN\' || lang == \'zh-tw\' && \'射擊！\' || \'HIT IT\'}"\n    style: { font_size: 28, color: contrast }\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: "{left} s"\n    style: { font_size: 28, color: contrast }\n  - type: spacer\n    height: fill\n',
  },
  'vip_payload': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.vip_payload\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: VIP / Payload\ndescription: >-\n  One team escorts its VIP, a player who shares their position, or a payload, a phone with GPS, to an\n  extraction zone; the other teams try to stop them. Reaching the zone scores and can end the game.\n  Checkpoint boxes along the way are captured as in Domination and score while a team holds them.\nroles:\n  checkpoint: { requires: [team_input], optional: [team_display, display, audio] }\n  payload:    { requires: [gps], optional: [display, audio] }\nparams:\n  vip_team:          { type: team, default: red, label: "Team that escorts the VIP and the payload" }\n  extraction:        { type: string, optional: true, max: 28, label: "Centre of the extraction zone, latitude,longitude in degrees, e.g. 38.722345,-9.139312 (empty: no extraction)" }\n  radius_m:          { type: int, min: 10, max: 1000, default: 25, label: "Radius of the extraction zone (m)" }\n  vip_points:        { type: int, min: 0, max: 1000, default: 100, label: "Points for the escorting team at the extraction" }\n  end_on_extract:    { type: bool, default: true, label: "The extraction ends the game, won by the escorting team" }\n  checkpoint_points: { type: int, min: 0, max: 1000, default: 1, label: "Points per tick for the team holding a checkpoint (0: none)" }\n  tick_s:            { type: int, min: 1, max: 600, default: 10, label: "Seconds per scoring tick of a checkpoint" }\n  capture_hold_ms:   { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture a checkpoint (ms)" }\n  lang:              { type: string, default: "", max: 5, label: "Language of the screens: pt, en, de or zh-tw (empty: the game\'s language)" }\ni18n:\n  pt:\n    name: VIP / Carga\n    description: >-\n      Uma equipa escolta o seu VIP, quem partilha a sua posição, ou uma carga, um telemóvel com GPS, até\n      uma zona de extração; as outras equipas tentam impedi-lo. Chegar à zona dá pontos e pode acabar o\n      jogo. Os pontos de controlo pelo caminho capturam-se como no Domínio e dão pontos enquanto uma\n      equipa os tiver.\n    params:\n      vip_team: Equipa que escolta o VIP e a carga\n      extraction: "Centro da zona de extração, latitude,longitude em graus, ex.: 38.722345,-9.139312 (vazio: sem extração)"\n      radius_m: Raio da zona de extração (m)\n      vip_points: Pontos para a equipa que escolta, na extração\n      end_on_extract: A extração acaba o jogo, ganho pela equipa que escolta\n      checkpoint_points: "Pontos por intervalo para a equipa que tem um ponto de controlo (0: nenhum)"\n      tick_s: Segundos por intervalo de um ponto de controlo\n      capture_hold_ms: Tempo a premir para capturar um ponto de controlo (ms)\n      lang: "Língua dos ecrãs: pt, en, de ou zh-tw (vazio: a língua do jogo)"\n  de:\n    name: VIP / Payload\n    description: >-\n      Ein Team eskortiert seinen VIP, eine Person, die ihre Position teilt, oder ein Payload, ein Handy mit\n      GPS, zu einer Extraktionszone; die anderen Teams versuchen, es zu verhindern. Das Erreichen der Zone\n      bringt Punkte und kann das Spiel beenden. Checkpoint-Boxen unterwegs werden eingenommen wie bei\n      Domination und punkten, solange ein Team sie hält.\n    params:\n      vip_team: Team, das den VIP und das Payload eskortiert\n      extraction: "Mitte der Extraktionszone, Breite,Länge in Grad, z. B. 38.722345,-9.139312 (leer: keine Extraktion)"\n      radius_m: Radius der Extraktionszone (m)\n      vip_points: Punkte für das eskortierende Team bei der Extraktion\n      end_on_extract: Die Extraktion beendet das Spiel, gewonnen vom eskortierenden Team\n      checkpoint_points: "Punkte pro Intervall für das Team, das einen Checkpoint hält (0: keine)"\n      tick_s: Sekunden pro Wertungsintervall eines Checkpoints\n      capture_hold_ms: Haltezeit zum Einnehmen eines Checkpoints (ms)\n      lang: "Sprache der Bildschirme: pt, en, de oder zh-tw (leer: die Sprache des Spiels)"\n  zh-tw:\n    name: VIP / 護送\n    description: 一隊護送自己的 VIP（分享位置的玩家）或護送目標（有 GPS 的手機）到撤離區；其他隊伍設法阻止。抵達撤離區可得分，也可以結束遊戲。沿途的檢查點盒子像佔點模式一樣佔領，佔有期間持續得分。\n    params:\n      vip_team: 護送 VIP 與護送目標的隊伍\n      extraction: 撤離區中心，緯度,經度（度），例如 38.722345,-9.139312（空白：不撤離）\n      radius_m: 撤離區半徑（公尺）\n      vip_points: 撤離時護送隊伍得到的分數\n      end_on_extract: 撤離即結束遊戲，由護送隊伍獲勝\n      checkpoint_points: 佔有檢查點的隊伍每次計分的分數（0：無）\n      tick_s: 檢查點的計分間隔（秒）\n      capture_hold_ms: 佔領檢查點需按住的時間（毫秒）\n      lang: 畫面的語言：pt、en、de 或 zh-tw（留空：使用遊戲的語言）\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- VIP / Payload, on each node. Two roles run this script:\n--\n-- * checkpoint: a team captures the box by holding its input, as in\n--   Domination. Boxes do not score: the controller\'s field.lua scores the\n--   holder of each checkpoint every params.tick_s seconds.\n-- * payload: an Android prop with GPS. The app gives it gps.fix (lat, lon,\n--   acc) from the phone\'s location; it checks the extraction zone itself with\n--   geo.in_zone() and emits only vip.extracted, once: positions never leave\n--   the phone (decision P4R6). Its screen shows the metres left to the zone.\n--\n-- A script does not know its role: only a role that uses gps gets gps.fix (the\n-- app sends one without lat and lon when the game starts, before the phone\'s\n-- first fix), and team inputs reach only checkpoints, so each part answers its\n-- own inputs (decision M5-5). Screens (assets/screens/): checkpoint_free,\n-- checkpoint_held, payload; final_score at the end (the Field Box\'s built-in).\n\nlocal s = state.node { owner = nil, since = 0, extracted = false }\nlocal payload = false -- set by the first gps.fix: this node is the payload\n\n-- "lat,lon" in degrees; nil when empty or unreadable (field.lua refuses those at load).\nlocal zone\ndo\n  local lat, lon =\n    string.match(params.extraction or "", "^%s*([%-+]?[%d.]+)%s*,%s*([%-+]?[%d.]+)%s*\$")\n  lat, lon = tonumber(lat), tonumber(lon)\n  if lat and lon and lat >= -90 and lat <= 90 and lon >= -180 and lon <= 180 then\n    zone = { type = "circle", lat = lat + 0.0, lon = lon + 0.0, radius_m = params.radius_m }\n  end\nend\n\nlocal function show()\n  if s.owner then\n    ui.screen("checkpoint_held", { team = s.owner, since = s.since })\n  else\n    ui.screen("checkpoint_free", {})\n  end\nend\n\nlocal function show_payload(state, metres)\n  ui.screen("payload", { team = params.vip_team, state = state, metres = metres })\nend\n\non("game.start", show)\n\n-- Checkpoints.\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  show()\nend\n\non("team_input.hold", function(e)\n  if not payload and e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override: a team, or none to free the checkpoint.\non("cmd.set_owner", function(e)\n  if payload then\n    return\n  end\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\n-- The payload.\n\non("gps.fix", function(e)\n  payload = true\n  if s.extracted then\n    return\n  end\n  if zone == nil then\n    return show_payload("no_zone", 0)\n  end\n  if type(e.lat) ~= "number" or type(e.lon) ~= "number" then\n    return show_payload("searching", 0)\n  end\n  -- A fix less precise than the zone\'s radius could put the payload in it by chance.\n  if type(e.acc) == "number" and e.acc > params.radius_m then\n    return show_payload("weak", math.floor(e.acc))\n  end\n  if geo.in_zone(e.lat, e.lon, zone) then\n    s.extracted = true\n    emit("vip.extracted", { team = params.vip_team })\n    audio.play("captured")\n    return show_payload("extracted", 0)\n  end\n  show_payload("moving", math.ceil(geo.distance(e.lat, e.lon, zone.lat, zone.lon) - zone.radius_m))\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- VIP / Payload, on the field controller.\n--\n-- * The VIP: the controller hands this script position.fix (player, team,\n--   role, lat, lon, acc, src) for each new position report of a player whose\n--   check-in role is vip, and to no other script (decision P4R6). A fix of the\n--   escorting team\'s VIP inside the extraction zone extracts it: vip.extracted\n--   with the player. A fix less precise than the zone\'s radius does not count.\n--   Coordinates stay here: never in an event, a log line or state.field.\n-- * The payload: its own phone checks the zone and emits vip.extracted; this\n--   script takes that as the extraction (and emits nothing more).\n-- * The extraction, once per game: params.vip_points for the escorting team,\n--   and with params.end_on_extract the game ends, won by that team.\n-- * Checkpoints: every second, the holder of each checkpoint (the boxes\' own\n--   reports, field.owner) is counted; a team that has held one for\n--   params.tick_s seconds in a row scores params.checkpoint_points, and counts\n--   again from zero.\n\nlocal fs = state.field { extracted = false, by = nil }\n\n-- "lat,lon" in degrees. A malformed one stops the game from starting, with this message.\nlocal zone\nif params.extraction ~= nil and params.extraction ~= "" then\n  local lat, lon = string.match(params.extraction, "^%s*([%-+]?[%d.]+)%s*,%s*([%-+]?[%d.]+)%s*\$")\n  lat, lon = tonumber(lat), tonumber(lon)\n  if not (lat and lon and lat >= -90 and lat <= 90 and lon >= -180 and lon <= 180) then\n    error("extraction: latitude,longitude in degrees, e.g. 38.722345,-9.139312", 0)\n  end\n  zone = { type = "circle", lat = lat + 0.0, lon = lon + 0.0, radius_m = params.radius_m }\nend\n\nlocal function extract(by, player)\n  fs.extracted = true\n  fs.by = by\n  if by == "vip" then\n    emit("vip.extracted", { team = params.vip_team, player = player })\n  end\n  if params.vip_points > 0 then\n    score.add(params.vip_team, params.vip_points, "extraction")\n  end\n  if params.end_on_extract then\n    game.win(params.vip_team)\n  end\nend\n\non("position.fix", function(e)\n  if fs.extracted or zone == nil or e.role ~= "vip" or e.team ~= params.vip_team then\n    return\n  end\n  if type(e.lat) ~= "number" or type(e.lon) ~= "number" then\n    return\n  end\n  if type(e.acc) == "number" and e.acc > params.radius_m then\n    return\n  end\n  if geo.in_zone(e.lat, e.lon, zone) then\n    extract("vip", type(e.player) == "string" and e.player or nil)\n  end\nend)\n\n-- From the payload prop, which checked the zone itself.\non("vip.extracted", function(e)\n  if not fs.extracted and e.team == params.vip_team then\n    extract("payload")\n  end\nend)\n\nlocal held = {} -- checkpoint node id -> { team, s }\n\nevery(1, function()\n  if params.checkpoint_points <= 0 then\n    return\n  end\n  for _, n in ipairs(field.nodes("checkpoint")) do\n    local owner = field.owner(n.id)\n    local h = held[n.id]\n    if owner == nil then\n      held[n.id] = nil\n    elseif h == nil or h.team ~= owner then\n      held[n.id] = { team = owner, s = 0 }\n    else\n      h.s = h.s + 1\n      if h.s >= params.tick_s then\n        h.s = 0\n        score.add(owner, params.checkpoint_points, "checkpoint")\n      end\n    end\n  end\nend)\n',
    'assets/screens/checkpoint_free.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the checkpoint. No data; the hold time comes from the game\'s\n# parameters. Texts in params.lang (pt, the default, en, de or zh-tw).\ntemplate: checkpoint_free\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'CHECKPOINT\' || params.lang == \'de\' && \'CHECKPOINT\' || params.lang == \'zh-tw\' && \'檢查點\' || \'PONTO DE CONTROLO\'}"\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'HOLD TO CAPTURE\' || params.lang == \'de\' && \'GEDRÜCKT HALTEN\' || params.lang == \'zh-tw\' && \'按住以佔領\' || \'MANTÉM PREMIDO\'}"\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: "{params.lang == \'en\' && \'Hold your button for\' || params.lang == \'de\' && \'Halte deinen Knopf\' || params.lang == \'zh-tw\' && \'按住按鈕\' || \'o botão\'} {params.capture_hold_ms / 1000} {params.lang == \'en\' && \'s\' || params.lang == \'de\' && \'s lang\' || params.lang == \'zh-tw\' && \'秒\' || \'s para capturar\'}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Nobody holds this checkpoint\' || params.lang == \'de\' && \'Kein Team hält diesen Checkpoint\' || params.lang == \'zh-tw\' && \'目前沒有隊伍佔領此檢查點\' || \'Ninguém tem este ponto\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/checkpoint_held.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the checkpoint. Data: team, since (game time of the capture,\n# in seconds). The box does not score: the controller does, while it is held.\n# Texts in params.lang (pt, the default, en, de or zh-tw).\ntemplate: checkpoint_held\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'CHECKPOINT HELD\' || params.lang == \'de\' && \'CHECKPOINT BESETZT\' || params.lang == \'zh-tw\' && \'檢查點已佔領\' || \'PONTO CAPTURADO\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{params.lang == \'en\' && \'held since\' || params.lang == \'de\' && \'seit\' || params.lang == \'zh-tw\' && \'佔領於\' || \'desde\'} {since|clock}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Hold your button to take it over\' || params.lang == \'de\' && \'Halte den Knopf zum Übernehmen\' || params.lang == \'zh-tw\' && \'按住你的按鈕即可奪取\' || \'Mantém o teu botão para o tomar\'}"\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/payload.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The payload prop (a phone with GPS). Data: team (the escorting team),\n# state (searching: no fix yet; weak: the fix is less precise than the zone,\n# metres is its accuracy; no_zone: the game has no extraction zone; moving:\n# metres is the distance to the zone\'s edge; extracted), metres. Texts in\n# params.lang (pt, the default, en, de or zh-tw). Nothing here says where the\n# zone or the phone is.\ntemplate: payload\nstyle: { background: "{state == \'extracted\' && team || \'background\'}" }\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: "{params.lang == \'en\' && \'PAYLOAD\' || params.lang == \'de\' && \'PAYLOAD\' || params.lang == \'zh-tw\' && \'護送目標\' || \'CARGA\'}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: icon\n    icon: gps\n    style: { font_size: 48, color: muted, visible: "{state == \'searching\' || state == \'weak\'}" }\n  - type: label\n    text: "{metres} m"\n    style: { font_size: 48, color: accent, visible: "{state == \'moving\'}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'to the extraction zone\' || params.lang == \'de\' && \'bis zur Extraktionszone\' || params.lang == \'zh-tw\' && \'距離撤離區\' || \'até à zona de extração\'}"\n    style: { font_size: 20, color: muted, visible: "{state == \'moving\'}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'Looking for GPS\' || params.lang == \'de\' && \'Suche GPS\' || params.lang == \'zh-tw\' && \'搜尋 GPS 中\' || \'À procura de GPS\'}"\n    style: { font_size: 28, visible: "{state == \'searching\'}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'Weak GPS\' || params.lang == \'de\' && \'GPS schwach\' || params.lang == \'zh-tw\' && \'GPS 訊號弱\' || \'GPS fraco\'} ({metres} m)"\n    style: { font_size: 28, color: orange, visible: "{state == \'weak\'}" }\n  - type: label\n    text: "{params.lang == \'en\' && \'No extraction zone\' || params.lang == \'de\' && \'Keine Extraktion\' || params.lang == \'zh-tw\' && \'沒有撤離區\' || \'Sem zona de extração\'}"\n    style: { font_size: 28, color: muted, visible: "{state == \'no_zone\'}" }\n  - type: icon\n    icon: ok\n    style: { font_size: 48, color: contrast, visible: "{state == \'extracted\'}" }\n  - type: label\n    text: "{params.lang == \'de\' && \'EXTRAHIERT\' || params.lang == \'zh-tw\' && \'撤離成功\' || \'EXTRAÇÃO CONCLUÍDA\'}"\n    style: { font_size: 20, color: contrast, visible: "{state == \'extracted\' && params.lang != \'en\'}" }\n  - type: label\n    text: "EXTRACTED"\n    style: { font_size: 28, color: contrast, visible: "{state == \'extracted\' && params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{params.lang == \'en\' && \'Take me to the extraction zone\' || params.lang == \'de\' && \'Bring mich zur Extraktionszone\' || params.lang == \'zh-tw\' && \'把我帶到撤離區\' || \'Leva-me à zona de extração\'}"\n    style:\n      font_size: 14\n      color: muted\n      visible: "{state != \'extracted\'}"\n      padding: { bottom: 10 }\n',
  },
};
